window.LK_VEHICULES = [{"id":"albany-emperor","nom":"Emperor","marque":"Albany","cat":"berline","st":"vu","insp":"Cadillac Sedan de Ville 1977-1980","src":"Capturas oficiais","search":"albany emperor cadillac sedan de ville 1977-1980","txt":"A Albany sempre foi a marca dos grandes carrões americanos de luxo, e o Emperor é o arquétipo disso: capô comprido, coluna traseira grossa, suspensão macia. O Cadillac Sedan de Ville de 1977 a 1980, do qual ele herda o visual, era um carro de patrão já envelhecido, que com os anos virou o sedã de segunda mão por excelência, aquele que a gente encontra enferrujado nos bairros populares. As capturas divulgadas pela Rockstar mostram o carro estacionado junto a uma calçada de Vice City.","reel":"https://www.google.com/search?tbm=isch&q=Cadillac%20Sedan%20de%20Ville","reelNom":"Cadillac Sedan de Ville","slot":"americain","thumb":"/img/schemas/albany-emperor.svg"},{"id":"albany-primo","nom":"Primo","marque":"Albany","cat":"berline","st":"vu","insp":"Pontiac Bonneville do fim dos anos 80","src":"Primeiro trailer","search":"albany primo pontiac bonneville fin des annees 80","txt":"O Primo tem um lugar especial na série: sedã sem prestígio, mas de mecânica confiável, ele é a base preferida de quem curte customizar. O Pontiac Bonneville do fim dos anos 80 que o inspira era um grande carro americano de série, produzido em massa e revendido barato uma década depois, o que fez dele uma base perfeita para a cultura lowrider do sul da Flórida. O primeiro trailer o mostra passando numa cena de rua.","reel":"https://www.google.com/search?tbm=isch&q=Pontiac%20Bonneville%20fin%20des%20ann%C3%A9es%2080","reelNom":"Pontiac Bonneville do fim dos anos 80","slot":"americain","thumb":"/img/schemas/albany-primo.svg"},{"id":"albany-primo-custom","nom":"Primo Custom","marque":"Albany","cat":"berline","st":"comm","insp":"Buick Regal","src":"Comparação da comunidade","search":"albany primo custom buick regal","txt":"Mesma carroceria do Primo, em versão lowrider: suspensão rebaixada, rodas raiadas finas, pintura com efeito. É a variante que mais combina com Vice City, onde a cena lowrider cubana e porto-riquenha é uma marca cultural forte. A oficina Rideout Customs, que está no nosso mapa, é o tipo de lugar onde uma preparação dessas seria feita. Modelo não confirmado pela Rockstar para Leonida.","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Regal","reelNom":"Buick Regal","slot":"americain","thumb":"/img/schemas/albany-primo-custom.svg"},{"id":"benefactor-schafter-v12","nom":"Schafter V12","marque":"Benefactor","cat":"berline","st":"vu","insp":"Brabus E V12","src":"Primeiro trailer","search":"benefactor schafter v12 brabus e v12","txt":"O Schafter V12 é um sedã esportivo da Benefactor. A comparação escolhida aqui é com o Brabus E V12. Ele foi catalogado a partir do primeiro trailer, com uma identificação da comunidade; a Rockstar não divulga o nome dele ali.","reel":"https://www.google.com/search?tbm=isch&q=Brabus%20E%20V12","reelNom":"Brabus E V12","thumb":"/img/schemas/benefactor-schafter-v12.svg"},{"id":"karin-asterope","nom":"Asterope","marque":"Karin","cat":"berline","st":"comm","insp":"Toyota Camry da geração anterior","txt":"Sedã familiar japonês, o carro mais vendido do seu segmento nos Estados Unidos durante décadas. A variante GZ, mais recente, já está nesta base de dados.","search":"karin asterope toyota camry generation precedente","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20Camry%20pr%C3%A9c%C3%A9dente","reelNom":"Toyota Camry da geração anterior","slot":"japonais","thumb":"/img/schemas/karin-asterope.svg"},{"id":"karin-asterope-gz","nom":"Asterope GZ","marque":"Karin","cat":"berline","st":"vu","insp":"Toyota Camry (XV30)","src":"Capturas oficiais","search":"karin asterope gz toyota camry (xv30)","txt":"A Karin é a marca japonesa popular do universo GTA, e o Asterope é o carro do cidadão comum. O Toyota Camry que o inspira é o sedã mais vendido dos Estados Unidos há décadas, justamente porque não chama atenção. O sufixo GZ sugere um acabamento um pouco mais caprichado. Ele aparece nas capturas oficiais, perdido no trânsito do dia a dia de Leonida.","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20Camry%20(XV30)","reelNom":"Toyota Camry (XV30)","slot":"japonais","thumb":"/img/schemas/karin-asterope-gz.svg"},{"id":"lampadati-feroci","nom":"Feroci","marque":"Karin","cat":"berline","st":"vu","insp":"Lexus GS 300 de primeira geração","txt":"O Feroci segue o Lexus GS 300 de primeira geração, desenhado por Giugiaro e lançado em 1993. Foi a tentativa da Toyota de emplacar um sedã esportivo de luxo contra os alemães: construção impecável, seis cilindros em linha e uma discrição que lhe custou a carreira comercial. A Karin é a Toyota do universo GTA, o que torna a atribuição coerente.","search":"karin feroci lexus gs 300 premiere generation","src":"Extended Look","reel":"https://www.google.com/search?tbm=isch&q=Lexus%20GS%20300","reelNom":"Lexus GS 300","slot":"japonais","thumb":"/img/schemas/lampadati-feroci.svg"},{"id":"karin-intruder","nom":"Intruder","marque":"Karin","cat":"berline","st":"vu","insp":"Infiniti Q45/I30","src":"Primeiro trailer","search":"karin intruder infiniti q45/i30","txt":"O Intruder segue o Infiniti Q45 e o I30, os sedãs de luxo que a Nissan lançou nos Estados Unidos para enfrentar a Lexus. A aposta nunca pegou de verdade: bem construídos, confortáveis, mas sem uma identidade forte diante dos alemães. Resultado: hoje eles aparecem usados e baratos, exatamente o tipo de carro que lota os estacionamentos de Vice City sem que ninguém olhe para ele.","reel":"https://www.google.com/search?tbm=isch&q=Infiniti%20Q45%2FI30","reelNom":"Infiniti Q45/I30","slot":"japonais","thumb":"/img/schemas/karin-intruder.svg"},{"id":"audi-a7-rs7","nom":"A7 RS7","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Audi RS7 de segunda geração","src":"Primeiro trailer","txt":"Sedã-cupê alemão de alto desempenho, com quatro portas e teto de caimento suave. O RS7 é o arquétipo do carro rápido que passa despercebido: quinhentos cavalos sob a carroceria de um sedã de gerente comercial. Nome no jogo não divulgado.","search":"marque inconnue a7 rs7 audi rs7 deuxieme generation","reel":"https://www.google.com/search?tbm=isch&q=Audi%20RS7","reelNom":"Audi RS7","slot":"europeen","thumb":"/img/schemas/audi-a7-rs7.svg"},{"id":"honda-accord-10","nom":"Accord","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Honda Accord de décima geração","src":"Capturas oficiais","txt":"Sedã japonês de grande série, décima geração. O Accord é um dos carros mais vendidos da história nos Estados Unidos, a ponto de ter ficado invisível na paisagem urbana. Nome no jogo não divulgado.","search":"marque inconnue accord honda accord dixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Honda%20Accord%20dixi%C3%A8me","reelNom":"Honda Accord de décima geração","slot":"japonais","thumb":"/img/schemas/honda-accord-10.svg"},{"id":"mercedes-c-w205","nom":"Classe C","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Mercedes-Benz Classe C W205","src":"Segundo trailer","txt":"Sedã compacto alemão da geração W205, fabricado de 2014 a 2021. É o modelo que popularizou a estrela da Mercedes, e o carro corporativo por excelência em todo o Ocidente. Nome no jogo não divulgado.","search":"marque inconnue classe c mercedes-benz classe c w205","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20Classe%20C%20W205","reelNom":"Mercedes-Benz Classe C W205","slot":"europeen","thumb":"/img/schemas/mercedes-c-w205.svg"},{"id":"chevrolet-impala-10","nom":"Impala","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Chevrolet Impala de décima geração","src":"Primeiro trailer","txt":"Sedã grande americano dos anos 2000, a última geração com tração dianteira. Comprado em massa por frotas, locadoras e órgãos públicos, é o grau zero do carro anônimo. Nome no jogo não divulgado.","search":"marque inconnue impala chevrolet impala dixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Impala%20dixi%C3%A8me","reelNom":"Chevrolet Impala de décima geração","slot":"americain","thumb":"/img/schemas/chevrolet-impala-10.svg"},{"id":"volkswagen-jetta","nom":"Jetta","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Volkswagen Jetta","src":"Extended Look","txt":"Sedã compacto alemão, versão três volumes do Golf, muito popular nos Estados Unidos, onde os hatches vendem mal. Visto no Extended Look. Nome no jogo não divulgado.","search":"marque inconnue jetta volkswagen jetta","reel":"https://www.google.com/search?tbm=isch&q=Volkswagen%20Jetta","reelNom":"Volkswagen Jetta","slot":"europeen","thumb":"/img/schemas/volkswagen-jetta.svg"},{"id":"chrysler-lebaron-town-country","nom":"LeBaron Town & Country","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Chrysler LeBaron Town & Country 1986-1988","src":"Extended Look","txt":"Perua familiar com laterais de madeira imitada, vista no Extended Look. Esse revestimento de vinil imitando nogueira é uma tradição americana que remonta aos anos 40 e que a Chrysler levou até os anos 80. Nome no jogo não divulgado.","search":"marque inconnue lebaron town & country chrysler lebaron town & country 1986-1988","reel":"https://www.google.com/search?tbm=isch&q=Chrysler%20LeBaron%20Town%20%26%20Country","reelNom":"Chrysler LeBaron Town & Country","slot":"americain","thumb":"/img/schemas/chrysler-lebaron-town-country.svg"},{"id":"oceanic","nom":"Oceanic","marque":"Marca desconhecida","cat":"berline","st":"comm","insp":"Chevrolet Bel Air 1950","txt":"Sedã americano do pós-guerra, para-lamas arredondados, para-brisa em duas partes. Ele pertence à geração anterior aos rabos de peixe, a das primeiras grandes migrações para a Flórida.","search":"marque inconnue oceanic chevrolet bel air 1950","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Bel%20Air%201950","reelNom":"Chevrolet Bel Air 1950","slot":"americain","thumb":"/img/schemas/oceanic.svg"},{"id":"buick-regal-6","nom":"Regal","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Buick Regal de sexta geração","src":"Primeiro trailer","txt":"Sedã americano intermediário dos anos 2010, derivado de um Opel europeu. A Buick buscava então rejuvenescer uma clientela envelhecida, sem conseguir de verdade. Nome no jogo não divulgado.","search":"marque inconnue regal buick regal sixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Regal","reelNom":"Buick Regal","slot":"americain","thumb":"/img/schemas/buick-regal-6.svg"},{"id":"chrysler-sebring-dodge-stratus","nom":"Sebring","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Chrysler Sebring de segunda geração","src":"Capturas oficiais","txt":"Sedã de produção em massa do fim dos anos 2000, irmão gêmeo do Dodge Stratus. Muitas vezes citado como um dos carros americanos menos bem-sucedidos da época, o que não o impediu de lotar as frotas de locação. Nome no jogo não divulgado.","search":"marque inconnue sebring chrysler sebring deuxieme generation","reel":"https://www.google.com/search?tbm=isch&q=Chrysler%20Sebring","reelNom":"Chrysler Sebring","slot":"americain","thumb":"/img/schemas/chrysler-sebring-dodge-stratus.svg"},{"id":"buick-skylark-6","nom":"Skylark","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Buick Skylark de sexta geração","src":"Segundo trailer","txt":"Sedã compacto americano dos anos 80, produzido em enorme escala sobre a plataforma X da General Motors. Esses carros envelheceram mal e hoje acabam nas ruas dos bairros populares, o que combina bem com o cenário de Leonida. Nome no jogo não divulgado.","search":"marque inconnue skylark buick skylark sixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Skylark","reelNom":"Buick Skylark","slot":"americain","thumb":"/img/schemas/buick-skylark-6.svg"},{"id":"chevrolet-sonic","nom":"Sonic","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Chevrolet Sonic","src":"Primeiro trailer","txt":"O Chevrolet Sonic, compacto de entrada vendido às centenas de milhares nos Estados Unidos. Motor quatro cilindros modesto, interior simples: é o carro do primeiro salário ou da frota de locação. Por enquanto, a Rockstar o deixa sem nome no jogo. O primeiro trailer o mostra parado em um semáforo, entre os carros do dia a dia.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Sonic","reelNom":"Chevrolet Sonic","search":"marque inconnue sonic chevrolet sonic","slot":"americain","thumb":"/img/schemas/chevrolet-sonic.svg"},{"id":"ford-taurus","nom":"Taurus","marque":"Marca desconhecida","cat":"berline","st":"vu","insp":"Ford Taurus","src":"Extended Look","txt":"Sedã familiar americano, um dos maiores sucessos de vendas da Ford nos anos 80 e 90. A carroceria arredondada causou escândalo no lançamento, antes de virar o padrão do setor. Nome no jogo não divulgado.","search":"marque inconnue taurus ford taurus","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Taurus","reelNom":"Ford Taurus","slot":"americain","thumb":"/img/schemas/ford-taurus.svg"},{"id":"obey-tailgater","nom":"Tailgater","marque":"Obey","cat":"berline","st":"vu","insp":"Audi A6","src":"Primeiro trailer","search":"obey tailgater audi a6","txt":"A Obey é a marca alemã premium da série, e o Tailgater é o sedã de entrada dela, o do executivo que está começando a se dar bem. O Audi A6 que o inspira é um sedã de estrada sóbrio, com tração nas quatro rodas, feito para devorar quilômetros sem emoção. Um perfil que combina com os bairros empresariais de Downtown. Ele aparece rapidamente no primeiro trailer, durante uma cena de trânsito.","reel":"https://www.google.com/search?tbm=isch&q=Audi%20A6","reelNom":"Audi A6","slot":"europeen","thumb":"/img/schemas/obey-tailgater.svg"},{"id":"obey-tailgater-s","nom":"Tailgater S","marque":"Obey","cat":"berline","st":"vu","insp":"Audi RS3 Sedan","src":"Capturas oficiais","search":"obey tailgater s audi rs3 sedan","txt":"Versão alongada e mais bem equipada do Tailgater, seguindo a mesma lógica da relação entre um Audi A4 e um A6: mesma linguagem de design, mais comprimento, mais cromados discretos. É o sedã de diretoria, aquele que vem com motorista. As capturas oficiais o destacam, bem assentado nas rodas originais.","reel":"https://www.google.com/search?tbm=isch&q=Audi%20RS3%20Sedan","reelNom":"Audi RS3 Sedan","slot":"europeen","thumb":"/img/schemas/obey-tailgater-s.svg"},{"id":"schyster-pmp-700","nom":"PMP 700","marque":"Schyster","cat":"berline","st":"vu","insp":"Chrysler 300 de segunda geração","src":"Primeiro trailer","search":"schyster pmp 700 chrysler 300 deuxieme generation","txt":"O PMP 700 é um sedã de diretoria com motorista, no estilo dos grandes sedãs alemães em versão alongada. Esse tipo de veículo faz os traslados entre o aeroporto e os hotéis à beira-mar, um movimento enorme em Miami. O primeiro trailer o mostra de três quartos, por trás, em marcha lenta numa fila de carros.","medias":["trailer-1-vehicles-027"],"imageAlts":{"trailer-1-vehicles-027":"Sedã grande verde em primeiro plano à direita, primeiro trailer do GTA VI aos 00:27"},"reel":"https://www.google.com/search?tbm=isch&q=Chrysler%20300","reelNom":"Chrysler 300","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-027-480.webp"},{"id":"vapid-stanier-moderne","nom":"Stanier","marque":"Vapid","cat":"berline","st":"vu","insp":"Ford Crown Victoria","src":"Primeiro trailer","txt":"O Stanier atual, diferente do Stanier ’55 da edição Ultimate. Ele se inspira no Ford Crown Victoria, sedã de tração traseira e chassi separado que serviu como carro de polícia e táxi nos Estados Unidos por mais de vinte anos. Indestrutível, pesado e reconhecível na hora.","search":"vapid stanier ford crown victoria","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Crown%20Victoria","reelNom":"Ford Crown Victoria","slot":"americain","thumb":"/img/schemas/vapid-stanier-moderne.svg"},{"id":"vapid-stanier","nom":"Stanier ’55","marque":"Vapid","cat":"berline","st":"officiel","insp":"1956 Ford Fairlane Club Sedan","src":"Primeiro trailer","vues":[],"credit":"Capture officielle Rockstar Games","search":"vapid stanier ’55 1956 ford fairlane club sedan","txt":"O Stanier ’55 é um dos poucos veículos cujo nome a Rockstar divulgou, no Pacote Vintage Vice City. Nossas capturas oficiais mostram a carroceria em dois tons, amarelo e creme, os rabos de peixe, as calotas de disco e o monograma cursivo no para-lama. O Ford Fairlane de 1955, que inspirou as linhas dele, pertence àquela geração do pós-guerra em que o carro americano começou a parecer um avião. Uma escolha lógica para uma cidade que cultiva a própria nostalgia.","edition":"Pre-Order","medias":["55-vapid-stanier-01","55-vapid-stanier-02","55-vapid-stanier-03","55-vapid-stanier-04"],"vuesDeclarees":["profil","arriere","interieur","detail"],"reel":"https://www.google.com/search?tbm=isch&q=1956%20Ford%20Fairlane%20Club%20Sedan","reelNom":"1956 Ford Fairlane Club Sedan","slot":"americain","thumb":"/img/officiel/55-vapid-stanier-01-480.webp"},{"id":"declasse-stratum","nom":"Stratum","marque":"Zirconium","cat":"berline","st":"vu","insp":"Honda Accord perua","txt":"Perua familiar de grande produção, tampa traseira vertical e rack de teto. O Stratum é o veículo de cenário por excelência: está em todo lugar, não chama a atenção em lugar nenhum e, por isso, é perfeito quando você não quer ser notado.","search":"zirconium stratum honda accord station wagon","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Honda%20Accord%20station%20wagon","reelNom":"Honda Accord perua","slot":"japonais","thumb":"/img/schemas/declasse-stratum.svg"},{"id":"albany-manana","nom":"Manana","marque":"Albany","cat":"sport","st":"vu","insp":"Buick LeSabre, Cadillac Eldorado","src":"Capturas oficiais","search":"albany manana buick lesabre, cadillac eldorado","txt":"O Manana é um cupê de luxo americano dos anos 70: duas portas, teto de vinil, banco dianteiro inteiriço. Na série, ele sempre foi tratado como um carro de bairro, muitas vezes visto em versão lowrider. O tamanho exagerado para só dois lugares resume bem a época que o produziu. As capturas oficiais o mostram numa oficina de preparação, pronto para a pintura.","medias":["rideout-customs-mod-shop-01","ultimate-edition-rideout-customs-02","ultimate-edition-rideout-customs-03"],"imageAlts":{"ultimate-edition-rideout-customs-02":"Interior vermelho do carro apresentado na série de capturas da Rideout Customs","ultimate-edition-rideout-customs-03":"Cupê amarelo elevado na oficina Rideout Customs, identificado como um Albany Manana"},"reel":"https://www.google.com/search?tbm=isch&q=Buick%20LeSabre","reelNom":"Buick LeSabre","slot":"americain","thumb":"/img/officiel/rideout-customs-mod-shop-01-480.webp"},{"id":"albany-v-str","nom":"V-STR","marque":"Albany","cat":"sport","st":"vu","insp":"2019 Cadillac CTS-V","src":"Capturas oficiais","search":"albany v-str 2019 cadillac cts-v","txt":"O V-STR é a tentativa da Albany de fazer um esportivo moderno, o que, para uma marca de carrões americanos, é quase um contorcionismo. A sigla lembra os nomes de três letras que a Cadillac transformou em assinatura nos seus modelos de alto desempenho. As capturas oficiais o mostram parado, com a grade bem à vista.","reel":"https://www.google.com/search?tbm=isch&q=2019%20Cadillac%20CTS-V","reelNom":"2019 Cadillac CTS-V","slot":"americain","thumb":"/img/schemas/albany-v-str.svg"},{"id":"annis-elegy-retro-custom","nom":"Elegy Retro Custom","marque":"Annis","cat":"sport","st":"vu","insp":"Nissan Skyline GT-R","src":"Primeiro trailer","search":"annis elegy retro custom nissan skyline gt-r","txt":"O Elegy é o ícone do tuning da série, e a versão Retro Custom é a mais cobiçada. O Nissan Skyline R32 que o inspira é um monumento da cultura automotiva japonesa: tração integral, seis cilindros em linha e um domínio total nas pistas que lhe rendeu o apelido de Godzilla. O sufixo Custom indica um kit widebody e um aerofólio. O primeiro trailer o mostra acelerando numa avenida, com a câmera na altura dos faróis.","reel":"https://www.google.com/search?tbm=isch&q=Nissan%20Skyline%20GT-R","reelNom":"Nissan Skyline GT-R","slot":"japonais","thumb":"/img/schemas/annis-elegy-retro-custom.svg"},{"id":"benefactor-schafter-lwb","nom":"Schafter LWB","marque":"Benefactor","cat":"sport","st":"comm","insp":"Mercedes-Benz Classe E em versão alongada","txt":"Versão de entre-eixos longo do Schafter, pensada mais para quem vai no banco de trás do que para o motorista. Em Leonida, é o carro de quem anda com motorista: hotéis de Vice City, aeroporto, saídas à noite.","search":"benefactor schafter lwb mercedes-benz classe e allongee","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20Classe%20E%20allong%C3%A9e","reelNom":"Mercedes-Benz Classe E em versão alongada","slot":"europeen","thumb":"/img/schemas/benefactor-schafter-lwb.svg"},{"id":"bravado-banshee","nom":"Banshee","marque":"Bravado","cat":"sport","st":"vu","insp":"Dodge Viper","src":"Segundo trailer","search":"bravado banshee dodge viper","txt":"O Banshee é presença constante na série desde o Vice City, com uma silhueta que lembra na hora o Dodge Viper. O Dodge Viper de quinta geração, do qual ele herda as proporções, é um carro brutal: um V10 de caminhão num chassi estreito, sem os recursos eletrônicos que deixam os esportivos modernos dóceis. O Banshee foi catalogado a partir do segundo trailer, sem nome divulgado pela Rockstar.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Viper","reelNom":"Dodge Viper","slot":"americain","thumb":"/img/schemas/bravado-banshee.svg"},{"id":"bravado-buffalo","nom":"Buffalo","marque":"Bravado","cat":"sport","st":"vu","insp":"Dodge Charger","src":"Primeiro trailer","search":"bravado buffalo dodge charger","txt":"A Bravado é a marca dos muscle cars americanos, e o Buffalo é o seu sedã esportivo: quatro portas, motor grande, chassi rígido. Nos jogos anteriores, ele era usado tanto pela polícia quanto pelas gangues, o que diz muito sobre a proposta dele. O primeiro trailer o mostra rodando no meio do trânsito de Vice City.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Charger","reelNom":"Dodge Charger","slot":"americain","thumb":"/img/schemas/bravado-buffalo.svg"},{"id":"bravado-buffalo-s","nom":"Buffalo S","marque":"Bravado","cat":"sport","st":"comm","insp":"Dodge Charger SRT8","txt":"A versão esportiva do Buffalo: saias laterais mais agressivas, capô com entrada de ar, rodas fechadas. No Charger real, essa versão marcou a volta do muscle car americano de quatro portas nos anos 2010.","search":"bravado buffalo s dodge charger srt8","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Charger%20SRT8","reelNom":"Dodge Charger SRT8","slot":"americain","thumb":"/img/schemas/bravado-buffalo-s.svg"},{"id":"coil-raiden","nom":"Raiden","marque":"Coil","cat":"sport","st":"vu","insp":"Tesla Model S","src":"Capturas oficiais","txt":"O sedã elétrico da Coil, copiado do Tesla Model S: sem grade, maçanetas embutidas, torque total disponível assim que você tira o pé do freio. É o carro dos bairros ricos de Leonida. As capturas oficiais o mostram ligado a um carregador.","reel":"https://www.google.com/search?tbm=isch&q=Tesla%20Model%20S","reelNom":"Tesla Model S","search":"coil raiden tesla model s","slot":"americain","thumb":"/img/schemas/coil-raiden.svg"},{"id":"declasse-mamba-gt","nom":"Mamba GT","marque":"Declasse","cat":"sport","st":"officiel","insp":"Shelby Daytona Coupé","src":"Edição Ultimate","vues":[],"credit":"Capture officielle Rockstar Games","search":"declasse mamba gt shelby daytona coupe","txt":"O Mamba GT está entre os modelos que a Rockstar nomeou no catálogo da edição Ultimate. O Shelby Daytona Coupé, de que ele herda o visual, é um carro de corrida nascido de uma restrição: deixar um Cobra de rodas à mostra aerodinâmico o bastante para aguentar a reta das 24 Horas de Le Mans. O resultado, com sua traseira cortada e seu para-brisa inclinado, venceu o campeonato mundial em 1965. Apenas seis exemplares foram construídos.","edition":"Ultimate Edition","medias":["classic-car-collection-04"],"vuesDeclarees":["detail"],"reel":"https://www.google.com/search?tbm=isch&q=Shelby%20Daytona%20Coup%C3%A9","reelNom":"Shelby Daytona Coupé","slot":"americain","thumb":"/img/officiel/classic-car-collection-04-480.webp"},{"id":"dinka-blista-compact","nom":"Blista Compact","marque":"Dinka","cat":"sport","st":"vu","insp":"Honda CR-X de primeira geração","src":"Capturas oficiais","search":"dinka blista compact honda cr-x premiere generation","txt":"A Dinka é a Honda desse universo, e o Blista Compact é o seu hatch esportivo. A fórmula é conhecida: carro pequeno e leve, motor nervoso, tração dianteira, preço acessível. É o tipo de veículo que enche as ruas, e não as garagens de colecionador. As capturas oficiais o colocam ao longo de uma rua residencial.","reel":"https://www.google.com/search?tbm=isch&q=Honda%20CR-X","reelNom":"Honda CR-X","slot":"japonais","thumb":"/img/schemas/dinka-blista-compact.svg"},{"id":"dinka-sugoi","nom":"Sugoi","marque":"Dinka","cat":"sport","st":"vu","insp":"Honda Civic Type R FK8","src":"Capturas oficiais","search":"dinka sugoi honda civic type r fk8","txt":"Sedã compacto de vocação esportiva, o Sugoi tem um nome que significa simplesmente “incrível” em japonês, o que diz muito sobre o humor da série. Ele pertence àquela família de carros de linha que viram máquinas de pista com algumas peças. As capturas oficiais o mostram com o aerofólio erguido, pronto para a reta.","reel":"https://www.google.com/search?tbm=isch&q=Honda%20Civic%20R%20FK8","reelNom":"Honda Civic R FK8","slot":"japonais","thumb":"/img/schemas/dinka-sugoi.svg"},{"id":"cheval-vectre","nom":"Vectre","marque":"Emperor","cat":"sport","st":"vu","insp":"Lexus RC F","src":"Segundo trailer","search":"emperor vectre lexus rc f","txt":"A Emperor é a marca japonesa de luxo do universo, e o Vectre é o cupê esportivo compacto dela. O nome soa como uma contração de “vetor”, no estilo aerodinâmico de que as montadoras gostavam nos anos 90. O segundo trailer o coloca em um plano de trânsito urbano.","reel":"https://www.google.com/search?tbm=isch&q=Lexus%20RC%20F","reelNom":"Lexus RC F","slot":"japonais","thumb":"/img/schemas/cheval-vectre.svg"},{"id":"enus-paragon-r","nom":"Paragon R","marque":"Enus","cat":"sport","st":"vu","insp":"2018 Bentley Continental GT","src":"Capturas oficiais","search":"enus paragon r 2018 bentley continental gt","txt":"O Paragon R segue o Bentley Continental GT de 2018: cupê de quatro lugares, W12 sob o capô e um peso que nenhuma suspensão consegue disfarçar por completo. É o gran turismo no sentido literal, o carro que cruza um continente de uma vez só. O sufixo R indica a versão mais afiada.","reel":"https://www.google.com/search?tbm=isch&q=2018%20Bentley%20Continental%20GT","reelNom":"2018 Bentley Continental GT","slot":"europeen","thumb":"/img/schemas/enus-paragon-r.svg"},{"id":"enus-windsor","nom":"Windsor","marque":"Enus","cat":"sport","st":"vu","insp":"Rolls-Royce Wraith","src":"Segundo trailer","txt":"O cupê de alto luxo da Enus, copiado do Rolls-Royce Wraith: portas suicidas, capô interminável, grade vertical erguida como o frontão de um templo. É o carro que você para na porta do hotel só para ser visto saindo dele. O segundo trailer o mostra de perfil.","reel":"https://www.google.com/search?tbm=isch&q=Rolls-Royce%20Wraith","reelNom":"Rolls-Royce Wraith","search":"enus windsor rolls-royce wraith","slot":"europeen","thumb":"/img/schemas/enus-windsor.svg"},{"id":"fathom-fr36","nom":"FR36","marque":"Fathom","cat":"sport","st":"vu","insp":"Infiniti G35 (V35)","src":"Extended Look","txt":"O cupê da Fathom segue o Infiniti G35 de primeira geração, um japonês de tração traseira que virou clássico da preparação graças ao motor de seis cilindros e ao chassi equilibrado. No Extended Look, ele aparece numa oficina, de capô aberto.","reel":"https://www.google.com/search?tbm=isch&q=Infiniti%20G35%20(V35)","reelNom":"Infiniti G35 (V35)","search":"fathom fr36 infiniti g35 (v35)","slot":"japonais","thumb":"/img/schemas/fathom-fr36.svg"},{"id":"grotti-carbonizzare","nom":"Carbonizzare","marque":"Grotti","cat":"sport","st":"vu","insp":"Ferrari F12berlinetta e Aston Martin V12 Zagato","src":"Primeiro trailer","search":"grotti carbonizzare ferrari f12berlinetta et aston martin v12 zagato","txt":"A Grotti é a Ferrari da série, e o Carbonizzare é o gran turismo de motor dianteiro dela. A Ferrari F12 que serve de modelo é um carro de rua fora de série: um V12 aspirado de mais de setecentos cavalos, numa carroceria esculpida para canalizar o ar em vez de cortá-lo. O primeiro trailer o mostra numa passagem rápida.","medias":["trailer-1-vehicles-025"],"imageAlts":{"trailer-1-vehicles-025":"Conversível vermelho ocupado por uma passageira em pé, primeiro trailer do GTA VI aos 00:25"},"reel":"https://www.google.com/search?tbm=isch&q=Ferrari%20F12berlinetta","reelNom":"Ferrari F12berlinetta","slot":"europeen","thumb":"/img/officiel/trailer-1-vehicles-025-480.webp"},{"id":"grotti-cheetah-classic","nom":"Cheetah ’95","marque":"Grotti","cat":"sport","st":"officiel","insp":"Ferrari Testarossa e 512 BB","src":"Edição Ultimate","vues":[],"credit":"Capture officielle Rockstar Games","search":"grotti cheetah ’95 ferrari testarossa et 512 bb","txt":"A Rockstar dá nome ao Cheetah ’95 no catálogo da edição Ultimate, e as nossas quatro capturas oficiais mostram a carroceria branca com faixas vermelhas, o interior de couro vermelho, as rodas de cinco raios e o monograma na traseira. A Ferrari Testarossa cujo estilo ele copia virou, para toda uma geração, a própria imagem de Miami: as aletas laterais e as proporções exageradas fizeram mais pelo imaginário da cidade do que qualquer campanha de turismo.","edition":"Ultimate Edition","medias":["95-grotti-cheetah-01","95-grotti-cheetah-02","95-grotti-cheetah-03","95-grotti-cheetah-04"],"vuesDeclarees":["face","profil","arriere","interieur"],"reel":"https://www.google.com/search?tbm=isch&q=Ferrari%20Testarossa","reelNom":"Ferrari Testarossa","slot":"europeen","thumb":"/img/officiel/95-grotti-cheetah-01-480.webp"},{"id":"grotti-itali-gto","nom":"Itali GTO","marque":"Grotti","cat":"sport","st":"vu","insp":"Ferrari 812 Superfast","src":"Primeiro trailer","search":"grotti itali gto ferrari 812 superfast","txt":"O Itali GTO retoma a linguagem da Ferrari 812 Superfast: V12 na frente, traseira compacta, saídas de escapamento agrupadas. A 812 é uma das últimas Ferraris com motor de doze cilindros aspirado, o que hoje lhe dá um status especial entre os colecionadores. A chegada dele a Leonida ainda precisa ser confirmada.","reel":"https://www.google.com/search?tbm=isch&q=Ferrari%20812%20Superfast","reelNom":"Ferrari 812 Superfast","slot":"europeen","thumb":"/img/schemas/grotti-itali-gto.svg"},{"id":"grotti-itali-rsx","nom":"Itali RSX","marque":"Grotti","cat":"sport","st":"vu","insp":"Ferrari SF90 Stradale","src":"Extended Look","txt":"O Grotti mais tecnológico da linha, copiado da Ferrari SF90 Stradale e do seu conjunto híbrido plug-in. Traseira truncada, escapamento duplo no alto, aerodinâmica ativa atrás. No Extended Look, ele acelera num trecho livre de rodovia.","reel":"https://www.google.com/search?tbm=isch&q=Ferrari%20SF90%20Stradale","reelNom":"Ferrari SF90 Stradale","search":"grotti itali rsx ferrari sf90 stradale","slot":"europeen","thumb":"/img/schemas/grotti-itali-rsx.svg"},{"id":"invetero-coquette","nom":"Coquette","marque":"Invetero","cat":"sport","st":"vu","insp":"Corvette C7, 2014 Corvette Stingray","src":"Segundo trailer","search":"invetero coquette corvette c7, 2014 corvette stingray","txt":"O Coquette da Invetero é comparado ao Corvette C7, em especial ao Corvette Stingray de 2014. Essa inspiração diferencia esta ficha das outras gerações de Coquette. A nossa base de dados o registra no segundo trailer, sem nome divulgado pela Rockstar.","reel":"https://www.google.com/search?tbm=isch&q=Corvette%20C7","reelNom":"Corvette C7","slot":"americain","thumb":"/img/schemas/invetero-coquette.svg"},{"id":"invetero-coquette-d10","nom":"Coquette D10","marque":"Invetero","cat":"sport","st":"vu","insp":"Chevrolet Corvette C8","src":"Primeiro trailer","search":"invetero coquette d10 chevrolet corvette c8","txt":"Versão radicalizada do Coquette, no espírito dos Corvette Z06: bitolas mais largas, aerodinâmica agressiva, motor mais bravo. O Z06 é tradicionalmente a versão que a Chevrolet prepara para as pistas sem deixar de homologá-la para as ruas. O primeiro trailer o faz surgir numa cena noturna.","medias":["extended-look-coquette-d10"],"imageAlts":{"extended-look-coquette-d10":"Conversível vermelho em primeiro plano à esquerda, quadro de An Extended Look"},"reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Corvette%20C8","reelNom":"Chevrolet Corvette C8","slot":"americain","thumb":"/img/officiel/extended-look-coquette-d10-480.webp"},{"id":"annis-futo","nom":"Futo","marque":"Karin","cat":"sport","st":"vu","insp":"Toyota AE86 Levin","src":"Primeiro trailer","search":"karin futo toyota ae86 levin","txt":"O Futo é o carro leve de tração traseira por excelência, aquele que você escolhe para aprender a fazer drift, e não para andar rápido. O Toyota AE86, do qual ele herda a silhueta, tem uma aura enorme: carro acessível e equilibrado, ele virou o símbolo do drift amador antes de ficar famoso com a cultura mangá. O primeiro trailer o mostra passando ao fundo, com as lanternas traseiras acesas.","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20AE86%20Levin","reelNom":"Toyota AE86 Levin","slot":"japonais","thumb":"/img/schemas/annis-futo.svg"},{"id":"karin-sultan","nom":"Sultan","marque":"Karin","cat":"sport","st":"vu","insp":"Lexus IS, Mitsubishi Lancer Evo VI, Subaru Impreza","src":"Primeiro trailer","search":"karin sultan lexus is, mitsubishi lancer evo vi, subaru impreza","txt":"O Sultan é o sedã esportivo com tração integral da série, o do rali urbano. O Subaru Impreza WRX que o inspira construiu a fama nas especiais do Mundial de Rali, com o motor boxer e uma estabilidade inabalável em asfalto ruim. A aparição dele está registrada no primeiro trailer; o nome Sultan continua sendo uma identificação da comunidade.","reel":"https://www.google.com/search?tbm=isch&q=Lexus%20IS","reelNom":"Lexus IS","slot":"japonais","thumb":"/img/schemas/karin-sultan.svg"},{"id":"karin-sultan-rs","nom":"Sultan RS","marque":"Karin","cat":"sport","st":"comm","insp":"Subaru Impreza WRX STI preparado","txt":"O Sultan levado à configuração de rali: alargadores de para-lama, aerofólio, entrada de ar no capô. É a referência do compacto japonês com tração nas quatro rodas, aquele que definiu toda uma geração do tuning.","search":"karin sultan rs subaru impreza wrx sti preparee","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Subaru%20Impreza%20WRX%20STI","reelNom":"Subaru Impreza WRX STI","slot":"japonais","thumb":"/img/schemas/karin-sultan-rs.svg"},{"id":"maibatsu-penumbra","nom":"Penumbra","marque":"Maibatsu","cat":"sport","st":"vu","insp":"Mitsubishi Eclipse, Audi TT","src":"Segundo trailer","search":"maibatsu penumbra mitsubishi eclipse, audi tt","txt":"A Maibatsu é a marca japonesa popular da série, e o Penumbra é o cupê esportivo de entrada dela. Ele faz parte daquela categoria de carros que têm a cara de esportivo sem a mecânica à altura, o que os torna bases de preparação muito disputadas. O segundo trailer o coloca no trânsito, de faróis acesos.","reel":"https://www.google.com/search?tbm=isch&q=Mitsubishi%20Eclipse","reelNom":"Mitsubishi Eclipse","slot":"japonais","thumb":"/img/schemas/maibatsu-penumbra.svg"},{"id":"maibatsu-penumbra-ff","nom":"Penumbra FF","marque":"Maibatsu","cat":"sport","st":"vu","insp":"Mitsubishi Eclipse de segunda geração, Eagle Talon de segunda geração","src":"Extended Look","txt":"O Penumbra na versão de tração dianteira, inspirado no Mitsubishi Eclipse de segunda geração e no seu irmão gêmeo, o Eagle Talon. Faróis escamoteáveis, tampa traseira de vidro: é o carro de preparação dos anos 90 por excelência. No Extended Look, ele aparece em plena aceleração.","reel":"https://www.google.com/search?tbm=isch&q=Mitsubishi%20Eclipse","reelNom":"Mitsubishi Eclipse","search":"maibatsu penumbra ff mitsubishi eclipse deuxieme generation, eagle talon deuxieme generation","slot":"japonais","thumb":"/img/schemas/maibatsu-penumbra-ff.svg"},{"id":"mercedes-cle-a236","nom":"Classe CLE Cabriolet","marque":"Marca desconhecida","cat":"sport","st":"vu","insp":"Mercedes-Benz Classe CLE (A236)","src":"Segundo trailer","txt":"O conversível CLE da Mercedes-Benz, aquele que substituiu de uma vez só os conversíveis Classe C e Classe E. Capota de lona, quatro lugares apertados, estrela cravada no centro da grade. Ele aparece no segundo trailer sem ter recebido nome no jogo.","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20Classe%20CLE%20(A236)","reelNom":"Mercedes-Benz Classe CLE (A236)","search":"marque inconnue classe cle cabriolet mercedes-benz classe cle (a236)","slot":"europeen","thumb":"/img/schemas/mercedes-cle-a236.svg"},{"id":"cadillac-eldorado-1959","nom":"Eldorado 1959","marque":"Marca desconhecida","cat":"sport","st":"vu","insp":"Cadillac Eldorado 1959","src":"Segundo trailer","txt":"O Cadillac Eldorado de 1959, aquele dos rabos de peixe exagerados e das lanternas em forma de foguete, símbolo da América de antes da crise do petróleo. Nem nome no jogo nem fabricante fictício foram atribuídos a ele. O segundo trailer o mostra rodando devagar pela orla.","reel":"https://www.google.com/search?tbm=isch&q=Cadillac%20Eldorado%201959","reelNom":"Cadillac Eldorado 1959","search":"marque inconnue eldorado 1959 cadillac eldorado 1959","slot":"americain","thumb":"/img/schemas/cadillac-eldorado-1959.svg"},{"id":"kellison-j4","nom":"Kellison J4","marque":"Marca desconhecida","cat":"sport","st":"vu","insp":"Kellison J4","src":"Capturas oficiais","txt":"Um roadster artesanal dos anos 60, de fibra de vidro, feito em pequena série por um encarroçador da Califórnia para correr nos fins de semana. A Rockstar não deu nome a ele no jogo. As capturas oficiais o mostram parado, de capô fechado.","medias":["ultimate-edition-02","classic-car-collection-05"],"imageAlts":{"ultimate-edition-02":"Jason e Lucia diante do cupê verde associado a um Kellison J4 na imagem da edição Ultimate"},"reel":"https://www.google.com/search?tbm=isch&q=Kellison%20J4","reelNom":"Kellison J4","search":"marque inconnue kellison j4 kellison j4","thumb":"/img/officiel/ultimate-edition-02-480.webp"},{"id":"lincoln-mark-viii","nom":"Mark VIII","marque":"Marca desconhecida","cat":"sport","st":"vu","insp":"Lincoln Mark VIII","src":"Extended Look","txt":"O grande cupê de luxo da Lincoln, o último da linhagem Mark, com a traseira arredondada e a faixa de lanternas cobrindo toda a largura. O nome no jogo não foi divulgado. No Extended Look, ele aparece no trânsito noturno, de faróis acesos.","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Mark%20VIII","reelNom":"Lincoln Mark VIII","search":"marque inconnue mark viii lincoln mark viii","slot":"americain","thumb":"/img/schemas/lincoln-mark-viii.svg"},{"id":"buick-reatta-convertible","nom":"Reatta Conversível","marque":"Marca desconhecida","cat":"sport","st":"vu","insp":"Buick Reatta Convertible","src":"Segundo trailer","txt":"Um cupê conversível americano do fim dos anos 80, baseado no Buick Reatta: linhas angulosas, capota de lona, dois lugares e nenhum a mais. A Rockstar ainda não deu um nome a ele no jogo. O segundo trailer o deixa estacionado de frente para o mar.","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Reatta%20Convertible","reelNom":"Buick Reatta Convertible","search":"marque inconnue reatta decapotable buick reatta convertible","slot":"americain","thumb":"/img/schemas/buick-reatta-convertible.svg"},{"id":"obey-8f-drafter","nom":"8F Drafter","marque":"Obey","cat":"sport","st":"vu","insp":"2018 Audi RS5 Coupe","src":"Capturas oficiais","search":"obey 8f drafter 2018 audi rs5 coupe","txt":"O 8F Drafter é o cupê de quatro portas da Obey, aquela categoria híbrida que as montadoras alemãs inventaram para vender o conforto de um sedã com as linhas de um cupê. O nome remete ao vácuo nas corridas, quando um carro se encaixa no rastro de outro. As capturas oficiais mostram o carro de perfil, com um estacionamento ao fundo.","reel":"https://www.google.com/search?tbm=isch&q=2018%20Audi%20RS5%20Coupe","reelNom":"2018 Audi RS5 Coupe","slot":"europeen","thumb":"/img/schemas/obey-8f-drafter.svg"},{"id":"overflod-omnis-e-gt","nom":"Omnis e-GT","marque":"Obey","cat":"sport","st":"vu","insp":"Audi e-Tron GT","txt":"Cupê elétrico gran turismo, sem escapamento visível nem entrada de ar para o motor. Leonida confirma a presença de veículos elétricos e de pontos de recarga, o que dá a essa categoria um papel de verdade no jogo.","search":"obey omnis e-gt audi e-tron gt","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Audi%20e-Tron%20GT","reelNom":"Audi e-Tron GT","slot":"europeen","thumb":"/img/schemas/overflod-omnis-e-gt.svg"},{"id":"ocelot-jugular","nom":"Jugular","marque":"Ocelot","cat":"sport","st":"vu","insp":"Jaguar XE SV Project 8","src":"Primeiro trailer","search":"ocelot jugular jaguar xe sv project 8","txt":"A Ocelot é a Jaguar deste universo, e o Jugular é o seu sedã esportivo. O Jaguar XE SV Project 8, do qual ele herda as proporções, é um sedã de série levado ao extremo: aerofólio fixo, bitolas alargadas e V8 com compressor pensado para a pista. No primeiro trailer, ele cruza uma cena de rua em poucos quadros.","reel":"https://www.google.com/search?tbm=isch&q=Jaguar%20XE%20SV%20Project%208","reelNom":"Jaguar XE SV Project 8","slot":"europeen","thumb":"/img/schemas/ocelot-jugular.svg"},{"id":"pegassi-infernus-classic","nom":"Infernus Classic","marque":"Pegassi","cat":"sport","st":"vu","insp":"Lamborghini Diablo, Cizeta V16T, Ferrari Testarossa","src":"Extended Look","search":"pegassi infernus classic lamborghini diablo, cizeta v16t, ferrari testarossa","txt":"O Infernus é o superesportivo histórico da série, presente desde o GTA III. A versão Classic retoma o estilo do Lamborghini Diablo e do Cizeta V16T: ângulos marcados, portas tesoura, visibilidade traseira quase nula. Nos anos 90, o Diablo manteve viva a estética do superesportivo de pôster de quarto de adolescente. O Infernus Classic foi identificado no Extended Look.","reel":"https://www.google.com/search?tbm=isch&q=Lamborghini%20Diablo","reelNom":"Lamborghini Diablo","slot":"europeen","thumb":"/img/schemas/pegassi-infernus-classic.svg"},{"id":"pfister-comet-retro-custom","nom":"Comet Retro Custom","marque":"Pfister","cat":"sport","st":"vu","insp":"Rauh-Welt Porsche 911 930","src":"Primeiro trailer","search":"pfister comet retro custom rauh-welt porsche 911 930","txt":"A Pfister é a Porsche deste universo, e o Comet sempre foi o seu 911. A versão Retro Custom se inspira nos 911 G-Series dos anos 70 e 80, reconhecíveis pelos para-choques sanfonados. Essa geração, desprezada por muito tempo, hoje é a mais procurada para preparação. O primeiro trailer mostra o carro alargado por todos os lados, com direito a para-lamas estufados.","reel":"https://www.google.com/search?tbm=isch&q=Rauh-Welt%20Porsche%20911%20930","reelNom":"Rauh-Welt Porsche 911 930","slot":"europeen","thumb":"/img/schemas/pfister-comet-retro-custom.svg"},{"id":"pfister-comet-s2","nom":"Comet S2","marque":"Pfister","cat":"sport","st":"comm","insp":"Porsche 911 992","txt":"O cupê da Pfister na sua forma mais recente, com base no 911 da geração 992. Motor pendurado atrás do eixo traseiro, lanternas unidas por uma faixa de luz contínua, traseira mais larga. A versão Cabrio já está nesta base de dados.","search":"pfister comet s2 porsche 911 992","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Porsche%20911%20992","reelNom":"Porsche 911 992","slot":"europeen","thumb":"/img/schemas/pfister-comet-s2.svg"},{"id":"pfister-comet-s2-cabrio","nom":"Comet S2 Cabrio","marque":"Pfister","cat":"sport","st":"vu","insp":"Porsche 911 Turbo S Cabriolet","src":"Primeiro trailer","search":"pfister comet s2 cabrio porsche 911 turbo s cabriolet","txt":"Versão conversível do Comet moderno, baseada nos Porsche 911 da geração 992. O que torna o 911 conversível especial é a arquitetura: como o motor fica atrás, a rigidez da carroceria sofre menos com a retirada do teto do que em um esportivo convencional. No primeiro trailer, ele roda de capota abaixada pela orla.","medias":["trailer-1-vehicles-033"],"imageAlts":{"trailer-1-vehicles-033":"Conversível turquesa em primeiro plano à esquerda na orla, primeiro trailer do GTA VI aos 00:33"},"reel":"https://www.google.com/search?tbm=isch&q=Porsche%20911%20Turbo%20S%20Cabriolet","reelNom":"Porsche 911 Turbo S Cabriolet","slot":"europeen","thumb":"/img/officiel/trailer-1-vehicles-033-480.webp"},{"id":"annis-growler","nom":"Growler","marque":"Pfister","cat":"sport","st":"vu","insp":"Porsche 718 Cayman","src":"Segundo trailer","search":"pfister growler porsche 718 cayman","txt":"O Growler é o cupê da Pfister que a nossa base de dados compara ao Porsche 718 Cayman. Ele foi catalogado a partir do segundo trailer. A identificação dele continua sendo da comunidade: o material oficial não dá nome a ele.","reel":"https://www.google.com/search?tbm=isch&q=Porsche%20718%20Cayman","reelNom":"Porsche 718 Cayman","slot":"europeen","thumb":"/img/schemas/annis-growler.svg"},{"id":"pfister-neon","nom":"Neon","marque":"Pfister","cat":"sport","st":"vu","insp":"Porsche Taycan, Porsche Panamera, Porsche 918 Spyder","src":"Extended Look","txt":"O sedã elétrico da Pfister, montado a partir de vários Porsches: o Taycan na silhueta, o 918 Spyder na dianteira, o Panamera na linha do teto. Silencioso e pesado, mas capaz de arrancar muito forte. O Extended Look acompanha o carro pela cidade.","reel":"https://www.google.com/search?tbm=isch&q=Porsche%20Taycan","reelNom":"Porsche Taycan","search":"pfister neon porsche taycan, porsche panamera, porsche 918 spyder","slot":"europeen","thumb":"/img/schemas/pfister-neon.svg"},{"id":"ubermacht-cypher","nom":"Cypher","marque":"Übermacht","cat":"sport","st":"vu","insp":"BMW M2 F87, com toques de M6 e M8","src":"Primeiro trailer","search":"ubermacht cypher bmw m2 f87, avec des touches de m6 et m8","txt":"A Übermacht é a BMW da série, e o Cypher é o seu cupê compacto e afiado. O BMW M2, do qual ele herda o estilo, pertence a uma linhagem que remonta ao M3 dos anos 80, um carro de corrida homologado para as ruas que construiu a fama nas pistas antes de chegar às concessionárias. O primeiro trailer o mostra parado, logo antes de arrancar.","reel":"https://www.google.com/search?tbm=isch&q=BMW%20M2%20F87","reelNom":"BMW M2 F87","slot":"europeen","thumb":"/img/schemas/ubermacht-cypher.svg"},{"id":"ubermacht-sentinel-classic","nom":"Sentinel Classic","marque":"Übermacht","cat":"sport","st":"vu","insp":"BMW E30 M3","txt":"O Sentinel é o BMW do universo GTA desde o GTA III. A versão Classic retoma a silhueta do E30 dos anos 80: capô reto, faróis duplos redondos, coluna traseira fina. É exatamente o tipo de cupê alemão que se via na Ocean Drive na época que Vice City recria.","search":"ubermacht sentinel classic bmw e30 m3","src":"Extended Look","medias":["extended-look-sentinel-classic-front","extended-look-sentinel-classic-rear"],"imageAlts":{"extended-look-sentinel-classic-front":"Conversível vermelho em frente a algumas lojas, quadro de An Extended Look","extended-look-sentinel-classic-rear":"Conversível vermelho visto de trás durante uma sequência de direção de An Extended Look"},"reel":"https://www.google.com/search?tbm=isch&q=BMW%20E30%20M3","reelNom":"BMW E30 M3","slot":"europeen","thumb":"/img/officiel/extended-look-sentinel-classic-front-480.webp"},{"id":"ubermacht-sentinel-xs","nom":"Sentinel XS","marque":"Übermacht","cat":"sport","st":"vu","insp":"BMW M3 E92","txt":"Versão contemporânea do Sentinel, baseada no Série 3 dos anos 2000 e 2010. Cupê compacto com tração traseira, para-choques integrados, linha de cintura marcada. A grande referência dos sedãs esportivos alemães feitos em grande escala.","search":"ubermacht sentinel xs bmw m3 e92","src":"Segundo trailer","reel":"https://www.google.com/search?tbm=isch&q=BMW%20M3%20E92","reelNom":"BMW M3 E92","slot":"europeen","thumb":"/img/schemas/ubermacht-sentinel-xs.svg"},{"id":"ubermacht-zion","nom":"Zion","marque":"Übermacht","cat":"sport","st":"vu","insp":"BMW M6 E63","src":"Capturas oficiais","search":"ubermacht zion bmw m6 e63","txt":"Cupê burguês da Übermacht, o Zion aposta no gran turismo mais do que no desempenho puro: duas portas, quatro lugares, um motor suficiente sem ser exagerado. É o carro de quem já se deu bem e não precisa mais provar nada. As capturas oficiais o mostram estacionado em diagonal, com o teto fechado.","reel":"https://www.google.com/search?tbm=isch&q=BMW%20M6%20E63","reelNom":"BMW M6 E63","slot":"europeen","thumb":"/img/schemas/ubermacht-zion.svg"},{"id":"ubermacht-zion-cabrio","nom":"Zion Cabrio","marque":"Übermacht","cat":"sport","st":"vu","insp":"BMW Série 6 E64","src":"Extended Look","txt":"A versão conversível do Zion, copiada do BMW Série 6 E64 desenhado na era Bangle, com direito à polêmica traseira. Quatro lugares, capota de lona, um seis cilindros que dá conta do recado. No Extended Look, ele roda de capota abaixada pelo litoral.","reel":"https://www.google.com/search?tbm=isch&q=BMW%20S%C3%A9rie%206%20E64","reelNom":"BMW Série 6 E64","search":"ubermacht zion cabrio bmw serie 6 e64","slot":"europeen","thumb":"/img/schemas/ubermacht-zion-cabrio.svg"},{"id":"grotti-furia","nom":"Furia","marque":"Grotti","cat":"supercar","st":"vu","insp":"Ferrari 488 Pista e SF90 Stradale","src":"Primeiro trailer","search":"grotti furia ferrari 488 pista et sf90 stradale","txt":"O Furia segue a Ferrari SF90 Stradale, a primeira Ferrari de rua híbrida plug-in. A arquitetura é fora do comum: um V8 turbo atrás e três motores elétricos, dois deles no eixo dianteiro, somando mais de mil cavalos. É um carro que pode rodar em silêncio antes de se transformar. O primeiro trailer o lança a toda velocidade num trecho livre.","reel":"https://www.google.com/search?tbm=isch&q=Ferrari%20488%20Pista","reelNom":"Ferrari 488 Pista","slot":"europeen","thumb":"/img/schemas/grotti-furia.svg"},{"id":"lamborghini-aventador","nom":"Aventador","marque":"Marca desconhecida","cat":"supercar","st":"vu","insp":"Lamborghini Aventador","src":"Primeiro trailer","txt":"O Lamborghini Aventador do jeito que é, com portas tesoura e V12 aspirado, sem nome no jogo nem fabricante fictício associado. A Rockstar o colocou no cenário sem inventar um equivalente próprio. O primeiro trailer o mostra no meio do trânsito.","reel":"https://www.google.com/search?tbm=isch&q=Lamborghini%20Aventador","reelNom":"Lamborghini Aventador","search":"marque inconnue aventador lamborghini aventador","slot":"europeen","thumb":"/img/schemas/lamborghini-aventador.svg"},{"id":"pegassi-tempesta","nom":"Tempesta","marque":"Pegassi","cat":"supercar","st":"vu","insp":"Lamborghini Huracán e Centenario","src":"Segundo trailer","search":"pegassi tempesta lamborghini huracan et centenario","txt":"O Tempesta se inspira no Lamborghini Huracán e no Centenario: V10 aspirado em posição central, tração integral, carroceria toda facetada. O Huracán é um dos últimos superesportivos a manter um motor aspirado de grande cilindrada, o que lhe dá um ronco que os motores turbo não conseguem reproduzir. Alguns também veem nele o Lotus Esprit desenhado em 2015 e nunca produzido.","reel":"https://www.google.com/search?tbm=isch&q=Lamborghini%20Hurac%C3%A1n","reelNom":"Lamborghini Huracán","slot":"europeen","thumb":"/img/schemas/pegassi-tempesta.svg"},{"id":"pegassi-zentorno","nom":"Zentorno","marque":"Pegassi","cat":"supercar","st":"comm","insp":"Lamborghini Sesto Elemento e Veneno","txt":"Superesportivo de arestas vivas, entradas de ar em Y, teto afilado. O Zentorno leva a linguagem da Lamborghini à sua versão mais extrema, a das séries limitadas a poucas unidades.","search":"pegassi zentorno lamborghini sesto elemento et veneno","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Lamborghini%20Sesto%20Elemento","reelNom":"Lamborghini Sesto Elemento","slot":"europeen","thumb":"/img/schemas/pegassi-zentorno.svg"},{"id":"pegassi-zorrusso","nom":"Zorrusso","marque":"Pegassi","cat":"supercar","st":"vu","insp":"Italdesign Zerouno","src":"Primeiro trailer","search":"pegassi zorrusso italdesign zerouno","txt":"Aqui, o Zorrusso da Pegassi é associado ao Italdesign Zerouno. Essa identificação continua sendo uma comparação feita pela comunidade. O primeiro trailer é a aparição registrada nesta ficha, sem nome oficial para o veículo.","reel":"https://www.google.com/search?tbm=isch&q=Italdesign%20Zerouno","reelNom":"Italdesign Zerouno","slot":"europeen","thumb":"/img/schemas/pegassi-zorrusso.svg"},{"id":"progen-emerus","nom":"Emerus","marque":"Progen","cat":"supercar","st":"vu","insp":"McLaren Senna","src":"Extended Look","txt":"O superesportivo de pista da Progen, copiado do McLaren Senna: aerofólio gigante, entradas de ar por toda parte, vidros recortados até a parte de baixo das portas. Tudo é sacrificado em nome da pressão aerodinâmica, a começar pelo conforto. No Extended Look, ele aparece parado em uma garagem.","reel":"https://www.google.com/search?tbm=isch&q=McLaren%20Senna","reelNom":"McLaren Senna","search":"progen emerus mclaren senna","slot":"europeen","thumb":"/img/schemas/progen-emerus.svg"},{"id":"albany-buccaneer","nom":"Buccaneer","marque":"Albany","cat":"muscle","st":"vu","insp":"Ford Fairlane, Buick Riviera","src":"Primeiro trailer","search":"albany buccaneer ford fairlane, buick riviera","txt":"O Buccaneer é o cupê de luxo americano na sua versão mais generosa. O Buick Riviera de 1966 que o inspira é um carro de desenho marcante, com faróis escamoteáveis e a linha tensa da coluna traseira, assinado pelo estúdio de design da General Motors no seu auge. O primeiro trailer o mostra saindo de uma curva, com a traseira escapando um pouco.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Fairlane","reelNom":"Ford Fairlane","slot":"americain","thumb":"/img/schemas/albany-buccaneer.svg"},{"id":"albany-buccaneer-custom","nom":"Buccaneer Custom","marque":"Albany","cat":"muscle","st":"vu","insp":"Ford Fairlane, Buick Riviera","src":"Primeiro trailer","search":"albany buccaneer custom ford fairlane, buick riviera","txt":"Versão preparada do Buccaneer, no estilo lowrider: carroceria rente ao chão, rodas raiadas, pintura com flocos metálicos. Os grandes cupês dos anos 60 são a base histórica dessa cultura, justamente porque o chassi separado da carroceria aguenta bem a suspensão hidráulica. O primeiro trailer flagra o carro sob os neons de um posto de gasolina.","medias":["trailer-1-vehicles-028"],"imageAlts":{"trailer-1-vehicles-028":"Lowrider azul-claro em primeiro plano à direita, primeiro trailer do GTA VI aos 00:28"},"reel":"https://www.google.com/search?tbm=isch&q=Ford%20Fairlane","reelNom":"Ford Fairlane","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-028-480.webp"},{"id":"albany-virgo-classic","nom":"Virgo Classic","marque":"Albany","cat":"muscle","st":"comm","insp":"Lincoln Continental Mark III","txt":"Cupê de luxo dos anos 70: estepe falso na tampa do porta-malas, grade vertical, teto de vinil. A nossa base de dados associa este Virgo Classic à Albany e o compara ao Lincoln Continental Mark III.","search":"albany virgo classic lincoln continental mark iii","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Continental%20Mark%20III","reelNom":"Lincoln Continental Mark III","slot":"americain","thumb":"/img/schemas/albany-virgo-classic.svg"},{"id":"bravado-buffalo-stx","nom":"Buffalo STX","marque":"Bravado","cat":"muscle","st":"vu","insp":"2015 Dodge Charger","src":"Primeiro trailer","search":"bravado buffalo stx 2015 dodge charger","txt":"Versão esportiva do Buffalo, com o pacote completo: spoiler dianteiro, aerofólio, escapamentos à mostra. É o arquétipo do sedã americano que se recusa a ser comportado. O primeiro trailer o mostra alinhado numa cena de estacionamento, com as portas fechadas.","reel":"https://www.google.com/search?tbm=isch&q=2015%20Dodge%20Charger","reelNom":"2015 Dodge Charger","slot":"americain","thumb":"/img/schemas/bravado-buffalo-stx.svg"},{"id":"bravado-gauntlet-classic","nom":"Gauntlet Classic","marque":"Bravado","cat":"muscle","st":"vu","src":"Primeiro trailer","insp":"Dodge Challenger de primeira geração","txt":"O Gauntlet original, copiado do Dodge Challenger de primeira geração: capô interminável, caixas de roda bem marcadas, traseira truncada. É o muscle car de referência da Bravado há vários jogos. O primeiro trailer o mostra rodando por uma avenida cheia de palmeiras.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Challenger","reelNom":"Dodge Challenger","search":"bravado gauntlet classic dodge challenger premiere generation","slot":"americain","thumb":"/img/schemas/bravado-gauntlet-classic.svg"},{"id":"vapid-gauntlet-classic-custom","nom":"Gauntlet Classic Custom","marque":"Bravado","cat":"muscle","st":"comm","insp":"Dodge Challenger 1970","src":"Comparação da comunidade","search":"bravado gauntlet classic custom dodge challenger 1970","txt":"Versão preparada de um Dodge Challenger de 1970, um dos muscle cars mais procurados hoje em dia. A versão de 1970 é aquela cujo desenho é unanimidade, com a grade de quatro faróis e a linha de cintura reta. O sufixo Custom indica motor e chassi retrabalhados. Não confirmado pela Rockstar.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Challenger%201970","reelNom":"Dodge Challenger 1970","slot":"americain","thumb":"/img/schemas/vapid-gauntlet-classic-custom.svg"},{"id":"bravado-gauntlet-hellfire","nom":"Gauntlet Hellfire","marque":"Bravado","cat":"muscle","st":"vu","insp":"Dodge Challenger Demon 2018","src":"Primeiro trailer","search":"bravado gauntlet hellfire dodge challenger demon 2018","txt":"O Gauntlet Hellfire retoma o estilo do Dodge Challenger SRT Hellcat, um carro cuja ficha técnica é pura provocação: um V8 com compressor de mais de setecentos cavalos numa carroceria desenhada em 1970, sem nenhuma pretensão de sutileza. Ele virou um símbolo da recusa americana à moderação. O primeiro trailer o solta numa reta, com o capô vibrando.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Challenger%20Demon%202018","reelNom":"Dodge Challenger Demon 2018","slot":"americain","thumb":"/img/schemas/bravado-gauntlet-hellfire.svg"},{"id":"declasse-impaler-lx","nom":"Impaler ’80","marque":"Declasse","cat":"muscle","st":"vu","insp":"Chevrolet Impala de sexta geração","txt":"O Impaler de linha, sem o kit de carroceria do SZ. A sexta geração do Chevrolet Impala, a do fim dos anos 70, é um sedã imenso de teto plano e laterais retas, saído das linhas de montagem às centenas de milhares, tanto para frotas quanto para famílias. As capturas oficiais o enquadram ao longo de uma calçada.","search":"declasse impaler ’80 chevrolet impala sixieme generation","src":"Capturas oficiais","medias":["vice-city-09"],"imageAlts":{"vice-city-09":"Sedã azul em primeiro plano, sob o viaduto de Vice City no GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Impala","reelNom":"Chevrolet Impala","slot":"americain","thumb":"/img/officiel/vice-city-09-480.webp"},{"id":"declasse-impaler-sz","nom":"Impaler SZ","marque":"Declasse","cat":"muscle","st":"vu","insp":"1994-1996 Chevrolet Impala SS","src":"Capturas oficiais","search":"declasse impaler sz 1994-1996 chevrolet impala ss","txt":"A Declasse é a Chevrolet da série, e o Impaler é o grande sedã popular dela. A versão SZ é a variante esportiva, no espírito dos carros preparados de rua. O nome faz um jogo com o Impala, modelo onipresente na cultura automotiva americana. Este Impaler SZ está ligado às capturas oficiais na nossa base; o nome dele continua sendo uma identificação da comunidade.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Impala%20SS","reelNom":"Chevrolet Impala SS","slot":"americain","thumb":"/img/schemas/declasse-impaler-sz.svg"},{"id":"declasse-sabre-turbo","nom":"Sabre Turbo","marque":"Declasse","cat":"muscle","st":"vu","insp":"Chevrolet Chevelle, Oldsmobile Cutlass","src":"Primeiro trailer","search":"declasse sabre turbo chevrolet chevelle, oldsmobile cutlass","txt":"O Sabre Turbo mistura o Chevrolet Chevelle e o Oldsmobile Cutlass, dois intermediários da General Motors que dividiam a mesma plataforma no início dos anos 70. Era a grande época dos V8 enormes, interrompida bruscamente pelo choque do petróleo de 1973. O sufixo Turbo, por sua vez, vem da preparação: esses motores nunca foram turbinados de fábrica.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Chevelle","reelNom":"Chevrolet Chevelle","slot":"americain","thumb":"/img/schemas/declasse-sabre-turbo.svg"},{"id":"declasse-tulip","nom":"Tulip","marque":"Declasse","cat":"muscle","st":"vu","insp":"1972 Chevelle Malibu, 1972 Oldsmobile Cutlass Supreme","src":"Primeiro trailer","search":"declasse tulip 1972 chevelle malibu, 1972 oldsmobile cutlass supreme","txt":"O Tulip retoma o Chevelle Malibu e o Oldsmobile Cutlass Supreme de 1972, o último ano-modelo antes de as normas antipoluição sufocarem os motores americanos. Esses sedãs intermediários venderam aos milhões, por isso ainda dá para ver muitos por aí, muitas vezes em estado precário. É o carro de bairro, não o de colecionador.","medias":["trailer-1-vehicles-071"],"imageAlts":{"trailer-1-vehicles-071":"Sedã vermelho dirigido por Jason com Lucia, visto de lado no primeiro trailer do GTA VI por volta de 01:11"},"reel":"https://www.google.com/search?tbm=isch&q=1972%20Chevelle%20Malibu","reelNom":"1972 Chevelle Malibu","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-071-480.webp"},{"id":"declasse-tulip-m100","nom":"Tulip M100","marque":"Declasse","cat":"muscle","st":"vu","insp":"Chevrolet Malibu de quarta geração","src":"Primeiro trailer","search":"declasse tulip m100 chevrolet malibu quatrieme generation","txt":"Versão preparada do Tulip, no espírito dos muscle cars de bairro: motor trocado, suspensão refeita e um visual sem complexos. O sufixo M100 lembra os códigos de chassi que os preparadores usam para chamar seus carros-base. O primeiro trailer o mostra estacionado ao lado de uma casa de subúrbio.","medias":["trailer-1-vehicles-028"],"imageAlts":{"trailer-1-vehicles-028":"Sedã rosa elevado no centro, primeiro trailer do GTA VI aos 00:28"},"reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Malibu","reelNom":"Chevrolet Malibu","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-028-480.webp"},{"id":"declasse-vigero-zx-convertible","nom":"Vigero ZX Convertible","marque":"Declasse","cat":"muscle","st":"vu","insp":"Chevrolet Camaro de sexta geração","src":"Capturas oficiais","search":"declasse vigero zx convertible chevrolet camaro sixieme generation","txt":"Versão conversível do Vigero moderno, calcada no Chevrolet Camaro atual. O Camaro de hoje copia de propósito as proporções da geração de 1969, com uma linha de cintura alta que reduz muito a visibilidade, um sacrifício assumido em nome do estilo. As capturas oficiais mostram o carro de capota aberta, sob um céu limpo.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Camaro","reelNom":"Chevrolet Camaro","slot":"americain","thumb":"/img/schemas/declasse-vigero-zx-convertible.svg"},{"id":"declasse-voodoo","nom":"Voodoo","marque":"Declasse","cat":"muscle","st":"comm","insp":"Chevrolet Impala 1960","txt":"O lowrider clássico de Grand Theft Auto, presente desde o San Andreas. Carroceria rebaixada, suspensão hidráulica, pintura metalizada. Ele combina naturalmente com uma cidade quente e um cenário de avenidas largas.","search":"declasse voodoo chevrolet impala 1960","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Impala%201960","reelNom":"Chevrolet Impala 1960","slot":"americain","thumb":"/img/schemas/declasse-voodoo.svg"},{"id":"imponte-phoenix","nom":"Phoenix","marque":"Imponte","cat":"muscle","st":"vu","insp":"Pontiac Firebird de segunda geração","src":"Segundo trailer","search":"imponte phoenix pontiac firebird deuxieme generation","txt":"A Imponte é a Pontiac do universo GTA, uma marca que não existe mais na vida real, mas que continua central no imaginário automotivo americano. O Phoenix retoma o estilo do Firebird dos anos 70, com o capô enorme e o desenho de pássaro. O segundo trailer o enquadra de baixo para cima, aerofólio traseiro incluído.","reel":"https://www.google.com/search?tbm=isch&q=Pontiac%20Firebird","reelNom":"Pontiac Firebird","slot":"americain","thumb":"/img/schemas/imponte-phoenix.svg"},{"id":"imponte-ruiner","nom":"Ruiner","marque":"Imponte","cat":"muscle","st":"vu","insp":"Pontiac Trans Am/Chevrolet Camaro","src":"Primeiro trailer","search":"imponte ruiner pontiac trans am/chevrolet camaro","txt":"O Ruiner é o Pontiac Trans Am da série, um carro inseparável da cultura pop americana dos anos 70 e 80, popularizado pelo cinema e pela televisão. A silhueta, as entradas de ar e as faixas no capô fizeram mais pela fama dele do que o desempenho real. O primeiro trailer o mostra atravessando um cruzamento em alta velocidade.","reel":"https://www.google.com/search?tbm=isch&q=Pontiac%20Trans%20Am%2FChevrolet%20Camaro","reelNom":"Pontiac Trans Am/Chevrolet Camaro","slot":"americain","thumb":"/img/schemas/imponte-ruiner.svg"},{"id":"sirius","nom":"Sirius","marque":"Marca desconhecida","cat":"muscle","st":"vu","insp":"1970 Mercury Cougar","src":"Edição Ultimate","note":"O nome Sirius é legível no para-lama traseiro do muscle car turquesa da coleção Wyman.","vues":[],"credit":"Capture officielle Rockstar Games","search":"marque inconnue sirius 1970 mercury cougar","txt":"As capturas oficiais mostram um muscle car turquesa com faixas douradas, aerofólio na tampa do porta-malas e rodas de três raios, com o nome Sirius bem legível no para-lama traseiro. Nem a nossa lista anterior nem a dos outros sites mencionava esse modelo: é uma descoberta tirada diretamente do material da Rockstar. A silhueta é a de um Mercury Cougar de 1970, o primo mais caro do Mustang. O fabricante não foi divulgado.","edition":"Ultimate Edition","medias":["classic-car-collection-02"],"vuesDeclarees":["profil"],"reel":"https://www.google.com/search?tbm=isch&q=1970%20Mercury%20Cougar","reelNom":"1970 Mercury Cougar","slot":"americain","thumb":"/img/officiel/classic-car-collection-02-480.webp"},{"id":"schyster-deviant","nom":"Deviant","marque":"Schyster","cat":"muscle","st":"officiel","insp":"1972 AMC Javelin","src":"Edição Ultimate","vues":[],"credit":"Capture officielle Rockstar Games","search":"schyster deviant 1972 amc javelin","txt":"O nome do Deviant vem da Rockstar, pela apresentação da edição Ultimate, e a nossa captura oficial mostra o carro com as cores da bandeira americana, com o monograma em letra cursiva na coluna traseira e o interior visível pelo vidro. O AMC Javelin, do qual ele herda as proporções, era o azarão do mercado: fabricado por uma montadora independente bem menor que as três grandes de Detroit, ainda assim venceu o campeonato Trans-Am contra os Mustang e os Camaro.","edition":"Ultimate Edition","medias":["classic-car-collection-06"],"vuesDeclarees":["profil"],"reel":"https://www.google.com/search?tbm=isch&q=1972%20AMC%20Javelin","reelNom":"1972 AMC Javelin","slot":"americain","thumb":"/img/officiel/classic-car-collection-06-480.webp"},{"id":"vapid-chino","nom":"Chino","marque":"Vapid","cat":"muscle","st":"vu","insp":"Lincoln Continental e Chrysler Imperial de 1965","src":"Primeiro trailer","search":"vapid chino lincoln continental et chrysler imperial de 1965","txt":"O Chino é o cupê americano de segunda mão, aquele que você compra por quase nada e fica vinte anos com ele. Na série, ele está associado aos bairros populares e à cultura lowrider. O que conta nele não são tanto as qualidades, mas o que ele representa. A presença dele se baseia nas observações dos jogadores.","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Continental","reelNom":"Lincoln Continental","slot":"americain","thumb":"/img/schemas/vapid-chino.svg"},{"id":"vapid-chino-custom","nom":"Chino Custom","marque":"Vapid","cat":"muscle","st":"comm","insp":"Lincoln Continental Mark IV e V, preparado como lowrider","src":"Comparação da comunidade","search":"vapid chino custom lincoln continental mark iv et v, prepare en lowrider","txt":"Versão preparada do Chino: suspensão hidráulica, rodas raiadas, pintura em várias camadas. Em Vice City, essa estética não é um detalhe decorativo, e sim uma marca de pertencimento, herdada das comunidades cubana e porto-riquenha de Miami. Modelo não confirmado pela Rockstar.","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Continental%20Mark%20IV","reelNom":"Lincoln Continental Mark IV","slot":"americain","thumb":"/img/schemas/vapid-chino-custom.svg"},{"id":"vapid-dominator","nom":"Dominator","marque":"Vapid","cat":"muscle","st":"vu","insp":"Ford Mustang","src":"Primeiro trailer","search":"vapid dominator ford mustang","txt":"O Dominator é o Ford Mustang da série, e a Vapid faz o papel da Ford. O Mustang moderno dá continuidade a uma linhagem iniciada em 1964, com uma constante: motor grande na frente, tração traseira e um preço acessível de propósito. Ele foi catalogado a partir do primeiro trailer, sem nome divulgado pela Rockstar.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang","reelNom":"Ford Mustang","slot":"americain","thumb":"/img/schemas/vapid-dominator.svg"},{"id":"vapid-dominator-67","nom":"Dominator ’67","marque":"Vapid","cat":"muscle","st":"vu","src":"Capturas oficiais","insp":"Ford Mustang de primeira geração","txt":"O Dominator na sua forma original, a do Ford Mustang de primeira geração: grade larga, laterais esculpidas, traseira curta. É o ancestral de toda a linhagem, em configuração de rua, e não como buggy levantado. As capturas oficiais o colocam em uma coleção particular.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang","reelNom":"Ford Mustang","search":"vapid dominator ’67 ford mustang premiere generation","slot":"americain","thumb":"/img/schemas/vapid-dominator-67.svg"},{"id":"vapid-dominator-asp","nom":"Dominator ASP","marque":"Vapid","cat":"muscle","st":"vu","insp":"Ford Mustang SVT Cobra R (New Edge)","src":"Primeiro trailer","search":"vapid dominator asp ford mustang svt cobra r (new edge)","txt":"Versão preparada do Dominator, com apêndices aerodinâmicos e bitolas alargadas. A Ford sempre lançou versões cada vez mais radicais do Mustang, chegando a modelos que mal são homologados para as ruas. No primeiro trailer, ele aparece colado no para-choque de outro carro.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang%20SVT%20Cobra%20R%20(New%20Edge)","reelNom":"Ford Mustang SVT Cobra R (New Edge)","slot":"americain","thumb":"/img/schemas/vapid-dominator-asp.svg"},{"id":"vapid-dominator-buggy","nom":"Dominator Buggy ’67","marque":"Vapid","cat":"muscle","st":"officiel","insp":"Ford Mustang de 1967, preparada para off-road","src":"Página oficial da edição Ultimate","vues":[],"credit":"Capture officielle Rockstar Games","search":"vapid dominator buggy ’67 ford mustang de 1967, preparee tout-terrain","txt":"A Rockstar batizou este veículo na apresentação da edição Ultimate, e as nossas quatro capturas oficiais o mostram de todos os ângulos: carroceria azul com faixa amarela, número 6, pneus agrícolas, barra no teto com quatro faróis auxiliares, grade de tela atrás de um quebra-mato. O interior mantém o volante de três raios e o velocímetro original. Um Ford Mustang de 1967 levantado e preparado para a lama: sozinho, ele resume a Flórida rural dos pântanos, a poucos quilômetros dos arranha-céus de Vice City.","medias":["67-vapid-dominator-buggy-01","67-vapid-dominator-buggy-02","67-vapid-dominator-buggy-03","67-vapid-dominator-buggy-04"],"edition":"Ultimate Edition","vuesDeclarees":["face","profil","interieur","detail"],"reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang%20de%201967","reelNom":"Ford Mustang de 1967","slot":"americain","thumb":"/img/officiel/67-vapid-dominator-buggy-01-480.webp"},{"id":"vapid-dominator-gt","nom":"Dominator GT","marque":"Vapid","cat":"muscle","st":"vu","insp":"2018-2023 Ford Mustang Convertible","src":"Capturas oficiais","search":"vapid dominator gt 2018-2023 ford mustang convertible","txt":"Versão conversível do Dominator. O Mustang conversível existe desde a primeiríssima geração e representa uma boa parte das vendas na Flórida, onde o clima torna o teto quase desnecessário. As capturas oficiais o mostram em frente a uma mansão à beira-mar.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang%20Convertible","reelNom":"Ford Mustang Convertible","slot":"americain","thumb":"/img/schemas/vapid-dominator-gt.svg"},{"id":"vapid-dominator-gtx","nom":"Dominator GTX","marque":"Vapid","cat":"muscle","st":"vu","insp":"Ford Mustang e Dodge Charger atuais","src":"Primeiro trailer","search":"vapid dominator gtx ford mustang et dodge charger contemporaines","txt":"Outra variante do Dominator, na linha das séries especiais que a Ford não para de lançar para o Mustang: pinturas comemorativas, motores retrabalhados, unidades numeradas e limitadas. O Dominator GTX foi catalogado a partir do primeiro trailer, com um nome sugerido pela comunidade.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang","reelNom":"Ford Mustang","slot":"americain","thumb":"/img/schemas/vapid-dominator-gtx.svg"},{"id":"vapid-slamvan","nom":"Slamvan","marque":"Vapid","cat":"muscle","st":"vu","insp":"Ford F-Series 1953-1956 preparada como rat rod","src":"Primeiro trailer","search":"vapid slamvan ford f-series 1953-1956 prepare rat rod","txt":"O Slamvan é uma picape colada no chão, a meio caminho entre o custom e o veículo de exibição. Rebaixar picapes é uma tradição da Califórnia e do Texas, nascida nos anos 80 em torno das minipicapes japonesas. A versão registrada aqui está ligada ao primeiro trailer, sem nome oficial divulgado.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-Series%20pr%C3%A9par%C3%A9%20rat%20rod","reelNom":"Ford F-Series preparada como rat rod","slot":"americain","thumb":"/img/schemas/vapid-slamvan.svg"},{"id":"willard-faction","nom":"Faction","marque":"Willard","cat":"muscle","st":"comm","insp":"Buick Regal dos anos 80","txt":"Cupê americano de duas portas do fim dos anos 80, base histórica do lowrider na série. Linhas retas, coluna traseira larga, grade fina.","search":"willard faction buick regal des annees 80","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Regal%20des%20ann%C3%A9es%2080","reelNom":"Buick Regal dos anos 80","slot":"americain","thumb":"/img/schemas/willard-faction.svg"},{"id":"willard-faction-custom-donk","nom":"Faction Custom Donk","marque":"Willard","cat":"muscle","st":"comm","insp":"Buick Regal em configuração donk","txt":"O donk é um estilo de customização nascido no sul dos Estados Unidos, principalmente em Miami: carroceria elevada, rodas de diâmetro enorme, pintura chamativa. É um dos poucos estilos de carro realmente enraizados na região que Leonida representa.","search":"willard faction custom donk buick regal en configuration donk","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Regal%20en%20configuration%20donk","reelNom":"Buick Regal em configuração donk","slot":"americain","thumb":"/img/schemas/willard-faction-custom-donk.svg"},{"id":"albany-cavalcade-xl","nom":"Cavalcade XL","marque":"Albany","cat":"suv","st":"vu","insp":"Cadillac Escalade-V 2023","src":"Capturas oficiais","txt":"O SUV de luxo americano na sua versão mais chamativa. O Escalade-V, do qual ele herda o visual, leva um V8 com compressor de seis litros numa carroceria de duas toneladas e meia. É o veículo de status por excelência, o das comitivas e dos clipes.","search":"albany cavalcade xl cadillac escalade-v 2023","reel":"https://www.google.com/search?tbm=isch&q=Cadillac%20Escalade-V%202023","reelNom":"Cadillac Escalade-V 2023","slot":"americain","thumb":"/img/schemas/albany-cavalcade-xl.svg"},{"id":"benefactor-dubsta","nom":"Dubsta","marque":"Benefactor","cat":"suv","st":"vu","insp":"Mercedes-Benz G-Class","src":"Primeiro trailer","search":"benefactor dubsta mercedes-benz g-class","txt":"O Dubsta retoma o estilo do Mercedes-Benz Classe G, um veículo criado originalmente para o exército e que continuou em produção quase sem mudanças por quarenta anos. O sucesso dele vem de um paradoxo: uma máquina militar que virou objeto de luxo urbano, vendida a preço de ouro em bairros onde nunca vai precisar encarar obstáculo nenhum. O primeiro trailer o mostra subindo numa calçada, de para-choque na frente.","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20G-Class","reelNom":"Mercedes-Benz G-Class","slot":"europeen","thumb":"/img/schemas/benefactor-dubsta.svg"},{"id":"benefactor-xls","nom":"XLS","marque":"Benefactor","cat":"suv","st":"vu","insp":"Mercedes-Benz Classe GL","src":"Extended Look","txt":"SUV alemão grande, com três fileiras de bancos, entre o Mercedes GL e o BMW X5. Visto no Extended Look. É o formato do SUV de diretoria, comprido o bastante para sete lugares e luxuoso o bastante para nunca sair do asfalto.","search":"benefactor xls mercedes-benz classe gl","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20Classe%20GL","reelNom":"Mercedes-Benz Classe GL","slot":"europeen","thumb":"/img/schemas/benefactor-xls.svg"},{"id":"bravado-dorado","nom":"Dorado","marque":"Bravado","cat":"suv","st":"vu","insp":"Dodge Durango de primeira geração","src":"Capturas oficiais","search":"bravado dorado dodge durango premiere generation","txt":"O Dorado se baseia no Dodge Durango de primeira geração, lançado em 1998 sobre a base da picape Dakota. Foi a resposta da Chrysler à virada do mercado americano para o SUV familiar: três fileiras de bancos, capacidade de reboque e um consumo de combustível com que ninguém se preocupava ainda.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Durango","reelNom":"Dodge Durango","slot":"americain","thumb":"/img/schemas/bravado-dorado.svg"},{"id":"enus-jubilee","nom":"Jubilee","marque":"Buckingham","cat":"suv","st":"vu","insp":"Rolls-Royce Cullinan","src":"Primeiro trailer","search":"buckingham jubilee rolls-royce cullinan","txt":"O Jubilee é o SUV de altíssimo luxo da linha, inspirado no Rolls-Royce Cullinan. A chegada dele ao mundo real marcou uma virada: uma marca que sempre tinha recusado o off-road entrou nesse segmento porque ele virou sua principal fonte de lucro. Portas suicidas, grade vertical, carroceria alta sem disfarce.","reel":"https://www.google.com/search?tbm=isch&q=Rolls-Royce%20Cullinan","reelNom":"Rolls-Royce Cullinan","slot":"europeen","thumb":"/img/schemas/enus-jubilee.svg"},{"id":"canis-mesa","nom":"Mesa","marque":"Canis","cat":"suv","st":"vu","insp":"Jeep Wrangler","src":"Imagem oficial da edição Ultimate","note":"O emblema Canis é legível na grade da picape verde apresentada na oficina One-Eyed Willie.","vues":[],"credit":"Capture officielle Rockstar Games","search":"canis mesa jeep wrangler","txt":"Nossas capturas oficiais mostram esta picape de quatro portas verde vivo na oficina One-Eyed Willie, com o emblema Canis legível por extenso na grade, um guincho, ganchos de reboque e um protetor de cárter sob o motor. Uma vista da oficina a mostra de capô aberto, em plena preparação. A silhueta lembra os off-road de chassi de escada do tipo Jeep. O modelo não é nomeado pela Rockstar.","vuesDeclarees":["face","profil","detail"],"reel":"https://www.google.com/search?tbm=isch&q=Jeep%20Wrangler","reelNom":"Jeep Wrangler","slot":"americain","thumb":"/img/schemas/canis-mesa.svg"},{"id":"declasse-seminole-frontier","nom":"Seminole Frontier","marque":"Canis","cat":"suv","st":"vu","insp":"Jeep Cherokee XJ de segunda geração","txt":"SUV compacto de carroceria angulosa, caixas de roda retas, coluna traseira vertical. O nome remete ao povo seminole da Flórida, cujo território histórico cobre parte do que o jogo chama de Leonida.","search":"canis seminole frontier jeep cherokee xj deuxieme generation","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Jeep%20Cherokee%20XJ","reelNom":"Jeep Cherokee XJ","slot":"americain","thumb":"/img/schemas/declasse-seminole-frontier.svg"},{"id":"canis-terminus","nom":"Terminus","marque":"Canis","cat":"suv","st":"vu","insp":"Jeep Wrangler Rubicon de quarta geração","src":"Extended Look","txt":"Veículo off-road curto com santantônio aparente, baseado no atual Wrangler Rubicon. O Wrangler continua sendo um dos poucos 4x4 populares a manter eixos rígidos e teto removível, o que explica sua presença em todas as áreas alagadas da Flórida. Visto no Extended Look.","reel":"https://www.google.com/search?tbm=isch&q=Jeep%20Wrangler%20Rubicon","reelNom":"Jeep Wrangler Rubicon","search":"canis terminus jeep wrangler rubicon quatrieme generation","slot":"americain","thumb":"/img/schemas/canis-terminus.svg"},{"id":"declasse-granger","nom":"Granger","marque":"Declasse","cat":"suv","st":"vu","insp":"Chevrolet Suburban","src":"Segundo trailer","search":"declasse granger chevrolet suburban","txt":"O Granger é o grande SUV americano de chassi separado, baseado no Chevrolet Suburban. Esse tipo de veículo ocupa um lugar especial nos Estados Unidos: carro de família, veículo de serviço, viatura das forças de segurança, tudo ao mesmo tempo. Ele aparece no segundo trailer.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Suburban","reelNom":"Chevrolet Suburban","slot":"americain","thumb":"/img/schemas/declasse-granger.svg"},{"id":"declasse-granger-3600lx","nom":"Granger 3600LX","marque":"Declasse","cat":"suv","st":"vu","insp":"Chevrolet Suburban 2015-2020","src":"Primeiro trailer","search":"declasse granger 3600lx chevrolet suburban 2015-2020","txt":"Versão topo de linha do Granger, no espírito dos acabamentos de luxo que a General Motors aplica sobre seus SUVs grandes: couro, cromados, rodas de vinte e duas polegadas. O veículo aparece no primeiro trailer.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Suburban","reelNom":"Chevrolet Suburban","slot":"americain","thumb":"/img/schemas/declasse-granger-3600lx.svg"},{"id":"dundreary-landstalker-xl","nom":"Landstalker XL","marque":"Dundreary","cat":"suv","st":"vu","insp":"Lincoln Navigator de quarta geração","src":"Segundo trailer","search":"dundreary landstalker xl lincoln navigator quatrieme generation","txt":"O Landstalker XL segue o Lincoln Navigator de quarta geração, o grande SUV de luxo americano na versão mais imponente. A Lincoln levou ao extremo a ideia da sala de estar sobre rodas: três fileiras de bancos, acabamento em couro, tela panorâmica. É o veículo dos bairros ricos de Vice City, aquele que você para na porta do hotel sem nem descer.","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Navigator","reelNom":"Lincoln Navigator","slot":"americain","thumb":"/img/schemas/dundreary-landstalker-xl.svg"},{"id":"gallivanter-baller","nom":"Baller II","marque":"Gallivanter","cat":"suv","st":"vu","insp":"Range Rover Evoque e Range Rover Sport","src":"Capturas oficiais","search":"gallivanter baller ii range rover evoque et range rover sport","txt":"A Gallivanter é a Land Rover do universo GTA, e o Baller é a versão urbana dela, com base no Range Rover Sport. O modelo real mostra uma mudança reveladora: nasceu como utilitário agrícola britânico e virou o carro preferido dos bairros nobres, com uma capacidade off-road que ninguém nunca usa.","reel":"https://www.google.com/search?tbm=isch&q=Range%20Rover%20Evoque","reelNom":"Range Rover Evoque","slot":"europeen","thumb":"/img/schemas/gallivanter-baller.svg"},{"id":"gallivanter-baller-st","nom":"Baller ST-D","marque":"Gallivanter","cat":"suv","st":"vu","insp":"Range Rover L460","txt":"A versão esportiva do Baller: para-choque redesenhado, quatro saídas de escapamento, rodas de grande diâmetro. O SUV de luxo rápido é um arquétipo que combina perfeitamente com os bairros ricos de Vice City.","search":"gallivanter baller st-d range rover l460","src":"Capturas oficiais","reel":"https://www.google.com/search?tbm=isch&q=Range%20Rover%20L460","reelNom":"Range Rover L460","slot":"europeen","thumb":"/img/schemas/gallivanter-baller-st.svg"},{"id":"vapid-contender","nom":"Contender","marque":"Karin","cat":"suv","st":"vu","insp":"Ford F-150 Raptor e Toyota Tundra preparada","src":"Capturas oficiais","search":"karin contender ford f-150 raptor et toyota tundra prepare","txt":"Picape grande baseada na Toyota Tundra preparada, com toques da Ford F-150 Raptor: a categoria das picapes de lazer levantadas, feitas mais para a terra do que para a cidade. As capturas oficiais mostram o Contender lá no alto, em cima dos pneus lameiros.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-150%20Raptor","reelNom":"Ford F-150 Raptor","slot":"japonais","thumb":"/img/schemas/vapid-contender.svg"},{"id":"karin-vivanite","nom":"Vivanite","marque":"Karin","cat":"suv","st":"vu","insp":"Toyota Sienna de quarta geração","src":"Extended Look","txt":"Minivan japonesa vista no Extended Look. A Sienna cujas linhas ela copia passou a ser híbrida de série, uma escolha rara nesse segmento. Como a Karin é a Toyota do universo GTA, o parentesco é claro.","search":"karin vivanite toyota sienna quatrieme generation","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20Sienna","reelNom":"Toyota Sienna","slot":"japonais","thumb":"/img/schemas/karin-vivanite.svg"},{"id":"lampadati-novak","nom":"Novak","marque":"Lampadati","cat":"suv","st":"vu","insp":"Maserati Levante","src":"Capturas oficiais","txt":"SUV italiano de luxo, entre o Maserati Levante e o Alfa Romeo Stelvio. A Lampadati representa essas duas marcas no universo GTA. O desafio é colocar o caráter de um sedã esportivo numa carroceria elevada, com resultados que dividem opiniões.","search":"lampadati novak maserati levante","reel":"https://www.google.com/search?tbm=isch&q=Maserati%20Levante","reelNom":"Maserati Levante","slot":"europeen","thumb":"/img/schemas/lampadati-novak.svg"},{"id":"mammoth-patriot-mil-spec","nom":"Patriot Mil-Spec","marque":"Mammoth","cat":"suv","st":"vu","insp":"Hummer H1","src":"Extended Look","txt":"Versão militar do Patriot, inspirada no Hummer H1 civil, derivado do Humvee do Exército americano. Largo, lento e beberrão, ele nunca teve outro argumento além da capacidade de passar por qualquer lugar e do visual. Visto no Extended Look.","reel":"https://www.google.com/search?tbm=isch&q=Hummer%20H1","reelNom":"Hummer H1","search":"mammoth patriot mil-spec hummer h1","thumb":"/img/schemas/mammoth-patriot-mil-spec.svg"},{"id":"dodge-durango-3","nom":"Durango","marque":"Marca desconhecida","cat":"suv","st":"vu","insp":"Dodge Durango de terceira geração","src":"Segundo trailer","txt":"SUV familiar americano de terceira geração, oferecido nas versões mais potentes com motores que de familiar não têm nada. Não confundir com o Dorado, que se baseia na primeira geração. Nome no jogo não divulgado.","search":"marque inconnue durango dodge durango troisieme generation","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Durango","reelNom":"Dodge Durango","slot":"americain","thumb":"/img/schemas/dodge-durango-3.svg"},{"id":"ford-explorer-2","nom":"Explorer ’95","marque":"Marca desconhecida","cat":"suv","st":"vu","insp":"Ford Explorer de segunda geração","src":"Primeiro trailer","txt":"O SUV que virou o mercado americano de cabeça para baixo. A segunda geração do Explorer, vendida aos milhões nos anos 90, convenceu as famílias a largar a perua. Nome no jogo não divulgado.","search":"marque inconnue explorer ’95 ford explorer deuxieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Explorer","reelNom":"Ford Explorer","slot":"americain","thumb":"/img/schemas/ford-explorer-2.svg"},{"id":"audi-q7-2","nom":"Q7","marque":"Marca desconhecida","cat":"suv","st":"vu","insp":"Audi Q7 de segunda geração","src":"Primeiro trailer","txt":"SUV alemão grande, com três fileiras de bancos, de segunda geração. O Audi Q7 inaugurou na marca uma linha que hoje representa a maior parte das vendas dela, à custa dos sedãs que fizeram a sua fama. Nome no jogo não divulgado.","search":"marque inconnue q7 audi q7 deuxieme generation","reel":"https://www.google.com/search?tbm=isch&q=Audi%20Q7","reelNom":"Audi Q7","slot":"europeen","thumb":"/img/schemas/audi-q7-2.svg"},{"id":"toyota-rav4-5","nom":"RAV4","marque":"Marca desconhecida","cat":"suv","st":"vu","insp":"Toyota RAV4 de quinta geração","src":"Segundo trailer","txt":"SUV compacto japonês, o veículo mais vendido do mundo, somando todas as categorias, há vários anos. A presença dele no trânsito de Leonida é puro realismo estatístico. Nome no jogo não divulgado.","search":"marque inconnue rav4 toyota rav4 cinquieme generation","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20RAV4","reelNom":"Toyota RAV4","slot":"japonais","thumb":"/img/schemas/toyota-rav4-5.svg"},{"id":"pegassi-toros","nom":"Toros","marque":"Pegassi","cat":"suv","st":"vu","insp":"Lamborghini Urus e Audi Q8","src":"Capturas oficiais","search":"pegassi toros lamborghini urus et audi q8","txt":"O Toros repete a fórmula do Lamborghini Urus: um SUV construído sobre uma plataforma de produção em massa, vestido com o estilo da marca e equipado com um motor extremo. Comercialmente, foi o modelo que permitiu à Lamborghini dobrar a produção. Ele aparece nas capturas oficiais.","reel":"https://www.google.com/search?tbm=isch&q=Lamborghini%20Urus","reelNom":"Lamborghini Urus","slot":"europeen","thumb":"/img/schemas/pegassi-toros.svg"},{"id":"pfister-astron","nom":"Astron","marque":"Pfister","cat":"suv","st":"vu","insp":"Porsche Macan","src":"Segundo trailer","search":"pfister astron porsche macan","txt":"O Astron é o SUV da Pfister, baseado no Porsche Macan, o irmão mais novo do Cayenne. O Cayenne causou escândalo entre os puristas da marca no lançamento, em 2002, antes de virar o modelo que bancou a permanência dos esportivos no catálogo. A Rockstar deixou o Astron aparecer no segundo trailer.","reel":"https://www.google.com/search?tbm=isch&q=Porsche%20Macan","reelNom":"Porsche Macan","slot":"europeen","thumb":"/img/schemas/pfister-astron.svg"},{"id":"ubermacht-rebla-gts","nom":"Rebla GTS","marque":"Übermacht","cat":"suv","st":"vu","insp":"BMW X5 de quarta geração","txt":"SUV cupê alemão, teto caído e tampa traseira inclinada. O Rebla ocupa o nicho do SUV que tenta parecer um sedã esportivo, nicho inventado justamente pelo modelo que o inspira.","search":"ubermacht rebla gts bmw x5 quatrieme generation","src":"Extended Look","reel":"https://www.google.com/search?tbm=isch&q=BMW%20X5","reelNom":"BMW X5","slot":"europeen","thumb":"/img/schemas/ubermacht-rebla-gts.svg"},{"id":"vapid-aleutian","nom":"Aleutian","marque":"Vapid","cat":"suv","st":"vu","insp":"Ford Expedition de quarta geração","src":"Segundo trailer","search":"vapid aleutian ford expedition quatrieme generation","txt":"SUV americano grande, com três fileiras de bancos, o Aleutian pertence àquela categoria de veículos feitos para levar sete pessoas e a bagagem delas em longas viagens de rodovia. O segundo trailer o mostra na entrada da garagem de uma casa, com a tampa traseira aberta.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Expedition","reelNom":"Ford Expedition","slot":"americain","thumb":"/img/schemas/vapid-aleutian.svg"},{"id":"vapid-montagne","nom":"Montagne","marque":"Vapid","cat":"suv","st":"vu","insp":"Ford Explorer de sexta geração","src":"Segundo trailer","txt":"O Explorer atual, que voltou à tração traseira depois de vinte anos de tração dianteira. Como a Vapid é a Ford desse universo, a associação é direta. É o SUV de polícia mais comum nos Estados Unidos hoje, e também aparece em versão civil.","search":"vapid montagne ford explorer sixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Explorer","reelNom":"Ford Explorer","slot":"americain","thumb":"/img/schemas/vapid-montagne.svg"},{"id":"vapid-riata-classic","nom":"Riata Classic","marque":"Vapid","cat":"suv","st":"officiel","insp":"Ford Bronco de primeira geração","src":"Edição Ultimate","vues":[],"credit":"Capture officielle Rockstar Games","search":"vapid riata classic ford bronco premiere generation","txt":"Foi a Rockstar que deu nome ao Riata Classic, de passagem, ao apresentar a edição Ultimate, e nossa captura oficial mostra o perfil dele: carroceria creme, faixas laterais em degradê vermelho e amarelo, pneus off-road, monograma cursivo no para-lama. O Ford Bronco de primeira geração, que inspirou o visual dele, era um utilitário simples, pouco mais que um chassi com uma carroceria, e desde então virou um item de colecionador disputado.","edition":"Ultimate Edition","medias":["classic-car-collection-03"],"vuesDeclarees":["profil"],"reel":"https://www.google.com/search?tbm=isch&q=Ford%20Bronco","reelNom":"Ford Bronco","slot":"americain","thumb":"/img/officiel/classic-car-collection-03-480.webp"},{"id":"annis-hellion","nom":"Hellion","marque":"Annis","cat":"pickup","st":"vu","insp":"Nissan Patrol Safari Y6, Jeep Cherokee (XJ)","src":"Primeiro trailer","search":"annis hellion nissan patrol safari y6, jeep cherokee (xj)","txt":"O Hellion é o off-road da Annis, algo incomum para uma marca associada aos esportivos japoneses. A silhueta compacta e quadradona lembra os 4x4 japoneses dos anos 80, feitos para encarar obstáculos e não para dar conforto. Ele aparece rapidamente no primeiro trailer.","reel":"https://www.google.com/search?tbm=isch&q=Nissan%20Patrol%20Safari%20Y6","reelNom":"Nissan Patrol Safari Y6","slot":"japonais","thumb":"/img/schemas/annis-hellion.svg"},{"id":"bravado-bison-900-95-monster-truck","nom":"Bison 900 ’95 Monster Truck","marque":"Bravado","cat":"pickup","st":"vu","insp":"Dodge Ram de segunda geração em configuração monster truck","src":"Capturas oficiais","txt":"O Bison 900 ’95 montado sobre eixos elevados e pneus agrícolas. O monster truck nasceu no sul dos Estados Unidos no fim dos anos 70, quando donos de picapes começaram a colocar rodas cada vez maiores, até aquilo virar espetáculo. A Flórida tem várias pistas desse tipo.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Ram%20en%20configuration%20monster%20truck","reelNom":"Dodge Ram em configuração monster truck","search":"bravado bison 900 ’95 monster truck dodge ram deuxieme generation en configuration monster truck","slot":"americain","thumb":"/img/schemas/bravado-bison-900-95-monster-truck.svg"},{"id":"canis-kamacho","nom":"Kamacho","marque":"Canis","cat":"pickup","st":"vu","insp":"Jeep Crew Chief 715 concept","txt":"Veículo off-road de carroceria recortada e pneus com garras, feito para andar fora de estrada. Os pântanos e as trilhas do interior de Leonida dão a ele um uso real, e não apenas decorativo.","search":"canis kamacho jeep crew chief 715 concept","src":"Capturas oficiais","medias":["one-eyed-willie-s-mod-shop-01","ultimate-edition-one-eyed-willie-03"],"imageAlts":{"one-eyed-willie-s-mod-shop-01":"Picape Canis verde preparada na One-Eyed Willie no GTA VI.","ultimate-edition-one-eyed-willie-03":"Picape Canis verde na oficina One-Eyed Willie, em GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Jeep%20Crew%20Chief%20715%20concept","reelNom":"Jeep Crew Chief 715 concept","slot":"americain","thumb":"/img/officiel/one-eyed-willie-s-mod-shop-01-480.webp"},{"id":"declasse-rancher","nom":"Rancher","marque":"Declasse","cat":"pickup","st":"vu","insp":"Chevrolet Suburban","src":"Capturas oficiais","search":"declasse rancher chevrolet suburban","txt":"O Rancher é um off-road utilitário de geração antiga, mais próximo de máquina agrícola do que de veículo de lazer. Na série, ele é associado a zonas rurais, o que combina com os pântanos e as fazendas do norte de Leonida. Aparece nas capturas divulgadas pela Rockstar.","medias":["trailer-2-rancher-035"],"imageAlts":{"trailer-2-rancher-035":"Picape vermelha e branca, com dois passageiros na caçamba, na frente do carro de Jason na via expressa, segundo trailer do GTA VI por volta de 00:35."},"reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Suburban","reelNom":"Chevrolet Suburban","slot":"americain","thumb":"/img/officiel/trailer-2-rancher-035-480.webp"},{"id":"declasse-walton-l35-stock","nom":"Walton L35","marque":"Declasse","cat":"pickup","st":"vu","insp":"Chevrolet S-10 1991-1993","src":"Capturas oficiais","search":"declasse walton l35 chevrolet s-10 1991-1993","txt":"Pequena picape de trabalho à moda antiga, cabine simples e caçamba curta. A Chevrolet S-10 do início dos anos 90 era a picape compacta de trabalho mais barata do mercado americano, vendida para profissionais de ofício e para fazendas. Seu valor volta a subir desde que a categoria sumiu dos catálogos.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20S-10","reelNom":"Chevrolet S-10","slot":"americain","thumb":"/img/schemas/declasse-walton-l35-stock.svg"},{"id":"declasse-yosemite","nom":"Yosemite","marque":"Declasse","cat":"pickup","st":"comm","insp":"Chevrolet C10 dos anos 60","txt":"Picape americana clássica de cabine simples, que muitas vezes vira veículo de coleção. A variante 1500 já está nesta base.","search":"declasse yosemite chevrolet c10 des annees 60","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20C10%20des%20ann%C3%A9es%2060","reelNom":"Chevrolet C10 dos anos 60","slot":"americain","thumb":"/img/schemas/declasse-yosemite.svg"},{"id":"declasse-yosemite-1500","nom":"Yosemite 1500","marque":"Declasse","cat":"pickup","st":"vu","insp":"Chevrolet Silverado de primeira geração","src":"Capturas oficiais","search":"declasse yosemite 1500 chevrolet silverado premiere generation","txt":"O Yosemite 1500 segue a Chevrolet Silverado de primeira geração, lançada em 1999 para substituir a C/K. Foi a picape que levou a categoria para o conforto de um sedã: cabine estendida, quatro portas, acabamento cromado. Ele aparece nas capturas oficiais.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Silverado","reelNom":"Chevrolet Silverado","slot":"americain","thumb":"/img/schemas/declasse-yosemite-1500.svg"},{"id":"dinka-verus","nom":"Verus","marque":"Dinka","cat":"pickup","st":"vu","insp":"Polaris Sportsman MV850","txt":"Quadriciclo off-road, chassi tubular e pneus largos. O veículo das trilhas de areia e dos lugares onde nenhum carro passa.","search":"dinka verus polaris sportsman mv850","src":"Capturas oficiais","reel":"https://www.google.com/search?tbm=isch&q=Polaris%20Sportsman%20MV850","reelNom":"Polaris Sportsman MV850","thumb":"/img/schemas/dinka-verus.svg"},{"id":"bravado-rebel","nom":"Rebel","marque":"Karin","cat":"pickup","st":"vu","insp":"Toyota Hilux","src":"Capturas oficiais","search":"karin rebel toyota hilux","txt":"O Rebel se baseia na Toyota Hilux, uma picape tão famosa por ser indestrutível que virou o veículo de referência das zonas de conflito e das expedições. A simplicidade mecânica é justamente o que faz o valor dela. Ele aparece nas capturas oficiais.","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20Hilux","reelNom":"Toyota Hilux","slot":"japonais","thumb":"/img/schemas/bravado-rebel.svg"},{"id":"dodge-dakota-convertible","nom":"Dakota Conversível","marque":"Marca desconhecida","cat":"pickup","st":"vu","insp":"Dodge Dakota Convertible","src":"Primeiro trailer","txt":"Uma curiosidade automotiva: uma picape conversível, fabricada pela Dodge em apenas alguns milhares de unidades no fim dos anos 80. A ideia nunca pegou, o que hoje a torna uma peça de colecionador improvável. Nome no jogo não divulgado.","search":"marque inconnue dakota decapotable dodge dakota convertible","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Dakota%20Convertible","reelNom":"Dodge Dakota Convertible","slot":"americain","thumb":"/img/schemas/dodge-dakota-convertible.svg"},{"id":"ford-explorer-sport-trac","nom":"Explorer Sport Trac","marque":"Marca desconhecida","cat":"pickup","st":"vu","src":"Extended Look","insp":"Ford Explorer Sport Trac","txt":"O Ford Explorer Sport Trac, aquele SUV de caçamba curta que fica no meio do caminho entre a perua e a picape, na versão civil. É o mesmo chassi do exemplar com pintura de salva-vidas, com carroceria de série. No Extended Look, ele aparece parado num estacionamento à beira da praia.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Explorer%20Sport%20Trac","reelNom":"Ford Explorer Sport Trac","search":"marque inconnue explorer sport trac ford explorer sport trac","slot":"americain","thumb":"/img/schemas/ford-explorer-sport-trac.svg"},{"id":"ford-f-series-3","nom":"F-Series ’50","marque":"Marca desconhecida","cat":"pickup","st":"vu","insp":"Ford F-Series de terceira geração","src":"Capturas oficiais","txt":"Picape Ford dos anos 50, terceira geração, a das grades largas e dos para-lamas arredondados. É a silhueta que todo mundo associa às fazendas e aos postos de gasolina daquela época, e uma base muito procurada pelos preparadores. Nome no jogo não divulgado.","search":"marque inconnue f-series ’50 ford f-series troisieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-Series","reelNom":"Ford F-Series","slot":"americain","thumb":"/img/schemas/ford-f-series-3.svg"},{"id":"ram-3500","nom":"RAM 3500","marque":"Marca desconhecida","cat":"pickup","st":"vu","insp":"RAM 3500","src":"Primeiro trailer","txt":"Picape pesada, com rodado duplo na traseira, feita para rebocar cargas que nada mais consegue puxar. É o veículo de quem transporta cavalos, barcos e trailers de camping. Nome no jogo não divulgado.","search":"marque inconnue ram 3500 ram 3500","reel":"https://www.google.com/search?tbm=isch&q=RAM%203500","reelNom":"RAM 3500","thumb":"/img/schemas/ram-3500.svg"},{"id":"jeep-scrambler-cj8","nom":"Scrambler CJ-8","marque":"Marca desconhecida","cat":"pickup","st":"vu","insp":"Jeep Scrambler CJ-8","src":"Capturas oficiais","txt":"Jeep CJ de entre-eixos alongado, com uma pequena caçamba atrás, fabricado de 1981 a 1986. Vendeu pouco na época, mas virou objeto de culto entre os fãs de off-road. Nome no jogo não divulgado.","search":"marque inconnue scrambler cj-8 jeep scrambler cj-8","reel":"https://www.google.com/search?tbm=isch&q=Jeep%20Scrambler%20CJ-8","reelNom":"Jeep Scrambler CJ-8","slot":"americain","thumb":"/img/schemas/jeep-scrambler-cj8.svg"},{"id":"swamp-buggy","nom":"Swamp Buggy","marque":"Marca desconhecida","cat":"pickup","st":"vu","insp":"Swamp buggy de Palm Beach","src":"Primeiro trailer","txt":"Veículo de pântano montado sobre rodas enormes, uma especialidade do sul da Flórida. Lá, os swamp buggies disputam corridas desde os anos 40, em lagoas de lama e não em pistas. Aparece no primeiro trailer. O nome dele no jogo não foi divulgado.","reel":"https://www.google.com/search?tbm=isch&q=Swamp%20buggy%20de%20Palm%20Beach","reelNom":"Swamp buggy de Palm Beach","search":"marque inconnue swamp buggy swamp buggy de palm beach","thumb":"/img/schemas/swamp-buggy.svg"},{"id":"nagasaki-blazer","nom":"Blazer","marque":"Nagasaki","cat":"pickup","st":"vu","insp":"Yamaha YFZ450","src":"Primeiro trailer","search":"nagasaki blazer yamaha yfz450","txt":"O Blazer é um quadriciclo de lazer, um veículo de quatro rodas com guidão feito para areia e trilhas. A Flórida, com suas praias e trilhas na mata, é um dos mercados mais aquecidos para esse tipo de máquina. O quadriciclo aparece em várias cenas do primeiro trailer.","reel":"https://www.google.com/search?tbm=isch&q=Yamaha%20YFZ450","reelNom":"Yamaha YFZ450","slot":"japonais","thumb":"/img/schemas/nagasaki-blazer.svg"},{"id":"nagasaki-outlaw","nom":"Outlaw","marque":"Nagasaki","cat":"pickup","st":"vu","insp":"Can-Am Maverick X3 Turbo","src":"Primeiro trailer","search":"nagasaki outlaw can-am maverick x3 turbo","txt":"Buggy off-road de estrutura tubular, o Outlaw fica entre o quadriciclo e o carro: gaiola de proteção completa, dois lugares lado a lado, suspensão de longo curso. O buggy aparece no primeiro trailer.","reel":"https://www.google.com/search?tbm=isch&q=Can-Am%20Maverick%20X3%20Turbo","reelNom":"Can-Am Maverick X3 Turbo","thumb":"/img/schemas/nagasaki-outlaw.svg"},{"id":"vapid-caracara","nom":"Caracara","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford F-150, Hennessey VelociRaptor 6X6","txt":"A versão básica do Caracara, antes da variante 4x4 reforçada. Picape compacta de cabine simples, pensada mais para a terra do que para a rodovia.","search":"vapid caracara ford f-150, hennessey velociraptor 6x6","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-150","reelNom":"Ford F-150","slot":"americain","thumb":"/img/schemas/vapid-caracara.svg"},{"id":"vapid-caracara-4x4","nom":"Caracara 4x4","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford F-150 Raptor de segunda geração","src":"Segundo trailer","search":"vapid caracara 4x4 ford f-150 raptor deuxieme generation","txt":"O Caracara 4x4 traz para o jogo a Ford F-150 Raptor, uma picape feita para andar rápido na terra, e não para vencer obstáculos devagar. A suspensão de longo curso vem direto das corridas no deserto de Baja. Ele aparece no segundo trailer.","medias":["trailer-2-caracara-016","brian-heder-01"],"imageAlts":{"trailer-2-caracara-016":"Brian Heder na frente da picape Vapid dele no Trailer 2 oficial do GTA VI.","brian-heder-01":"Brian Heder ao volante da sua picape em uma captura oficial de GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-150%20Raptor","reelNom":"Ford F-150 Raptor","slot":"americain","thumb":"/img/officiel/trailer-2-caracara-016-480.webp"},{"id":"vapid-ganado","nom":"Ganado ’70","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford Ranchero 1970, Mercury Cougar 1969-1970","src":"Capturas oficiais","note":"O nome Ganado e a inscrição 434ci são legíveis na picape cupê estacionada na frente do esconderijo de Jason.","vues":[],"credit":"Capture officielle Rockstar Games","search":"vapid ganado ’70 creado ford ranchero 1970, mercury cougar 1969-1970","txt":"As nossas capturas oficiais mostram esta picape cupê amarela com faixas vermelhas em frente ao esconderijo de Jason, nos Keys. Dá para ler o nome Ganado no para-lama e no painel, junto com a inscrição 434ci, que indica a cilindrada em polegadas cúbicas. É um cupê utilitário na linha do Ford Ranchero, e a posição dele no material da Rockstar sugere que ele pertence ao personagem. Desde então, a Rockstar ligou o modelo à Vapid, depois de apresentá-lo primeiro com o nome Creado.","fam":"Cupê utilitário americano dos anos 70","alias":"Creado","medias":["ganado-retro-build","jason-s-safehouse-vehicles"],"perso":"jason","vuesDeclarees":["profil","detail"],"reel":"https://www.google.com/search?tbm=isch&q=Ford%20Ranchero%201970","reelNom":"Ford Ranchero 1970","slot":"americain","thumb":"/img/officiel/ganado-retro-build-480.webp"},{"id":"vapid-liberator","nom":"Liberator","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford Expedition de segunda geração em versão monster truck","src":"Primeiro trailer","txt":"Monster truck com pintura patriótica, fácil de reconhecer desde o primeiro trailer. A base é um SUV grande da Ford, montado sobre eixos de caminhão. Esse tipo de máquina quase nunca anda na estrada: vive em cima de um reboque entre uma exibição e outra, e é exatamente o tipo de detalhe com que a Rockstar adora brincar.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Expedition%20en%20monster%20truck","reelNom":"Ford Expedition em versão monster truck","search":"vapid liberator ford expedition deuxieme generation en monster truck","slot":"americain","thumb":"/img/schemas/vapid-liberator.svg"},{"id":"vapid-reclaimer","nom":"Reclaimer","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford Ranger T6 2019-2023","src":"Primeiro trailer","txt":"Picape média, o formato que voltou a ganhar mercado nos Estados Unidos diante das picapes grandes, que ficaram enormes. A Ranger desta geração era vendida como o meio-termo sensato: caçamba suficiente para trabalhar, compacta o bastante para estacionar na cidade.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Ranger%20T6","reelNom":"Ford Ranger T6","search":"vapid reclaimer ford ranger t6 2019-2023","slot":"americain","thumb":"/img/schemas/vapid-reclaimer.svg"},{"id":"vapid-sandking-xl","nom":"Sandking XL","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford Super Duty","src":"Primeiro trailer","search":"vapid sandking xl ford super duty","txt":"O Sandking XL é uma picape elevada sobre pneus gigantes, no estilo das Ford F-350 modificadas. Essa moda de levantar picapes é muito comum no sul dos Estados Unidos, onde é tanto uma questão de uso quanto de atitude. A picape aparece já no primeiro trailer.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Super%20Duty","reelNom":"Ford Super Duty","slot":"americain","thumb":"/img/schemas/vapid-sandking-xl.svg"},{"id":"bravado-bison","nom":"Bison","marque":"Bravado","cat":"van","st":"vu","insp":"Dodge Ram Quad Cab de quarta geração","src":"Segundo trailer","search":"bravado bison dodge ram quad cab quatrieme generation","txt":"O Bison é a picape de trabalho americana na sua forma mais comum: cabine dupla, caçamba curta, motor V8. Esse tipo de veículo é o mais vendido dos Estados Unidos, somando todas as categorias, há mais de quarenta anos. Ele aparece no segundo trailer.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Ram%20Quad%20Cab","reelNom":"Dodge Ram Quad Cab","slot":"americain","thumb":"/img/schemas/bravado-bison.svg"},{"id":"bravado-bison-1800","nom":"Bison 1800","marque":"Bravado","cat":"van","st":"vu","insp":"Ram 1500 DT","src":"Segundo trailer","txt":"Versão atual do Bison, com base na Ram 1500 da geração DT. Grade monumental, cabine dupla, suspensão a ar opcional: a picape americana moderna deixou de ser uma ferramenta de trabalho para virar um sedã familiar elevado, e os números de vendas mostram que a aposta deu certo.","search":"bravado bison 1800 ram 1500 dt","medias":["grassrivers-04"],"imageAlts":{"grassrivers-04":"Picape em primeiro plano em uma perseguição pelos pântanos de Grassrivers, GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Ram%201500%20DT","reelNom":"Ram 1500 DT","thumb":"/img/officiel/grassrivers-04-480.webp"},{"id":"bravado-bison-900-95","nom":"Bison 900 ’95","marque":"Bravado","cat":"van","st":"vu","insp":"Dodge Ram de segunda geração","src":"Primeiro trailer","txt":"O Bison na versão dos anos 90, baseada na Dodge Ram de segunda geração. Foi esse modelo que lançou a moda do capô alto e da grade com cara de caminhão, um desenho que virou o segmento inteiro de cabeça para baixo. Vinte anos depois, ainda dá para ver muitas delas por todo o sul dos Estados Unidos.","search":"bravado bison 900 ’95 dodge ram deuxieme generation","medias":["trailer-1-vehicles-053"],"imageAlts":{"trailer-1-vehicles-053":"Picape verde e seu ocupante, primeiro trailer oficial do GTA VI aos 00:53"},"reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Ram","reelNom":"Dodge Ram","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-053-480.webp"},{"id":"bravado-rumpo","nom":"Rumpo","marque":"Bravado","cat":"van","st":"vu","insp":"Ford E-Series","txt":"Furgão fechado, sem janelas laterais na parte de trás. O Rumpo está na série desde o GTA III e ocupa o papel da van de serviço genérica.","search":"bravado rumpo ford e-series","src":"Primeiro trailer","medias":["trailer-1-vehicles-064"],"imageAlts":{"trailer-1-vehicles-064":"Furgão branco à esquerda da cena filmada pela Weazel News, primeiro trailer do GTA VI por volta de 01:04"},"reel":"https://www.google.com/search?tbm=isch&q=Ford%20E-Series","reelNom":"Ford E-Series","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-064-480.webp"},{"id":"bravado-youga-classic","nom":"Youga Classic","marque":"Bravado","cat":"van","st":"vu","insp":"Ford Econoline de segunda geração","src":"Primeiro trailer","search":"bravado youga classic ford econoline deuxieme generation","txt":"O Youga Classic é a van americana dos anos 70, a dos surfistas e das bandas de rock em turnê. Essa categoria criou uma estética própria, com murais pintados com aerógrafo, janelas tipo escotilha e carpete por dentro. Dá para ver a van no primeiro trailer.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Econoline","reelNom":"Ford Econoline","slot":"americain","thumb":"/img/schemas/bravado-youga-classic.svg"},{"id":"brute-boxville","nom":"Boxville","marque":"Brute","cat":"van","st":"vu","insp":"GMC Step Van","src":"Capturas oficiais","search":"brute boxville gmc step van","txt":"O Boxville é o furgão de entrega com baú em forma de cubo, onipresente nas ruas americanas. O formato não tem nenhuma preocupação estética: é o máximo de espaço possível em cima de um chassi, com uma porta de correr na lateral. Ele aparece nas capturas publicadas pela Rockstar.","reel":"https://www.google.com/search?tbm=isch&q=GMC%20Step%20Van","reelNom":"GMC Step Van","slot":"americain","thumb":"/img/schemas/brute-boxville.svg"},{"id":"vapid-bobcat-xl","nom":"Bobcat XL","marque":"Declasse","cat":"van","st":"vu","insp":"Chevrolet C/K de quarta geração","src":"Primeiro trailer","search":"declasse bobcat xl chevrolet c/k quatrieme generation","txt":"Picape compacta de caçamba curta, o Bobcat XL ocupa o nicho do caminhãozinho pau para toda obra, o dos profissionais autônomos e dos serviços da prefeitura. Menos imponente que uma F-150, ele continua prático na cidade. A picape aparece no primeiro trailer.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20C%2FK","reelNom":"Chevrolet C/K","slot":"americain","thumb":"/img/schemas/vapid-bobcat-xl.svg"},{"id":"declasse-burrito","nom":"Burrito","marque":"Declasse","cat":"van","st":"vu","insp":"Chevrolet Express 1996-2002","src":"Primeiro trailer","search":"declasse burrito chevrolet express 1996-2002","txt":"O Burrito é o furgão de obra por excelência: fechado de chapa, sem vidros atrás, com banco dianteiro de três lugares. Na série, ele anda junto com os golpes, o que diz muito sobre sua capacidade de passar despercebido. A van aparece com clareza no primeiro trailer.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Express","reelNom":"Chevrolet Express","slot":"americain","thumb":"/img/schemas/declasse-burrito.svg"},{"id":"coach","nom":"Coach","marque":"Marca desconhecida","cat":"van","st":"comm","insp":null,"src":"Comparação da comunidade","search":"marque inconnue coach autocar longue distance americain","txt":"O ônibus rodoviário de longa distância faz parte da paisagem das estradas americanas, com seus bagageiros laterais e a faixa de vidros escurecidos. Ele liga as cidades que as companhias aéreas ignoram. Modelo não confirmado pela Rockstar para o GTA VI.","fam":"Ônibus rodoviário americano","reel":"https://www.google.com/search?tbm=isch&q=Autocar%20longue%20distance%20am%C3%A9ricain","reelNom":"Ônibus rodoviário americano","thumb":"/img/schemas/coach.svg"},{"id":"ford-econoline-4","nom":"Econoline","marque":"Marca desconhecida","cat":"van","st":"vu","insp":"Ford Econoline de quarta geração","src":"Segundo trailer","txt":"Van americana de bico curto, quarta geração. A Econoline foi a van de trabalho padrão nos Estados Unidos durante décadas: encanadores, floriculturas, bandas em turnê. Nome no jogo não divulgado.","search":"marque inconnue econoline ford econoline quatrieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Econoline","reelNom":"Ford Econoline","slot":"americain","thumb":"/img/schemas/ford-econoline-4.svg"},{"id":"moocher","nom":"Moocher","marque":"Marca desconhecida","cat":"van","st":"vu","insp":"Fleetwood Southwind 1985","src":"Capturas oficiais","txt":"Motorhome dos anos 80, carroceria quadrada e faixas decorativas da época. O nome, que quer dizer mais ou menos “aproveitador”, diz muito sobre o tipo de personagem que a Rockstar imagina ao volante. Esses veículos envelhecidos muitas vezes servem de moradia fixa na Flórida.","search":"marque inconnue moocher fleetwood southwind 1985","reel":"https://www.google.com/search?tbm=isch&q=Fleetwood%20Southwind%201985","reelNom":"Fleetwood Southwind 1985","thumb":"/img/schemas/moocher.svg"},{"id":"rexhall-rose-air","nom":"Rose Air","marque":"Marca desconhecida","cat":"van","st":"vu","insp":"Rexhall Rose Air","src":"Extended Look","txt":"Motorhome integral identificado no Extended Look. A Rexhall era uma fabricante californiana de motorhomes intermediários, que já fechou as portas. Nome no jogo não divulgado.","search":"marque inconnue rose air rexhall rose air","reel":"https://www.google.com/search?tbm=isch&q=Rexhall%20Rose%20Air","reelNom":"Rexhall Rose Air","thumb":"/img/schemas/rexhall-rose-air.svg"},{"id":"mercedes-sprinter-2","nom":"Sprinter","marque":"Marca desconhecida","cat":"van","st":"vu","insp":"Mercedes-Benz Sprinter","src":"Capturas oficiais","txt":"Van de alto padrão com teto alto, segunda geração. A Sprinter criou sozinha uma categoria: confiável o bastante para as frotas de empresas, espaçosa o bastante para virar motorhome. Nome no jogo não divulgado.","search":"marque inconnue sprinter mercedes-benz sprinter","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20Sprinter","reelNom":"Mercedes-Benz Sprinter","slot":"europeen","thumb":"/img/schemas/mercedes-sprinter-2.svg"},{"id":"chrysler-town-country","nom":"Town & Country","marque":"Marca desconhecida","cat":"van","st":"vu","insp":"Chrysler Town & Country","src":"Primeiro trailer","txt":"Minivan familiar de portas de correr, quinta geração. A Chrysler inventou esse formato em 1983 e o dominou por trinta anos, até o SUV varrê-lo do mapa. É o veículo das famílias de subúrbio, onipresente e totalmente invisível. Nome no jogo não divulgado.","search":"marque inconnue town & country chrysler town & country","reel":"https://www.google.com/search?tbm=isch&q=Chrysler%20Town%20%26%20Country","reelNom":"Chrysler Town & Country","slot":"americain","thumb":"/img/schemas/chrysler-town-country.svg"},{"id":"ford-transit-4","nom":"Transit","marque":"Marca desconhecida","cat":"van","st":"vu","insp":"Ford Transit de quarta geração","src":"Segundo trailer","txt":"Van europeia levada aos Estados Unidos nos anos 2010 para substituir a Econoline. Mais alta, mais estreita, mais econômica: a visão europeia do veículo utilitário, que acabou se impondo nos Estados Unidos. Nome no jogo não divulgado.","search":"marque inconnue transit ford transit quatrieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Transit","reelNom":"Ford Transit","slot":"americain","thumb":"/img/schemas/ford-transit-4.svg"},{"id":"ford-transit-cargo-4","nom":"Transit Cargo","marque":"Marca desconhecida","cat":"van","st":"vu","insp":"Ford Transit Cargo","src":"Primeiro trailer","txt":"A versão furgão da Transit, sem janelas laterais atrás. É a configuração dos entregadores e dos prestadores de serviço, a que oferece o máximo de espaço de carga e o mínimo de visão sobre o que vai lá dentro. Nome no jogo não divulgado.","search":"marque inconnue transit cargo ford transit cargo","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Transit%20Cargo","reelNom":"Ford Transit Cargo","slot":"americain","thumb":"/img/schemas/ford-transit-cargo-4.svg"},{"id":"vapid-speedo","nom":"Speedo","marque":"Vapid","cat":"van","st":"vu","insp":"Chevrolet Express, desde 2003","src":"Primeiro trailer","search":"vapid speedo chevrolet express, depuis 2003","txt":"O Speedo é um furgão compacto de cabine avançada, no estilo dos utilitários urbanos. O tamanho pequeno faz dele o veículo das entregas no centro da cidade, onde um Boxville não passa. Dá para vê-lo passando no primeiro trailer.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Express","reelNom":"Chevrolet Express","slot":"americain","thumb":"/img/schemas/vapid-speedo.svg"},{"id":"zirconium-journey","nom":"Journey","marque":"Zirconium","cat":"van","st":"vu","insp":"1979-1981 Fleetwood Pace Arrow","txt":"Motorhome classe A, o veículo dos aposentados que vão morar na Flórida e das viagens de estrada pela Costa Leste. A variante Journey II, mais recente, já está nesta base.","search":"zirconium journey 1979-1981 fleetwood pace arrow","src":"Capturas oficiais","reel":"https://www.google.com/search?tbm=isch&q=Fleetwood%20Pace%20Arrow","reelNom":"Fleetwood Pace Arrow","thumb":"/img/schemas/zirconium-journey.svg"},{"id":"zirconium-journey-ii","nom":"Journey II","marque":"Zirconium","cat":"van","st":"comm","insp":"Winnebago Chieftain","src":"Comparação da comunidade","search":"zirconium journey ii winnebago chieftain","txt":"O Journey II é um motorhome classe A, no estilo do Winnebago Chieftain. O nome da marca, Zirconium, brinca com a imitação: a zircônia é a pedra que parece diamante sem ser um. Para um veículo de férias de orçamento apertado, a piada é bem sacada. Esses motorhomes fazem parte da paisagem das estradas da Flórida, principalmente no inverno.","reel":"https://www.google.com/search?tbm=isch&q=Winnebago%20Chieftain","reelNom":"Winnebago Chieftain","slot":"americain","thumb":"/img/schemas/zirconium-journey-ii.svg"},{"id":"dinka-double-t","nom":"Double T","marque":"Dinka","cat":"moto","st":"vu","insp":"Honda CBR","src":"Primeiro trailer","search":"dinka double t honda cbr","txt":"A Double T é uma moto esportiva de estrada, carenada, na linha das Honda CBR. Esse tipo de moto busca um equilíbrio raro: potente o bastante para dar prazer, confortável o bastante para viagens longas. O primeiro trailer é a fonte de aparição escolhida para a Double T, cujo nome não foi divulgado.","reel":"https://www.google.com/search?tbm=isch&q=Honda%20CBR","reelNom":"Honda CBR","slot":"japonais","thumb":"/img/schemas/dinka-double-t.svg"},{"id":"dinka-enduro","nom":"Enduro","marque":"Dinka","cat":"moto","st":"officiel","insp":"Honda XL 350 e XR 500","src":"Edição Ultimate","vues":[],"credit":"Capture officielle Rockstar Games","search":"dinka enduro honda xl 350 et xr 500","txt":"A Enduro leva esse nome por causa da apresentação da edição Ultimate feita pela Rockstar, e nossa captura oficial mostra uma vista de perfil nítida: tanque verde-oliva com o logo da Dinka, banco preto gasto, paralama alto, pneus travados, escapamento elevado. É uma trail japonesa dos anos 80, dessas que serviam tanto na estrada quanto na terra. Outra captura a mostra estacionada na frente do esconderijo do Jason, o que sugere que ela é dele.","edition":"Ultimate Edition","medias":["dinka-enduro-motorcycle","jason-s-safehouse-vehicles"],"perso":"jason","vuesDeclarees":["profil"],"reel":"https://www.google.com/search?tbm=isch&q=Honda%20XL%20350","reelNom":"Honda XL 350","slot":"japonais","thumb":"/img/officiel/dinka-enduro-motorcycle-480.webp"},{"id":"lcc-avarus","nom":"Avarus","marque":"LCC","cat":"moto","st":"vu","insp":"Generica mostly-naked chopper","txt":"Chopper de garfo bem inclinado, guidão alto e roda dianteira fina. Um estilo que vem direto dos motoclubes americanos, e que combina com as longas retas do litoral.","search":"lcc avarus generica mostly-naked chopper","src":"Segundo trailer","medias":["trailer-2-motorcycle-143"],"imageAlts":{"trailer-2-motorcycle-143":"Jason pilota uma moto vermelha, na frente de um hidroavião, no Trailer 2 oficial do GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Generica%20mostly-naked%20chopper","reelNom":"Generica mostly-naked chopper","thumb":"/img/officiel/trailer-2-motorcycle-143-480.webp"},{"id":"maibatsu-manchez","nom":"Manchez","marque":"Maibatsu","cat":"moto","st":"vu","insp":"500cc KTM","txt":"Trail leve com roda dianteira de grande diâmetro, tão à vontade no asfalto quanto na terra. Útil nos pântanos e no interior, onde as estradas muitas vezes acabam.","search":"maibatsu manchez 500cc ktm","src":"Capturas oficiais","medias":["mount-kalaga-national-park-01","ptt-youngin-illegal-goods-store"],"imageAlts":{"mount-kalaga-national-park-01":"Duas motos off-road no Mount Kalaga National Park no GTA VI.","ptt-youngin-illegal-goods-store":"Moto de trilha decorada na loja PTT YOUNGIN$ de GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=500cc%20KTM","reelNom":"500cc KTM","thumb":"/img/officiel/mount-kalaga-national-park-01-480.webp"},{"id":"maibatsu-sanchez","nom":"Sanchez","marque":"Maibatsu","cat":"moto","st":"vu","insp":"Yamaha YZ450F 2006-2009","src":"Primeiro trailer","search":"maibatsu sanchez yamaha yz450f 2006-2009","txt":"A Sanchez aparece nos materiais oficiais sem que a Rockstar tenha divulgado o nome. A referência escolhida para esta moto é a Yamaha YZ450F dos anos 2006 a 2009. A identificação e a comparação vêm da comunidade; a fonte registrada é o primeiro trailer.","medias":["jason-and-lucia-09"],"imageAlts":{"jason-and-lucia-09":"Jason e Lucia em uma moto amarela identificada como Maibatsu Sanchez, perseguidos pela polícia."},"reel":"https://www.google.com/search?tbm=isch&q=Yamaha%20YZ450F","reelNom":"Yamaha YZ450F","slot":"japonais","thumb":"/img/officiel/jason-and-lucia-09-480.webp"},{"id":"yamaha-bws-125","nom":"BWs 125","marque":"Marca desconhecida","cat":"moto","st":"vu","insp":"Yamaha BWs 125","src":"Extended Look","txt":"O scooter urbano de pneus largos derivado do Yamaha BWs 125, aquele que você estaciona em qualquer lugar e que encara meio-fio sem reclamar. O nome no jogo não foi divulgado. O Extended Look o mostra no trânsito de um bairro residencial.","reel":"https://www.google.com/search?tbm=isch&q=Yamaha%20BWs%20125","reelNom":"Yamaha BWs 125","search":"marque inconnue bws 125 yamaha bws 125","slot":"japonais","thumb":"/img/schemas/yamaha-bws-125.svg"},{"id":"suzuki-gsx-r1000","nom":"GSX-R1000","marque":"Marca desconhecida","cat":"moto","st":"vu","insp":"Suzuki GSX-R1000","src":"Capturas oficiais","txt":"Uma esportiva japonesa copiada traço por traço da Suzuki GSX-R1000, sem nome no jogo nem fabricante fictício por enquanto. É o tipo de moto que você vê andando em bando pelas avenidas, acelerando tudo entre duas filas de carros. As capturas oficiais a mostram ao lado de Lucia.","medias":["lucia-caminos-03"],"imageAlts":{"lucia-caminos-03":"Lucia sentada em uma moto amarela, comparada a uma Suzuki GSX-R1000"},"reel":"https://www.google.com/search?tbm=isch&q=Suzuki%20GSX-R1000","reelNom":"Suzuki GSX-R1000","search":"marque inconnue gsx-r1000 suzuki gsx-r1000","slot":"japonais","thumb":"/img/officiel/lucia-caminos-03-480.webp"},{"id":"pomazoom-mobility-scooter","nom":"Pomazoom","marque":"Marca desconhecida","cat":"moto","st":"vu","insp":"Pride Maxima 3","src":"Capturas oficiais","txt":"O scooter elétrico de três rodas das calçadas e dos estacionamentos de supermercado, copiado de um Pride Maxima 3. A Rockstar o transformou em um veículo que dá para dirigir, chamado Pomazoom, com direito a cestinha na frente. As capturas oficiais o flagram atravessando um estacionamento.","medias":["leonida-keys-02"],"imageAlts":{"leonida-keys-02":"Condutor de uma scooter de mobilidade azul nas Leonida Keys, perto de um jacaré"},"reel":"https://www.google.com/search?tbm=isch&q=Pride%20Maxima%203","reelNom":"Pride Maxima 3","search":"marque inconnue pomazoom pride maxima 3","thumb":"/img/officiel/leonida-keys-02-480.webp"},{"id":"nagasaki-blazer-lifeguard","nom":"Blazer Lifeguard","marque":"Nagasaki","cat":"moto","st":"comm","insp":null,"src":"Comparação da comunidade","search":"nagasaki blazer lifeguard quad de plage en configuration de sauvetage","txt":"Versão de resgate do Blazer, com as cores dos salva-vidas. Esse tipo de quadriciclo é usado de verdade nas praias de Miami Beach para patrulhar e agir rápido na areia. A ligação com Leonida vem dos jogadores, já que nenhum material oficial foi identificado até agora.","fam":"Quadriciclo de praia em configuração de resgate","reel":"https://www.google.com/search?tbm=isch&q=Quad%20de%20plage%20en%20configuration%20de%20sauvetage","reelNom":"Quadriciclo de praia em configuração de resgate","thumb":"/img/schemas/nagasaki-blazer-lifeguard.svg"},{"id":"nagasaki-carbon-rs","nom":"Carbon RS","marque":"Nagasaki","cat":"moto","st":"vu","insp":"Ducati 1199, EBR 1190RS","txt":"Esportiva com carenagem integral e escapamento embaixo do banco. A Carbon RS é a moto mais rápida dos jogos anteriores, e uma das poucas tão eficientes em linha reta quanto impossíveis de pilotar no molhado.","search":"nagasaki carbon rs ducati 1199, ebr 1190rs","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Ducati%201199","reelNom":"Ducati 1199","slot":"europeen","thumb":"/img/schemas/nagasaki-carbon-rs.svg"},{"id":"pegassi-bati-801","nom":"Bati 801","marque":"Pegassi","cat":"moto","st":"vu","insp":"Ducati 848","src":"Artes oficiais","txt":"A esportiva da Pegassi, desenhada a partir da Ducati 848: carenagem afilada, tanque esculpido para os antebraços, posição de pilotagem que dobra o piloto ao meio. Ela aparece nas artes divulgadas pela Rockstar, o que já garante a presença dela no jogo antes mesmo de alguma cena mostrá-la em alta velocidade.","reel":"https://www.google.com/search?tbm=isch&q=Ducati%20848","reelNom":"Ducati 848","search":"pegassi bati 801 ducati 848","slot":"europeen","thumb":"/img/schemas/pegassi-bati-801.svg"},{"id":"pegassi-faggio","nom":"Faggio","marque":"Pegassi","cat":"moto","st":"vu","insp":"Piaggio Vespa","src":"Extended Look","search":"pegassi faggio piaggio vespa","txt":"O scooter é exatamente o oposto do resto do catálogo da Pegassi, e é isso que torna a piada engraçada. A Vespa, da qual ele herda a silhueta, é um objeto de design por si só, criada em 1946 para colocar a Itália de volta sobre rodas com o mínimo de aço. No Extended Look, ele aparece costurando entre duas filas de carros parados.","reel":"https://www.google.com/search?tbm=isch&q=Piaggio%20Vespa","reelNom":"Piaggio Vespa","slot":"europeen","thumb":"/img/schemas/pegassi-faggio.svg"},{"id":"pegassi-faggio-sport","nom":"Faggio Sport","marque":"Pegassi","cat":"moto","st":"vu","insp":"Piaggio Zip, Peugeot V-Clic e Kymco Agility 50","src":"Extended Look","search":"pegassi faggio sport piaggio zip, peugeot v-clic et kymco agility 50","txt":"A versão moderna do scooter da Pegassi, com o desenho anguloso dos pequenos scooters de 50 cc de hoje: carenagem de plástico, rodas sem raios, farol embutido no escudo frontal. Longe do charme retrô do Faggio clássico, é o veículo dos entregadores e dos estudantes do ensino médio, aquele que aparece por toda parte nas ruas de Vice City no Extended Look. A palavra Sport não promete nada: ele não vai deixar para trás nem a fila de carros que vai costurando.","reel":"https://www.google.com/search?tbm=isch&q=Piaggio%20Zip","reelNom":"Piaggio Zip","slot":"europeen","thumb":"/img/schemas/pegassi-faggio-sport.svg"},{"id":"principe-alvino-v1","nom":"Alvino V1","marque":"Principe","cat":"moto","st":"vu","insp":"Ducati Panigale V2 Sport Bike","src":"Capturas oficiais","search":"principe alvino v1 ducati panigale v2 sport bike","txt":"A Principe é a marca de motos italianas deste universo, no estilo da Ducati. A Alvino V1 é uma esportiva com quadro de treliça, uma arquitetura que é tanto a assinatura visual dessas máquinas quanto o segredo da sua rigidez. As capturas oficiais a mostram apoiada no descanso, com a carenagem intacta.","medias":["jason-duval-01"],"reel":"https://www.google.com/search?tbm=isch&q=Ducati%20Panigale%20V2%20Sport%20Bike","reelNom":"Ducati Panigale V2 Sport Bike","slot":"europeen","thumb":"/img/officiel/jason-duval-01-480.webp"},{"id":"principe-lectro","nom":"Lectro","marque":"Principe","cat":"moto","st":"vu","insp":"Ducati Streetfighter S, MV Agusta Brutale S","src":"Extended Look","txt":"Uma naked nervosa da Principe, algo entre a Ducati Streetfighter S e a MV Agusta Brutale S: guidão largo, quadro de treliça à mostra, nada para se proteger do vento. No Extended Look, ela acelera por uma estrada litorânea, com a roda dianteira quase saindo do chão.","reel":"https://www.google.com/search?tbm=isch&q=Ducati%20Streetfighter%20S","reelNom":"Ducati Streetfighter S","search":"principe lectro ducati streetfighter s, mv agusta brutale s","slot":"europeen","thumb":"/img/schemas/principe-lectro.svg"},{"id":"shitzu-pcj-600","nom":"PCJ-600","marque":"Shitzu","cat":"moto","st":"comm","insp":"Yamaha YZF-R6","src":"Comparação da comunidade","search":"shitzu pcj-600 yamaha yzf-r6","txt":"A PCJ-600 é a esportiva acessível da série, baseada na Yamaha YZF-R6. A categoria das seiscentas cilindradas foi por muito tempo a porta de entrada para as motos esportivas: potente o bastante para exigir do piloto, leve o bastante para continuar fácil de pilotar. Nenhuma confirmação oficial.","reel":"https://www.google.com/search?tbm=isch&q=Yamaha%20YZF-R6","reelNom":"Yamaha YZF-R6","slot":"japonais","thumb":"/img/schemas/shitzu-pcj-600.svg"},{"id":"western-nightblade","nom":"Nightblade","marque":"Western","cat":"moto","st":"vu","insp":"Harley-Davidson Night Rod Special","txt":"Cruiser de alta cilindrada, com tanque bojudo e banco baixo. A Western é a Harley do universo GTA.","search":"western nightblade harley-davidson night rod special","src":"Capturas oficiais","medias":["electric-fang-tattoo-01"],"imageAlts":{"electric-fang-tattoo-01":"Duas motos estacionadas em frente ao Electric Fang Tattoo no GTA VI; cruiser de pneu traseiro largo à direita."},"reel":"https://www.google.com/search?tbm=isch&q=Harley-Davidson%20Night%20Rod%20Special","reelNom":"Harley-Davidson Night Rod Special","slot":"americain","thumb":"/img/officiel/electric-fang-tattoo-01-480.webp"},{"id":"western-sovereign","nom":"Sovereign","marque":"Western","cat":"moto","st":"vu","insp":"Harley Davidson Road King","txt":"Cruiser cromada com para-lamas envolventes e para-brisa removível. A moto de turismo americana na sua versão mais clássica.","search":"western sovereign harley davidson road king","src":"Capturas oficiais","medias":["ambrosia-01"],"imageAlts":{"ambrosia-01":"Grupo de motoqueiros circulando por Ambrosia no GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Harley%20Davidson%20Road%20King","reelNom":"Harley Davidson Road King","slot":"americain","thumb":"/img/officiel/ambrosia-01-480.webp"},{"id":"western-zombie-chopper","nom":"Zombie Chopper","marque":"Western","cat":"moto","st":"vu","insp":"Harley Davidson Fat Bob Custom, Iron 883","src":"Segundo trailer","search":"western zombie chopper harley davidson fat bob custom, iron 883","txt":"A Zombie Chopper é uma custom americana de garfo longo, na tradição das Harley-Davidson Fat Bob Custom e Iron 883. O estilo chopper nasceu do costume de tirar de uma moto de série tudo o que não é indispensável, daí o nome. A Zombie Chopper aparece no segundo trailer, com uma identificação feita pela comunidade.","medias":["electric-fang-tattoo-01"],"imageAlts":{"electric-fang-tattoo-01":"Duas motos estacionadas em frente ao Electric Fang Tattoo no GTA VI; chopper à esquerda."},"reel":"https://www.google.com/search?tbm=isch&q=Harley%20Davidson%20Fat%20Bob%20Custom","reelNom":"Harley Davidson Fat Bob Custom","slot":"americain","thumb":"/img/officiel/electric-fang-tattoo-01-480.webp"},{"id":"buckingham-maverick","nom":"Maverick","marque":"Buckingham","cat":"helicoptere","st":"vu","insp":"Bell 206L Longranger","src":"Capturas oficiais","search":"buckingham maverick bell 206l longranger","txt":"O Maverick aparece na tela sem que a Rockstar divulgue o nome dele. Ele segue a arquitetura do Bell 206 LongRanger, versão alongada de um dos helicópteros civis mais produzidos do mundo: sete lugares, um único motor a turbina e uma confiabilidade que fez dele a aeronave preferida dos canais de notícias e das polícias.","medias":["mount-kalaga-national-park-02"],"imageAlts":{"mount-kalaga-national-park-02":"Helicóptero Maverick vermelho e branco voando diante das colinas, com um passageiro na porta aberta."},"reel":"https://www.google.com/search?tbm=isch&q=Bell%20206L%20Longranger","reelNom":"Bell 206L Longranger","slot":"americain","thumb":"/img/officiel/mount-kalaga-national-park-02-480.webp"},{"id":"buckingham-police-maverick","nom":"Police Maverick","marque":"Buckingham","cat":"helicoptere","st":"vu","insp":"Eurocopter AS350B","txt":"O helicóptero da polícia, com holofote e câmera. Ele entra em ação nos níveis de procurado mais altos e acrescenta uma pressão vinda de cima, que você não consegue enfrentar se ficar no chão.","search":"buckingham police maverick eurocopter as350b","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Eurocopter%20AS350B","reelNom":"Eurocopter AS350B","thumb":"/img/schemas/buckingham-police-maverick.svg"},{"id":"buckingham-supervolito","nom":"SuperVolito","marque":"Buckingham","cat":"helicoptere","st":"vu","insp":"Eurocopter EC145","src":"Primeiro trailer","search":"buckingham supervolito eurocopter ec145","txt":"Helicóptero executivo biturbina, o SuperVolito se baseia no Eurocopter EC145. Esse tipo de aeronave serve tanto para transportar executivos quanto para atender plataformas de petróleo no mar, um uso comum no golfo do México. O primeiro trailer mostra o helicóptero sobrevoando a baía em aproximação.","reel":"https://www.google.com/search?tbm=isch&q=Eurocopter%20EC145","reelNom":"Eurocopter EC145","thumb":"/img/schemas/buckingham-supervolito.svg"},{"id":"buckingham-swift","nom":"Swift","marque":"Buckingham","cat":"helicoptere","st":"vu","insp":"AgustaWestland AW109, Bell 222","src":"Capturas oficiais","search":"buckingham swift agustawestland aw109, bell 222","txt":"O Swift é um helicóptero de transporte particular, na linha do AgustaWestland AW109: silhueta esguia, trem de pouso retrátil, cabine bem acabada. É a aeronave de quem quer fugir dos engarrafamentos entre o centro empresarial e a marina. As capturas oficiais o mostram pousado em um heliponto no topo de um prédio.","reel":"https://www.google.com/search?tbm=isch&q=AgustaWestland%20AW109","reelNom":"AgustaWestland AW109","slot":"europeen","thumb":"/img/schemas/buckingham-swift.svg"},{"id":"buckingham-valkyrie","nom":"Valkyrie","marque":"Buckingham","cat":"helicoptere","st":"vu","insp":"Bell UH-1Y Venom, Bell 412","src":"Extended Look","txt":"O helicóptero de transporte da Buckingham, descendente direto do Bell UH-1 e de suas evoluções Venom e 412, com rotor de cauda carenado do tipo Fenestron. Portas laterais de correr e cabine aberta nas laterais. O Extended Look o acompanha em voo a baixa altitude.","reel":"https://www.google.com/search?tbm=isch&q=Bell%20UH-1Y%20Venom","reelNom":"Bell UH-1Y Venom","search":"buckingham valkyrie bell uh-1y venom, bell 412","slot":"americain","thumb":"/img/schemas/buckingham-valkyrie.svg"},{"id":"buckingham-buzzard","nom":"Buzzard","marque":"Nagasaki","cat":"helicoptere","st":"vu","insp":"AH-6 Little Bird","src":"Segundo trailer","search":"nagasaki buzzard ah-6 little bird","txt":"O Buzzard volta a aparecer no material oficial da Rockstar. É um helicóptero leve de dois lugares, baseado no AH-6 Little Bird, uma aeronave compacta usada pelas forças especiais americanas justamente por conseguir pousar em espaços apertados, inclusive no topo de prédios.","reel":"https://www.google.com/search?tbm=isch&q=AH-6%20Little%20Bird","reelNom":"AH-6 Little Bird","thumb":"/img/schemas/buckingham-buzzard.svg"},{"id":"nagasaki-police-buzzard","nom":"Police Buzzard","marque":"Nagasaki","cat":"helicoptere","st":"vu","insp":"MH-6 Little Bird","src":"Capturas oficiais","txt":"Versão policial do Buzzard, com uma pintura parecida com a das aeronaves do Miami Police Department. O MH-6 Little Bird que serve de modelo para ele é um helicóptero leve de origem militar, escolhido pelas polícias das grandes cidades pelo tamanho compacto e pelo custo de operação baixo.","reel":"https://www.google.com/search?tbm=isch&q=MH-6%20Little%20Bird","reelNom":"MH-6 Little Bird","search":"nagasaki police buzzard mh-6 little bird","thumb":"/img/schemas/nagasaki-police-buzzard.svg"},{"id":"western-sea-sparrow","nom":"Sea Sparrow","marque":"Western","cat":"helicoptere","st":"vu","insp":"Sikorsky S-300, antigo Hughes 300","src":"Primeiro trailer","search":"western sea sparrow sikorsky s-300, anciennement hughes 300","txt":"O Sea Sparrow é um helicóptero leve montado sobre flutuadores. A inspiração escolhida é o Sikorsky S-300, antes chamado Hughes 300. Nossa base o associa ao primeiro trailer, sem nome divulgado; os flutuadores permitem diferenciá-lo da versão terrestre.","medias":["cover-art-sea-sparrow"],"imageAlts":{"cover-art-sea-sparrow":"Helicóptero azul com flutuadores em uma ilustração da capa oficial do GTA VI"},"reel":"https://www.google.com/search?tbm=isch&q=Sikorsky%20S-300","reelNom":"Sikorsky S-300","thumb":"/img/officiel/cover-art-sea-sparrow-480.webp"},{"id":"buckingham-luxor","nom":"Luxor","marque":"Buckingham","cat":"avion","st":"vu","insp":"Learjet 45","src":"Extended Look","txt":"O jato executivo topo de linha da Buckingham, construído sobre um Learjet 45 como o Shamal, mas com um interior muito mais caprichado. É o avião das chegadas discretas em pista particular. No Extended Look, ele aparece em solo, com a escada de embarque aberta.","reel":"https://www.google.com/search?tbm=isch&q=Learjet%2045","reelNom":"Learjet 45","search":"buckingham luxor learjet 45","slot":"americain","thumb":"/img/schemas/buckingham-luxor.svg"},{"id":"buckingham-nimbus","nom":"Nimbus","marque":"Buckingham","cat":"avion","st":"vu","insp":"Cessna Citation X","src":"Primeiro trailer","txt":"Um jato executivo bimotor baseado no Cessna Citation X, que por muito tempo foi o avião civil mais rápido do mercado. Fuselagem fina, asas bem inclinadas para trás e motores presos na cauda. O primeiro trailer mostra o avião cruzando o céu de Leonida em grande altitude.","reel":"https://www.google.com/search?tbm=isch&q=Cessna%20Citation%20X","reelNom":"Cessna Citation X","search":"buckingham nimbus cessna citation x","slot":"americain","thumb":"/img/schemas/buckingham-nimbus.svg"},{"id":"buckingham-shamal","nom":"Shamal","marque":"Buckingham","cat":"avion","st":"vu","insp":"Learjet 45","src":"Capturas oficiais","search":"buckingham shamal learjet 45","txt":"A Rockstar mostra o avião nas imagens, mas guarda o nome a sete chaves. É um jato executivo baseado no Learjet 45: fuselagem estreita, motores na parte traseira e cauda em T. O Learjet definiu a categoria da aviação executiva nos anos 60, com uma proposta assumida de caça civil.","medias":["vice-city-01"],"reel":"https://www.google.com/search?tbm=isch&q=Learjet%2045","reelNom":"Learjet 45","slot":"americain","thumb":"/img/officiel/vice-city-01-480.webp"},{"id":"jobuilt-mammatus","nom":"Mammatus","marque":"JoBuilt","cat":"avion","st":"vu","insp":"Cessna 172 Skyhawk","src":"Capturas oficiais","search":"jobuilt mammatus cessna 172 skyhawk","txt":"O avião aparece nas imagens da Rockstar, mas a legenda não diz nada sobre ele. Pequeno monomotor de asa alta no estilo dos Cessna, é o tipo de avião que lota os aeródromos da Flórida: formação de pilotos, voos panorâmicos, viagens particulares. O nosso mapa registra vários desses aeródromos.","reel":"https://www.google.com/search?tbm=isch&q=Cessna%20172%20Skyhawk","reelNom":"Cessna 172 Skyhawk","slot":"americain","thumb":"/img/schemas/jobuilt-mammatus.svg"},{"id":"mammoth-dodo","nom":"Dodo","marque":"Mammoth","cat":"avion","st":"vu","insp":"De Havilland Canada DHC-2 Beaver","src":"Primeiro trailer","search":"mammoth dodo de havilland canada dhc-2 beaver","txt":"A Rockstar o mostra sem nunca chamá-lo pelo nome. É um hidroavião de asa alta inspirado no De Havilland Beaver, avião canadense projetado para decolar em pouco espaço e pousar na água. Entre as Keys, os pântanos e os inúmeros lagos e lagoas de Leonida, a utilidade é óbvia.","medias":["leonida-keys-01"],"reel":"https://www.google.com/search?tbm=isch&q=De%20Havilland%20Canada%20DHC-2%20Beaver","reelNom":"De Havilland Canada DHC-2 Beaver","slot":"europeen","thumb":"/img/officiel/leonida-keys-01-480.webp"},{"id":"mammoth-streamer216","nom":"Streamer216","marque":"Mammoth","cat":"avion","st":"vu","insp":"De Havilland Canada DHC-6 Twin Otter","src":"Segundo trailer","txt":"O bimotor de asa alta das ligações entre as ilhas, inspirado no DHC-6 Twin Otter da De Havilland Canada. Ele decola em pouco espaço, pousa em pistas improvisadas e leva uns quinze passageiros. O segundo trailer o mostra na aproximação final.","reel":"https://www.google.com/search?tbm=isch&q=De%20Havilland%20Canada%20DHC-6%20Twin%20Otter","reelNom":"De Havilland Canada DHC-6 Twin Otter","search":"mammoth streamer216 de havilland canada dhc-6 twin otter","slot":"europeen","thumb":"/img/schemas/mammoth-streamer216.svg"},{"id":"jet","nom":"Jet","marque":"Marca desconhecida","cat":"avion","st":"vu","insp":"Boeing 747-400, 747-8I","txt":"Avião comercial de passageiros. A presença dele no aeroporto internacional de Vice City é sobretudo cenográfica, mas a série sempre acabou deixando você pilotar esses aviões.","search":"marque inconnue jet boeing 747-400, 747-8i","src":"Segundo trailer","medias":["trailer-2-jet-037"],"imageAlts":{"trailer-2-jet-037":"Avião comercial de quatro motores acima das placas para o VCI Airport, segundo trailer do GTA VI por volta de 00:37."},"reel":"https://www.google.com/search?tbm=isch&q=Boeing%20747-400","reelNom":"Boeing 747-400","slot":"americain","thumb":"/img/officiel/trailer-2-jet-037-480.webp"},{"id":"western-company-duster","nom":"Duster","marque":"Western Company","cat":"avion","st":"vu","insp":"Stearman Model 75","src":"Capturas oficiais","search":"western company duster stearman model 75","txt":"O biplano aparece nas imagens oficiais, sem nome. É um biplano de pulverização agrícola, na linha do Stearman Model 75: estrutura treliçada, cabine aberta, trem de pouso fixo. Essas aeronaves, muitas vezes antigos aviões de treinamento militar reaproveitados, ainda sobrevoam as fazendas do sul dos Estados Unidos.","reel":"https://www.google.com/search?tbm=isch&q=Stearman%20Model%2075","reelNom":"Stearman Model 75","slot":"americain","thumb":"/img/schemas/western-company-duster.svg"},{"id":"xero-blimp","nom":"Blimp","marque":"Xero","cat":"avion","st":"vu","insp":"Goodyear Aerospace GZ-20","src":"Primeiro trailer","search":"xero blimp goodyear aerospace gz-20","txt":"O dirigível publicitário faz parte da paisagem americana, principalmente sobre estádios e grandes eventos. A Xero é a petroleira desse universo, e esse tipo de parceria publicitária é fiel à realidade. O dirigível aparece mesmo nas imagens; o nome dele, não.","reel":"https://www.google.com/search?tbm=isch&q=Goodyear%20Aerospace%20GZ-20","reelNom":"Goodyear Aerospace GZ-20","thumb":"/img/schemas/xero-blimp.svg"},{"id":"airboat-09","nom":"Airboat 09","marque":"Airgator","cat":"bateau","st":"vu","insp":"Aerobarco Diamondback Hunting & Fishing","src":"Capturas oficiais","search":"airgator airboat 09 hydroglisseur diamondback hunting & fishing","txt":"O aerobarco, com sua hélice aérea, é inseparável dos Everglades: casco chato, motor de avião na popa, fileiras de assentos elevados para o passeio turístico. Ele desliza sobre poucos centímetros de água e atravessa a vegetação aquática. O nome Airgator deixa clara a referência aos aligátores, os jacarés que essas máquinas levam os visitantes para ver.","medias":["grassrivers-01"],"reel":"https://www.google.com/search?tbm=isch&q=Hydroglisseur%20Diamondback%20Hunting%20%26%20Fishing","reelNom":"Aerobarco Diamondback Hunting & Fishing","thumb":"/img/officiel/grassrivers-01-480.webp"},{"id":"btn-delmar","nom":"Delmar","marque":"BTN","cat":"bateau","st":"vu","insp":"BTN Delmar","src":"Primeiro trailer","search":"btn delmar btn delmar","txt":"O Delmar é um barco de pesca costeira com cabine, do tipo que sai para passar o dia a partir das marinas da Flórida. É um barco feito para trabalhar: convés livre, porta-varas e borda livre alta. O primeiro trailer mostra o barco atracado ao lado de um píer.","fam":"Barco de pesca costeira com cabine","reel":"https://www.google.com/search?tbm=isch&q=BTN%20Delmar","reelNom":"BTN Delmar","thumb":"/img/schemas/btn-delmar.svg"},{"id":"crest-kayak","nom":"Kayak","marque":"Crest","cat":"bateau","st":"officiel","insp":"Caiaque Crescent, em várias versões","src":"Edição Ultimate","vues":[],"credit":"Capture officielle Rockstar Games","search":"crest kayak kayak crescent, plusieurs variantes","txt":"O caiaque é nomeado pela Rockstar, e nossa captura oficial o mostra em uso ao pôr do sol, com a marca Crest legível no casco. É um caiaque de mar do tipo sit-on-top, embarcação aberta especialmente adequada às águas quentes e rasas das Keys. Outra captura o mostra parado na frente do esconderijo de Jason.","edition":"Ultimate Edition","medias":["crest-kayak","jason-s-safehouse-vehicles","mount-kalaga-national-park-06"],"perso":"jason","imageAlts":{"mount-kalaga-national-park-06":"Caiaque Crest laranja num rio, sob uma ponte ferroviária do Mount Kalaga National Park."},"vuesDeclarees":["profil"],"reel":"https://www.google.com/search?tbm=isch&q=Kayak%20Crescent","reelNom":"Caiaque Crescent","slot":"americain","thumb":"/img/officiel/crest-kayak-480.webp"},{"id":"dinka-jetmax","nom":"Jetmax","marque":"Dinka","cat":"bateau","st":"comm","insp":null,"src":"Comparação da comunidade","search":"dinka jetmax hors-bord de sport a coque en v","txt":"O Jetmax é uma lancha esportiva, feita para a velocidade em águas calmas: casco aerodinâmico, cockpit baixo, motor superdimensionado. As baías abrigadas de Vice City são o terreno ideal. Modelo não confirmado pela Rockstar.","fam":"Lancha esportiva com casco em V","reel":"https://www.google.com/search?tbm=isch&q=Hors-bord%20de%20sport%20%C3%A0%20coque%20en%20V","reelNom":"Lancha esportiva com casco em V","thumb":"/img/schemas/dinka-jetmax.svg"},{"id":"nagasaki-marquis","nom":"Marquis","marque":"Dinka","cat":"bateau","st":"vu","insp":"Adjutor Yachts","src":"Segundo trailer","search":"dinka marquis adjutor yachts","txt":"O Marquis está catalogado como um veleiro de cruzeiro, tendo a Adjutor Yachts como inspiração. A marca usada na nossa base de dados é a Dinka. A aparição dele está ligada ao segundo trailer, sem nenhuma legenda oficial indicando o nome.","reel":"https://www.google.com/search?tbm=isch&q=Adjutor%20Yachts","reelNom":"Adjutor Yachts","slot":"europeen","thumb":"/img/schemas/nagasaki-marquis.svg"},{"id":"lure-predator-l35p","nom":"Predator L35P","marque":"Lure","cat":"bateau","st":"vu","insp":"Contender 25T","src":"Capturas oficiais","txt":"Barco de pesca com console central, arco e outriggers. A marca Lure Predator aparece nas capturas oficiais, o que faz dele um dos poucos barcos do jogo com nome. Também existe uma versão com pintura da polícia.","search":"lure predator l35p contender 25t","medias":["leonida-keys-05"],"imageAlts":{"leonida-keys-05":"Barcos reunidos nas Leonida Keys, com uma lancha da marca Lure Predator em primeiro plano."},"reel":"https://www.google.com/search?tbm=isch&q=Contender%2025T","reelNom":"Contender 25T","slot":"americain","thumb":"/img/officiel/leonida-keys-05-480.webp"},{"id":"lure-predator-l35p-police","nom":"Predator L35P da polícia","marque":"Lure","cat":"bateau","st":"vu","insp":"Contender 25T","src":"Capturas oficiais","txt":"Versão do Predator L35P com a pintura das forças de segurança: giroflex, faixas refletivas, holofote. A polícia marítima faz parte do dia a dia num estado com tantos canais e tanto litoral, e ela entra em ação nas perseguições na água.","search":"lure predator l35p de police contender 25t","medias":["shitzu-squalo-04"],"reel":"https://www.google.com/search?tbm=isch&q=Contender%2025T","reelNom":"Contender 25T","slot":"americain","thumb":"/img/officiel/shitzu-squalo-04-480.webp"},{"id":"lure-predator-s23","nom":"Predator S23","marque":"Lure","cat":"bateau","st":"vu","insp":"Contender 25 Bay","src":"Capturas oficiais","txt":"Pequeno barco de pesca para águas rasas, de sete metros, com casco de baixo calado pensado para baías e manguezais. É o formato mais comum entre os pescadores da Flórida, bem longe dos barcos de alto-mar.","search":"lure predator s23 contender 25 bay","medias":["leonida-keys-05"],"imageAlts":{"leonida-keys-05":"Barcos reunidos nas Leonida Keys, com uma lancha da marca Lure Predator em primeiro plano."},"reel":"https://www.google.com/search?tbm=isch&q=Contender%2025%20Bay","reelNom":"Contender 25 Bay","slot":"americain","thumb":"/img/officiel/leonida-keys-05-480.webp"},{"id":"azimut-85","nom":"Azimut 85","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Azimut 85","src":"Segundo trailer","txt":"Iate a motor de vinte e seis metros, na categoria das grandes embarcações de cruzeiro. O Azimut 85 vem de um estaleiro italiano cujos modelos lotam as marinas de Miami Beach. A Rockstar não divulgou o nome dele no jogo.","search":"marque inconnue azimut 85 azimut 85","reel":"https://www.google.com/search?tbm=isch&q=Azimut%2085","reelNom":"Azimut 85","slot":"europeen","thumb":"/img/schemas/azimut-85.svg"},{"id":"azimut-atlantis-45","nom":"Azimut Atlantis 45","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Azimut Atlantis 45","src":"Segundo trailer","txt":"Lancha de cruzeiro com cabine, de catorze metros, o meio-termo entre a lancha de passeio de um dia e o iate onde dá para passar dias a bordo. É o barco do dono bem de vida que sai nos fins de semana, e não o de um armador. Nome no jogo não divulgado.","search":"marque inconnue azimut atlantis 45 azimut atlantis 45","reel":"https://www.google.com/search?tbm=isch&q=Azimut%20Atlantis%2045","reelNom":"Azimut Atlantis 45","slot":"europeen","thumb":"/img/schemas/azimut-atlantis-45.svg"},{"id":"fishing-boat","nom":"Barco de pesca","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Steiger Craft 31 Miami","src":"Capturas oficiais","txt":"Barco de pesca costeiro com cabine fechada, de nove metros. O Steiger Craft cujas linhas ele copia leva literalmente o nome de Miami na sua designação. É a ferramenta do pescador profissional, não o brinquedo de quem passeia de barco no fim de semana.","search":"marque inconnue bateau de peche steiger craft 31 miami","reel":"https://www.google.com/search?tbm=isch&q=Steiger%20Craft%2031%20Miami","reelNom":"Steiger Craft 31 Miami","thumb":"/img/schemas/fishing-boat.svg"},{"id":"water-taxi","nom":"Táxi aquático","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Táxi aquático de Miami","src":"Extended Look","txt":"Barco fluvial de passageiros, visto no Extended Look. Miami tem uma rede real de táxis aquáticos entre o centro, a praia e as ilhas. A presença dele em Leonida sugere mais um meio de transporte, diferente do ônibus e do metrô elevado.","search":"marque inconnue bateau-taxi bateau-taxi de miami","reel":"https://www.google.com/search?tbm=isch&q=Bateau-taxi%20de%20Miami","reelNom":"Táxi aquático de Miami","thumb":"/img/schemas/water-taxi.svg"},{"id":"bavaria-sr33","nom":"Bavaria SR33","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Bavaria SR33","src":"Primeiro trailer","txt":"Lancha esportiva alemã de casco profundo, pensada mais para o mar agitado do que para a lagoa. A Bavaria é conhecida sobretudo pelos veleiros, e essa linha a motor é a aposta dela no mercado de lanchas esportivas. Nome no jogo não divulgado.","search":"marque inconnue bavaria sr33 bavaria sr33","reel":"https://www.google.com/search?tbm=isch&q=Bavaria%20SR33","reelNom":"Bavaria SR33","slot":"europeen","thumb":"/img/schemas/bavaria-sr33.svg"},{"id":"clarion","nom":"Clarion","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Cigarette 38 Top Gun","src":"Primeiro trailer","txt":"Lancha de corrida de casco bem afilado, na linha das Cigarette 38 Top Gun. Esses barcos têm uma história pesada em Miami: feitos para competições offshore, foram muito usados por traficantes nos anos 80 porque deixavam para trás as lanchas da alfândega. Difícil combinar mais com Vice City.","search":"marque inconnue clarion cigarette 38 top gun","reel":"https://www.google.com/search?tbm=isch&q=Cigarette%2038%20Top%20Gun","reelNom":"Cigarette 38 Top Gun","slot":"americain","thumb":"/img/schemas/clarion.svg"},{"id":"contender-39st","nom":"Contender 39ST","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Contender 39ST","src":"Capturas oficiais","txt":"Barco de pesca oceânica com console central, doze metros, quatro motores de popa na traseira. A Contender é um estaleiro do sul da Flórida cujos barcos são feitos para ir longe e rápido. Nome no jogo não divulgado.","search":"marque inconnue contender 39st contender 39st","reel":"https://www.google.com/search?tbm=isch&q=Contender%2039ST","reelNom":"Contender 39ST","slot":"americain","thumb":"/img/schemas/contender-39st.svg"},{"id":"crownline-275-ss","nom":"Crownline 275 SS","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Crownline 275 SS","src":"Primeiro trailer","txt":"Bowrider de lazer, oito metros, cockpit aberto e banco de proa. É o barco de família americano por excelência: esqui aquático, banho de mar e um drinque com o barco ancorado. Nome no jogo não divulgado.","search":"marque inconnue crownline 275 ss crownline 275 ss","reel":"https://www.google.com/search?tbm=isch&q=Crownline%20275%20SS","reelNom":"Crownline 275 SS","slot":"americain","thumb":"/img/schemas/crownline-275-ss.svg"},{"id":"crusader-boats-gfy","nom":"Crusader Boats GFY","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Crusader Boats GFY","src":"Primeiro trailer","txt":"Barco de mergulho de convés livre, dez metros, com plataforma traseira e suporte para cilindros. Os recifes da Flórida sustentam toda uma economia de passeios de mergulho, e esse é exatamente o tipo de barco que se aluga por dia. Nome no jogo não divulgado.","search":"marque inconnue crusader boats gfy crusader boats gfy","reel":"https://www.google.com/search?tbm=isch&q=Crusader%20Boats%20GFY","reelNom":"Crusader Boats GFY","thumb":"/img/schemas/crusader-boats-gfy.svg"},{"id":"shipyard-de-hoop-brion","nom":"De Hoop Brion","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Shipyard De Hoop Brion","src":"Capturas oficiais","txt":"Navio de apoio holandês, casco de trabalho e guindaste no convés. Não é nem um barco de lazer nem um barco de pesca, mas um desses navios utilitários que lotam os portos comerciais. Nome no jogo não divulgado.","search":"marque inconnue de hoop brion shipyard de hoop brion","reel":"https://www.google.com/search?tbm=isch&q=Shipyard%20De%20Hoop%20Brion","reelNom":"Shipyard De Hoop Brion","thumb":"/img/schemas/shipyard-de-hoop-brion.svg"},{"id":"ferry","nom":"Ferry","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Balsa de Fisher Island","src":"Extended Look","txt":"Balsa de passageiros e veículos, no modelo das que atendem Fisher Island, a ilha particular em frente a Miami Beach onde só se chega de barco. A presença dela sugere que uma parte do mapa de Leonida não tem ligação por estrada.","search":"marque inconnue ferry ferry de fisher island","reel":"https://www.google.com/search?tbm=isch&q=Ferry%20de%20Fisher%20Island","reelNom":"Balsa de Fisher Island","thumb":"/img/schemas/ferry.svg"},{"id":"frauscher-1017-gt","nom":"Frauscher 1017 GT","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Frauscher 1017 GT","src":"Primeiro trailer","txt":"Day boat austríaco de linhas muito marcadas, de dez metros. A Frauscher trabalha seus cascos como carrocerias de carro esportivo, o que lhe garante uma reputação única no mundo náutico. Nome no jogo não divulgado.","search":"marque inconnue frauscher 1017 gt frauscher 1017 gt","reel":"https://www.google.com/search?tbm=isch&q=Frauscher%201017%20GT","reelNom":"Frauscher 1017 GT","slot":"europeen","thumb":"/img/schemas/frauscher-1017-gt.svg"},{"id":"highfield-sport-900","nom":"Highfield Sport 900","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Highfield Sport 900","src":"Capturas oficiais","txt":"Bote semirrígido de nove metros, casco de alumínio e flutuadores infláveis. Esses barcos servem de apoio aos grandes iates e de transporte rápido entre o ancoradouro e a costa. Nome no jogo não divulgado.","search":"marque inconnue highfield sport 900 highfield sport 900","reel":"https://www.google.com/search?tbm=isch&q=Highfield%20Sport%20900","reelNom":"Highfield Sport 900","thumb":"/img/schemas/highfield-sport-900.svg"},{"id":"horizon-power-catamarans-pc60","nom":"Horizon PC60","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Horizon Power Catamarans PC60","src":"Primeiro trailer","txt":"Catamarã a motor de dezoito metros. O casco duplo oferece uma estabilidade e um espaço interno que um monocasco do mesmo comprimento não consegue alcançar, ao custo de uma largura que complica a atracação. Nome no jogo não divulgado.","search":"marque inconnue horizon pc60 horizon power catamarans pc60","reel":"https://www.google.com/search?tbm=isch&q=Horizon%20Power%20Catamarans%20PC60","reelNom":"Horizon Power Catamarans PC60","thumb":"/img/schemas/horizon-power-catamarans-pc60.svg"},{"id":"lurssen-73m-coral-ocean","nom":"Lürssen 73m","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Lürssen Coral Ocean","src":"Primeiro trailer","txt":"Superiate de setenta e três metros, o topo da hierarquia náutica do jogo. A Lürssen é o estaleiro alemão que constrói os maiores iates particulares do mundo. Um navio desses ancorado não é um veículo, é cenário, e um símbolo de status. Nome no jogo não divulgado.","search":"marque inconnue lurssen 73m lurssen coral ocean","reel":"https://www.google.com/search?tbm=isch&q=L%C3%BCrssen%20Coral%20Ocean","reelNom":"Lürssen Coral Ocean","thumb":"/img/schemas/lurssen-73m-coral-ocean.svg"},{"id":"cruise-ship","nom":"Navio de cruzeiro","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Royal Caribbean Voyager","src":"Capturas oficiais","txt":"Navio de cruzeiro, um dos maiores objetos móveis do jogo. O porto de Miami é o maior porto de cruzeiros do mundo, e esses navios fazem parte da silhueta da cidade tanto quanto os hotéis. É pouco provável que dê para pilotá-lo, mas a presença dele no porto estrutura o cenário.","search":"marque inconnue paquebot de croisiere royal caribbean voyager","reel":"https://www.google.com/search?tbm=isch&q=Royal%20Caribbean%20Voyager","reelNom":"Royal Caribbean Voyager","thumb":"/img/schemas/cruise-ship.svg"},{"id":"rb-s","nom":"RB-S","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Lancha da guarda costeira RB-S","src":"Capturas oficiais","txt":"Lancha de intervenção da guarda costeira, casco rígido e flutuadores, motores de popa. A Response Boat Small é a embarcação de patrulha padrão da US Coast Guard. Nome no jogo não divulgado.","search":"marque inconnue rb-s vedette garde-cotes rb-s","reel":"https://www.google.com/search?tbm=isch&q=Vedette%20garde-c%C3%B4tes%20RB-S","reelNom":"Lancha da guarda costeira RB-S","thumb":"/img/schemas/rb-s.svg"},{"id":"rb-s-ii","nom":"RB-S II","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Lancha da guarda costeira RB-S II","src":"Capturas oficiais","txt":"Segunda geração da lancha de patrulha da guarda costeira, mais longa e mais potente. Ela patrulha a costa e os canais, enquanto a polícia marítima fica nas águas interiores. Nome no jogo não divulgado.","search":"marque inconnue rb-s ii vedette garde-cotes rb-s ii","reel":"https://www.google.com/search?tbm=isch&q=Vedette%20garde-c%C3%B4tes%20RB-S%20II","reelNom":"Lancha da guarda costeira RB-S II","thumb":"/img/schemas/rb-s-ii.svg"},{"id":"riva-86-domino","nom":"Riva 86 Domino","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Riva 86 Domino","src":"Primeiro trailer","txt":"Iate italiano de vinte e seis metros. A Riva está para os barcos assim como a Ferrari está para os carros: um nome que serve de atalho para dizer riqueza e bom gosto. O Domino é a versão moderna dessa ideia, todo vidro e linhas tensas. Nome no jogo não divulgado.","search":"marque inconnue riva 86 domino riva 86 domino","reel":"https://www.google.com/search?tbm=isch&q=Riva%2086%20Domino","reelNom":"Riva 86 Domino","slot":"europeen","thumb":"/img/schemas/riva-86-domino.svg"},{"id":"sea-ray-350-sundancer","nom":"Sea Ray 350 Sundancer","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Sea Ray 350 Sundancer","src":"Primeiro trailer","txt":"Lancha de onze metros com cabine, cama e cozinha abaixo do convés. A Sea Ray é a maior fabricante americana de barcos de lazer, e a Sundancer é a sua linha mais vendida. Nome no jogo não divulgado.","search":"marque inconnue sea ray 350 sundancer sea ray 350 sundancer","reel":"https://www.google.com/search?tbm=isch&q=Sea%20Ray%20350%20Sundancer","reelNom":"Sea Ray 350 Sundancer","slot":"americain","thumb":"/img/schemas/sea-ray-350-sundancer.svg"},{"id":"sea-doo-rxt-x-300","nom":"Sea-Doo RXT-X 300","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Sea-Doo RXT-X 300","src":"Primeiro trailer","txt":"Jet ski de três lugares e muita potência, diferente do Seashark que já está nesta base de dados. O RXT-X é a versão esportiva da linha, a que passa dos cem quilômetros por hora. Nome no jogo não divulgado.","search":"marque inconnue sea-doo rxt-x 300 sea-doo rxt-x 300","reel":"https://www.google.com/search?tbm=isch&q=Sea-Doo%20RXT-X%20300","reelNom":"Sea-Doo RXT-X 300","slot":"americain","thumb":"/img/schemas/sea-doo-rxt-x-300.svg"},{"id":"skater-388","nom":"Skater 388","marque":"Marca desconhecida","cat":"bateau","st":"vu","insp":"Skater 388","src":"Primeiro trailer","txt":"Catamarã de corrida offshore, com um túnel central no casco que levanta o barco em alta velocidade. Essas máquinas passam dos duzentos quilômetros por hora e não servem para nada além de competir e se exibir. Nome no jogo não divulgado.","search":"marque inconnue skater 388 skater 388","reel":"https://www.google.com/search?tbm=isch&q=Skater%20388","reelNom":"Skater 388","slot":"americain","thumb":"/img/schemas/skater-388.svg"},{"id":"nagasaki-dinghy","nom":"Dinghy","marque":"Nagasaki","cat":"bateau","st":"vu","insp":"Rigid-hulled inflatable boat","src":"Segundo trailer","search":"nagasaki dinghy rigid-hulled inflatable boat","txt":"O Dinghy é um bote semirrígido: casco rígido com flutuadores infláveis nas bordas. É a embarcação de apoio por excelência, usada para chegar a um barco ancorado, para mergulho ou para intervenções rápidas. No segundo trailer, ele passa voando entre dois bancos de mangue.","reel":"https://www.google.com/search?tbm=isch&q=Rigid-hulled%20inflatable%20boat","reelNom":"Rigid-hulled inflatable boat","thumb":"/img/schemas/nagasaki-dinghy.svg"},{"id":"pegassi-speeder","nom":"Speeder","marque":"Pegassi","cat":"bateau","st":"vu","insp":"Coeur 290 Nighthawk, Cherubini Classic 20","src":"Primeiro trailer","search":"pegassi speeder coeur 290 nighthawk, cherubini classic 20","txt":"O Speeder é uma lancha de alto desempenho, na linha das Cigarette Racing. Esses barcos de casco em V profundo têm uma história especial em Miami: criados para as corridas offshore nos anos 70, logo foram adotados para outras atividades ao longo da costa da Flórida. No primeiro trailer, ele aparece a toda velocidade, com a proa fora da água.","reel":"https://www.google.com/search?tbm=isch&q=Coeur%20290%20Nighthawk","reelNom":"Coeur 290 Nighthawk","thumb":"/img/schemas/pegassi-speeder.svg"},{"id":"shitzu-longfin","nom":"Longfin","marque":"Shitzu","cat":"bateau","st":"comm","insp":"Lancha de pesca oceânica","txt":"Barco de pesca oceânica com cabine alta, arco e outriggers. O tipo de lancha que se aluga por dia em todo o litoral da Flórida, e que também serve, na ficção e na vida real, para outros negócios.","search":"shitzu longfin vedette de peche hauturiere","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Vedette%20de%20p%C3%AAche%20hauturi%C3%A8re","reelNom":"Lancha de pesca oceânica","thumb":"/img/schemas/shitzu-longfin.svg"},{"id":"shitzu-squalo","nom":"Squalo","marque":"Shitzu","cat":"bateau","st":"officiel","insp":"Chris-Craft Stinger 390x","src":"Edição Ultimate","vues":[],"credit":"Capture officielle Rockstar Games","search":"shitzu squalo chris-craft stinger 390x","txt":"O nome do Squalo aparece com todas as letras na apresentação da edição Ultimate, e as capturas oficiais não deixam dúvida: dá para ler o logo da Shitzu e o nome Squalo no casco e no para-brisa. Também dá para ver a pintura com estampa de folhas de palmeira, o convés de teca, as varas de pesca, um cilindro de mergulho e o número de registro VB 0522 05. O casco é o do Chris-Craft Stinger 390x, uma lancha esportiva dos anos 80 cuja silhueta baixa e proa pontuda são inseparáveis da imagem de Miami.","edition":"Ultimate Edition","medias":["shitzu-squalo-01","shitzu-squalo-02","shitzu-squalo-03","shitzu-squalo-04"],"vuesDeclarees":["face","profil","arriere","detail"],"reel":"https://www.google.com/search?tbm=isch&q=Chris-Craft%20Stinger%20390x","reelNom":"Chris-Craft Stinger 390x","slot":"americain","thumb":"/img/officiel/shitzu-squalo-01-480.webp"},{"id":"shitzu-tropic","nom":"Tropic","marque":"Shitzu","cat":"bateau","st":"vu","insp":"Sea Ray 300 Sundancer","src":"Primeiro trailer","search":"shitzu tropic sea ray 300 sundancer","txt":"O Tropic é uma lancha de cruzeiro com cabine, baseada no Sea Ray 300 Sundancer. É o barco de família americano por excelência: espaçoso o bastante para dormir a bordo, bom de mar o bastante para sair da baía, e vendido aos milhares em todo o litoral da Flórida. O tipo de embarcação que fica atracada atrás das casas à beira dos canais.","medias":["trailer-1-tropic-011"],"imageAlts":{"trailer-1-tropic-011":"Barco de lazer branco com cabine, visto de cima perto dos golfinhos, primeiro trailer do GTA VI por volta de 00:11."},"reel":"https://www.google.com/search?tbm=isch&q=Sea%20Ray%20300%20Sundancer","reelNom":"Sea Ray 300 Sundancer","slot":"americain","thumb":"/img/officiel/trailer-1-tropic-011-480.webp"},{"id":"speedophile-seashark","nom":"Seashark","marque":"Speedophile","cat":"bateau","st":"officiel","insp":"Sea-Doo GTX","src":"Segundo trailer","search":"speedophile seashark sea-doo gtx","txt":"Dá para ler o nome dele na lateral do casco no segundo trailer, quando Jason e Lucia cruzam a baía em cima dele a toda velocidade. É um jet ski de três lugares, baseado no Sea-Doo GTX: propulsão por turbina, casco de compósito, nenhuma hélice à mostra. O nome da marca é uma das piadas mais diretas do catálogo.","medias":["trailer-2-seashark-141"],"imageAlts":{"trailer-2-seashark-141":"Jason e Lucia em um jet ski verde; o nome Seashark é legível no casco, segundo trailer do GTA VI por volta de 02:21."},"reel":"https://www.google.com/search?tbm=isch&q=Sea-Doo%20GTX","reelNom":"Sea-Doo GTX","slot":"americain","thumb":"/img/officiel/trailer-2-seashark-141-480.webp"},{"id":"vortex-airboat","nom":"Airboat","marque":"Vortex","cat":"bateau","st":"vu","insp":"Aerobarco Panther Airboat","src":"Primeiro trailer","txt":"O aerobarco é a verdadeira novidade na água do GTA VI: nunca apareceu na série. Casco chato e uma hélice aérea enorme dentro de uma gaiola: ele desliza sobre poucos centímetros de água e passa onde nenhum barco passa. Esse tipo de embarcação é associado aos pântanos da Flórida. Como ele se sai nos Grassrivers ainda precisa ser conferido no jogo.","search":"vortex airboat hydroglisseur panther airboat","medias":["grassrivers-03"],"imageAlts":{"grassrivers-03":"Aerobarco visto de cima entre jacarés e plantas aquáticas em Grassrivers."},"reel":"https://www.google.com/search?tbm=isch&q=Hydroglisseur%20Panther%20Airboat","reelNom":"Aerobarco Panther Airboat","thumb":"/img/officiel/grassrivers-03-480.webp"},{"id":"bravado-bison-1800-police","nom":"Bison 1800 (Police)","marque":"Bravado","cat":"service","st":"vu","insp":"Ram 1500 DT","src":"Capturas oficiais","txt":"Versão de patrulha do Bison 1800. As polícias do sul da Flórida usam de verdade picapes desse tamanho para ocorrências fora do asfalto, nas trilhas das áreas alagadas ou nos acessos às praias, onde um carro de polícia comum atola.","reel":"https://www.google.com/search?tbm=isch&q=Ram%201500%20DT","reelNom":"Ram 1500 DT","search":"bravado bison 1800 (police) ram 1500 dt","thumb":"/img/schemas/bravado-bison-1800-police.svg"},{"id":"bravado-buffalo-stx-pursuit","nom":"Buffalo STX Pursuit","marque":"Bravado","cat":"service","st":"vu","insp":"Dodge Charger Pursuit","src":"Primeiro trailer","search":"bravado buffalo stx pursuit dodge charger pursuit","txt":"Versão de patrulha do Buffalo STX: barra de luzes, pintura da corporação, suspensão e arrefecimento reforçados. Nos Estados Unidos, as montadoras vendem de verdade versões policiais homologadas, com mecânica diferente da dos modelos civis. O primeiro trailer o mostra numa perseguição, com o giroflex ligado.","medias":["jason-and-lucia-09","vice-city-06"],"imageAlts":{"jason-and-lucia-09":"Jason e Lucia em uma moto amarela identificada como Maibatsu Sanchez, perseguidos pela polícia.","vice-city-06":"Buffalo STX da Vice Beach Police cercado de policiais e transeuntes em frente ao Ocean View Hotel."},"reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Charger%20Pursuit","reelNom":"Dodge Charger Pursuit","slot":"americain","thumb":"/img/officiel/jason-and-lucia-09-480.webp"},{"id":"bravado-gauntlet-interceptor","nom":"Gauntlet Interceptor","marque":"Bravado","cat":"service","st":"vu","insp":"Dodge Challenger em configuração policial","src":"Primeiro trailer","search":"bravado gauntlet interceptor dodge challenger en configuration de police","txt":"Versão de interceptação do Gauntlet, feita mais para perseguição do que para patrulha. As polícias americanas usam muscle cars nessa função com frequência, menos pela eficiência real do que pelo efeito dissuasivo. O primeiro trailer o mostra atravessado na pista, com as portas abertas.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Challenger%20en%20configuration%20de%20police","reelNom":"Dodge Challenger em configuração policial","slot":"americain","thumb":"/img/schemas/bravado-gauntlet-interceptor.svg"},{"id":"bravado-police-cruiser-buffalo","nom":"Police Cruiser (Buffalo)","marque":"Bravado","cat":"service","st":"vu","insp":"Dodge Charger","txt":"O Buffalo com pintura de patrulha urbana. As forças policiais de Leonida não usam o mesmo veículo em todo lugar: a cidade, a rodovia e o interior têm, cada um, a sua configuração.","search":"bravado police cruiser (buffalo) dodge charger","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Charger","reelNom":"Dodge Charger","slot":"americain","thumb":"/img/schemas/bravado-police-cruiser-buffalo.svg"},{"id":"brute-ambulance","nom":"Ambulance","marque":"Brute","cat":"service","st":"vu","insp":"Chevrolet Express 3500 chassi-cabine","src":"Extended Look","txt":"A ambulância de Leonida segue o formato americano de sempre: um chassi-cabine Chevrolet Express com um módulo de atendimento montado em cima, mais largo que a cabine. Nos Estados Unidos, essas carrocerias são instaladas por encarroçadoras especializadas, o que explica a quebra bem marcada na linha logo atrás das portas dianteiras.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Express%203500%20ch%C3%A2ssis-cabine","reelNom":"Chevrolet Express 3500 chassi-cabine","search":"brute ambulance chevrolet express 3500 chassis-cabine","slot":"americain","thumb":"/img/schemas/brute-ambulance.svg"},{"id":"brute-bus","nom":"Bus","marque":"Brute","cat":"service","st":"vu","insp":"New Flyer Xcelsior","txt":"Ônibus urbano de piso baixo. Há pontos de ônibus marcados no nosso mapa. Este veículo está catalogado em material oficial, enquanto as formas de uso pelo jogador ainda precisam ser verificadas no jogo.","search":"brute bus new flyer xcelsior","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=New%20Flyer%20Xcelsior","reelNom":"New Flyer Xcelsior","thumb":"/img/schemas/brute-bus.svg"},{"id":"brute-police-riot","nom":"Police Riot","marque":"Brute","cat":"service","st":"vu","insp":"Lenco BEAR","src":"Segundo trailer","search":"brute police riot lenco bear","txt":"O furgão blindado da tropa de choque aparece na tela, mas o nome dele continua desconhecido. Esses veículos, muitas vezes excedentes militares repassados às polícias locais, viraram tema de debate público nos Estados Unidos. A presença deles numa cidade como Vice City não é um detalhe qualquer.","medias":["trailer-2-police-riot-119"],"imageAlts":{"trailer-2-police-riot-119":"Furgão blindado preto de frente para Lucia, à esquerda do carro lançado pela explosão, segundo trailer do GTA VI por volta de 01:59."},"reel":"https://www.google.com/search?tbm=isch&q=Lenco%20BEAR","reelNom":"Lenco BEAR","slot":"americain","thumb":"/img/officiel/trailer-2-police-riot-119-480.webp"},{"id":"brute-rental-shuttle-bus","nom":"Rental Shuttle Bus","marque":"Brute","cat":"service","st":"vu","insp":"1996-2002 Chevrolet Express","txt":"Micro-ônibus de traslado, aquele que liga os terminais aos estacionamentos e aos hotéis. Um veículo que só chama a atenção nos aeroportos, e Leonida tem vários.","search":"brute rental shuttle bus 1996-2002 chevrolet express","src":"Segundo trailer","medias":["leonida-keys-02"],"imageAlts":{"leonida-keys-02":"Micro-ônibus branco à direita na cena de rua das Leonida Keys no GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Express","reelNom":"Chevrolet Express","slot":"americain","thumb":"/img/officiel/leonida-keys-02-480.webp"},{"id":"brute-stockade","nom":"Stockade","marque":"Brute","cat":"service","st":"vu","insp":"International 4700 Series","src":"Extended Look","txt":"O carro-forte, construído sobre o mesmo chassi International 4700 do Benson, mas com uma carroceria reforçada cheia de seteiras. É tanto um alvo de golpe quanto um veículo. No Extended Look, ele aparece parado em frente a uma agência bancária.","medias":["extended-look-stockade"],"imageAlts":{"extended-look-stockade":"Furgão blindado no meio da rua, quadro de An Extended Look"},"reel":"https://www.google.com/search?tbm=isch&q=International%204700%20Series","reelNom":"International 4700 Series","search":"brute stockade international 4700 series","thumb":"/img/officiel/extended-look-stockade-480.webp"},{"id":"brute-tipper-6-wheels","nom":"Tipper (6 rodas)","marque":"Brute","cat":"service","st":"vu","insp":"Chevrolet Kodiak, GMC TopKick","src":"Extended Look","txt":"O caminhão basculante de seis rodas da Brute, montado sobre a base do Kodiak e do TopKick: dois eixos traseiros, caçamba basculante e um porte entre o utilitário e o caminhão pesado. No Extended Look, ele aparece carregado, rodando numa estrada de terra de uma obra.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Kodiak","reelNom":"Chevrolet Kodiak","search":"brute tipper (6 roues) chevrolet kodiak, gmc topkick","slot":"americain","thumb":"/img/schemas/brute-tipper-6-wheels.svg"},{"id":"brute-utility-truck","nom":"Utility Truck","marque":"Brute","cat":"service","st":"vu","insp":"International 4700 Series","src":"Extended Look","txt":"O caminhão de manutenção da Brute, com o cesto aéreo recolhido sobre a carroceria e caixas de ferramentas nas laterais, montado sobre um chassi International 4700 Series. É o caminhão das equipes que consertam a rede elétrica. No Extended Look, ele aparece estacionado, com as patolas estabilizadoras abertas.","reel":"https://www.google.com/search?tbm=isch&q=International%204700%20Series","reelNom":"International 4700 Series","search":"brute utility truck international 4700 series","thumb":"/img/schemas/brute-utility-truck.svg"},{"id":"declasse-granger-taxi","nom":"Granger Taxi","marque":"Declasse","cat":"service","st":"vu","insp":"Chevrolet Suburban","src":"Extended Look","txt":"O Granger pintado de táxi, um Suburban enorme coroado pelo letreiro luminoso. É a corrida para vários passageiros, aquela que leva uma família inteira com a bagagem quando o sedã não dá conta. O Extended Look o deixa esperando na frente da entrada de um hotel.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Suburban","reelNom":"Chevrolet Suburban","search":"declasse granger taxi chevrolet suburban","slot":"americain","thumb":"/img/schemas/declasse-granger-taxi.svg"},{"id":"declasse-sheriff-suv","nom":"Sheriff SUV","marque":"Declasse","cat":"service","st":"comm","insp":"Chevrolet Tahoe de xerife","txt":"O SUV do gabinete do xerife, usado fora dos limites da cidade. A distinção entre polícia municipal e xerife de condado estrutura o mapa de Leonida tanto quanto a geografia.","search":"declasse sheriff suv chevrolet tahoe de sherif","src":"Comparação da comunidade","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Tahoe%20de%20sh%C3%A9rif","reelNom":"Chevrolet Tahoe de xerife","slot":"americain","thumb":"/img/schemas/declasse-sheriff-suv.svg"},{"id":"dundreary-police-landstalker-xl","nom":"Police Landstalker XL","marque":"Dundreary","cat":"service","st":"vu","insp":"Lincoln Navigator de quarta geração","src":"Extended Look","txt":"Grande SUV com as cores da polícia, derivado do Landstalker XL civil. Um veículo desse porte raramente serve para perseguições: as polícias americanas o reservam para supervisão, transporte de equipes e material volumoso. Visto no Extended Look.","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Navigator","reelNom":"Lincoln Navigator","search":"dundreary police landstalker xl lincoln navigator quatrieme generation","slot":"americain","thumb":"/img/schemas/dundreary-police-landstalker-xl.svg"},{"id":"hvy-airtug","nom":"Airtug","marque":"HVY","cat":"service","st":"vu","insp":"Clark CT30","src":"Extended Look","txt":"O pequeno trator de pista que puxa os carrinhos de bagagem entre o terminal e o porão do avião. A silhueta vem do Clark CT30, uma máquina de aeroporto em que ninguém repara, mas que circula por todo o pátio. No Extended Look, ele aparece trabalhando no aeroporto de Leonida.","reel":"https://www.google.com/search?tbm=isch&q=Clark%20CT30","reelNom":"Clark CT30","search":"hvy airtug clark ct30","thumb":"/img/schemas/hvy-airtug.svg"},{"id":"hvy-biff","nom":"Biff","marque":"HVY","cat":"service","st":"vu","insp":"Kenworth T800","src":"Extended Look","txt":"O caminhão basculante da HVY, montado sobre um chassi Kenworth T800 de cabine curta. Ele leva cascalho e terra de uma obra para outra, e é pesado o bastante para atravessar um cruzamento sem frear. No Extended Look, ele aparece num canteiro de obras.","reel":"https://www.google.com/search?tbm=isch&q=Kenworth%20T800","reelNom":"Kenworth T800","search":"hvy biff kenworth t800","thumb":"/img/schemas/hvy-biff.svg"},{"id":"hvy-forklift","nom":"Forklift","marque":"HVY","cat":"service","st":"vu","insp":"Yale GLP060VX","src":"Capturas oficiais","txt":"A empilhadeira dos armazéns e das docas de carga, copiada de uma Yale GLP060VX. Lenta, rente ao chão, incapaz de subir uma calçada, mas indispensável assim que é preciso mover um palete. As capturas oficiais a colocam numa zona industrial.","reel":"https://www.google.com/search?tbm=isch&q=Yale%20GLP060VX","reelNom":"Yale GLP060VX","search":"hvy forklift yale glp060vx","thumb":"/img/schemas/hvy-forklift.svg"},{"id":"jacksheepe-excavator","nom":"Excavator","marque":"Jacksheepe","cat":"service","st":"vu","insp":"Liebherr R954B HD-S, Samsung SE280LC-2","src":"Extended Look","txt":"A escavadeira de esteiras da Jacksheepe, uma mistura de uma Liebherr R954B HD-S com uma Samsung SE280LC-2. Torre giratória, braço articulado e uma caçamba larga o bastante para virar um sedã sem esforço. No Extended Look, ela aparece trabalhando numa terraplenagem.","reel":"https://www.google.com/search?tbm=isch&q=Liebherr%20R954B%20HD-S","reelNom":"Liebherr R954B HD-S","search":"jacksheepe excavator liebherr r954b hd-s, samsung se280lc-2","thumb":"/img/schemas/jacksheepe-excavator.svg"},{"id":"mtl-flatbed","nom":"Flatbed","marque":"JoBuilt","cat":"service","st":"vu","insp":"2004 Freightliner Century Class 112","src":"Extended Look","search":"jobuilt flatbed 2004 freightliner century class 112","txt":"O Flatbed é um caminhão de carroceria plana, usado para transportar veículos ou cargas volumosas. A nossa base de dados atribui esta versão à JoBuilt e a compara ao Freightliner Century Class 112 de 2004. No Extended Look, ele aparece carregando um carro destruído, com a plataforma inclinada.","reel":"https://www.google.com/search?tbm=isch&q=2004%20Freightliner%20Century%20Class%20112","reelNom":"2004 Freightliner Century Class 112","slot":"americain","thumb":"/img/schemas/mtl-flatbed.svg"},{"id":"jobuilt-hauler","nom":"Hauler","marque":"JoBuilt","cat":"service","st":"vu","insp":"Cavalos mecânicos Freightliner e Kenworth","src":"Capturas oficiais","search":"jobuilt hauler tracteurs routiers freightliner et kenworth","txt":"O Hauler é um cavalo mecânico, a parte da frente de uma carreta. A JoBuilt é a marca de máquinas pesadas do universo GTA. O porto de Vice City e as estradas que sobem para o norte de Leonida são o habitat natural desse tipo de veículo. As capturas oficiais o mostram engatado, pronto para pegar a estrada de novo.","reel":"https://www.google.com/search?tbm=isch&q=Tracteurs%20routiers%20Freightliner","reelNom":"Cavalos mecânicos Freightliner","slot":"americain","thumb":"/img/schemas/jobuilt-hauler.svg"},{"id":"jobuilt-phantom","nom":"Phantom","marque":"JoBuilt","cat":"service","st":"vu","insp":"Peterbilt 359 EXHD","src":"Primeiro trailer","search":"jobuilt phantom peterbilt 359 exhd","txt":"O Phantom é um cavalo mecânico de cabine longa, do tipo que cruza os Estados Unidos de costa a costa com uma cama atrás dos bancos. O primeiro trailer o mostra ultrapassando numa via expressa.","medias":["trailer-1-phantom-003"],"imageAlts":{"trailer-1-phantom-003":"Cavalo mecânico puxando uma carreta Patriot no meio da via expressa, primeiro trailer do GTA VI por volta de 00:03."},"reel":"https://www.google.com/search?tbm=isch&q=Peterbilt%20359%20EXHD","reelNom":"Peterbilt 359 EXHD","thumb":"/img/officiel/trailer-1-phantom-003-480.webp"},{"id":"jobuilt-phantom-custom","nom":"Phantom Custom","marque":"JoBuilt","cat":"service","st":"vu","insp":"GMC General 1984 com cabine leito carenada","src":"Capturas oficiais","search":"jobuilt phantom custom gmc general 1984 a cabine couchette carenee","txt":"Versão personalizada do Phantom: cromados, faróis extras, pintura caprichada. A cultura do caminhão decorado é uma tradição bem viva nos Estados Unidos, onde o caminhão muitas vezes pertence ao próprio motorista. As capturas oficiais o mostram parado numa área de descanso.","reel":"https://www.google.com/search?tbm=isch&q=GMC%20General%201984%20%C3%A0%20cabine%20couchette%20car%C3%A9n%C3%A9e","reelNom":"GMC General 1984 com cabine leito carenada","slot":"americain","thumb":"/img/schemas/jobuilt-phantom-custom.svg"},{"id":"jobuilt-rubble","nom":"Rubble","marque":"JoBuilt","cat":"service","st":"vu","insp":"Peterbilt 359 EXHD","txt":"Caminhão basculante de quatro eixos. As obras fazem parte da paisagem urbana de Vice City, com máquinas que circulam de verdade em vez de ficarem paradas.","search":"jobuilt rubble peterbilt 359 exhd","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Peterbilt%20359%20EXHD","reelNom":"Peterbilt 359 EXHD","thumb":"/img/schemas/jobuilt-rubble.svg"},{"id":"maibatsu-mule","nom":"Mule","marque":"Maibatsu","cat":"service","st":"vu","insp":"Mitsubishi Fuso Canter de sétima geração","txt":"Caminhão baú com cabine japonesa. O Mule é o caminhão de entregas e mudanças padrão da série.","search":"maibatsu mule mitsubishi fuso canter septieme generation","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Mitsubishi%20Fuso%20Canter","reelNom":"Mitsubishi Fuso Canter","slot":"japonais","thumb":"/img/schemas/maibatsu-mule.svg"},{"id":"airport-bus","nom":"Airport Bus","marque":"Marca desconhecida","cat":"service","st":"vu","src":"Extended Look","txt":"O ônibus de traslado que circula entre os terminais, com portas largas e um longo corredor central para os passageiros em pé, com a mala aos pés. A fabricante continua desconhecida e nenhum modelo real foi identificado até agora. No Extended Look, ele aparece atendendo o aeroporto de Vice City.","fam":"Ônibus de traslado de aeroporto","reel":"https://www.google.com/search?tbm=isch&q=Navette%20d%E2%80%99a%C3%A9roport","reelNom":"Ônibus de traslado de aeroporto","search":"marque inconnue airport bus navette d’aeroport","thumb":"/img/schemas/airport-bus.svg"},{"id":"amloco-ge-genesis","nom":"Amloco (GE Genesis)","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"Locomotiva GE Genesis","src":"Capturas oficiais","txt":"A Amloco, a companhia ferroviária de Leonida, puxa os seus trens de passageiros com uma locomotiva copiada da GE Genesis: frente arredondada, carroceria monobloco, pintura clara. É a máquina das viagens entre cidades, não do transporte de carga. As capturas oficiais a mostram parada na plataforma.","reel":"https://www.google.com/search?tbm=isch&q=Locomotive%20GE%20Genesis","reelNom":"Locomotiva GE Genesis","search":"marque inconnue amloco (ge genesis) locomotive ge genesis","thumb":"/img/schemas/amloco-ge-genesis.svg"},{"id":"dashound","nom":"Dashound","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"Ônibus rodoviário MCI Renaissance E, com a pintura da Greyhound","src":"Primeiro trailer","search":"marque inconnue dashound autocar mci renaissance e, livree greyhound","txt":"O ônibus intermunicipal Dashound é uma constante da série, transposição de uma empresa americana bem real cujo emblema é um galgo. Essa rede atende milhares de cidades que o avião e o trem abandonaram. O primeiro trailer o mostra rodando na rodovia, com a pintura completa à vista.","reel":"https://www.google.com/search?tbm=isch&q=Autocar%20MCI%20Renaissance%20E","reelNom":"Ônibus rodoviário MCI Renaissance E","thumb":"/img/schemas/dashound.svg"},{"id":"isuzu-elf-250","nom":"Elf 250","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"Isuzu Elf 250","src":"Extended Look","txt":"O pequeno caminhão de cabine avançada da Isuzu, onipresente nas entregas urbanas do mundo inteiro. Cabine sobre o motor, baú atrás, raio de giro minúsculo. O nome no jogo ainda não foi divulgado. Ele aparece no Extended Look.","reel":"https://www.google.com/search?tbm=isch&q=Isuzu%20Elf%20250","reelNom":"Isuzu Elf 250","search":"marque inconnue elf 250 isuzu elf 250","slot":"japonais","thumb":"/img/schemas/isuzu-elf-250.svg"},{"id":"vapid-caracara-lifeguard","nom":"Explorer Sport Trac (Lifeguard)","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"Ford Explorer Sport Trac","txt":"Picape de patrulha das praias, com pintura de resgate e o equipamento amarrado na traseira. O Sport Trac era um Explorer em que a Ford trocou o porta-malas por uma caçamba curta, fabricado de 2000 a 2010. Os postos de salva-vidas de Miami Beach usaram vários deles durante anos. Nome no jogo não divulgado.","search":"marque inconnue explorer sport trac (lifeguard) ford explorer sport trac","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Explorer%20Sport%20Trac","reelNom":"Ford Explorer Sport Trac","slot":"americain","thumb":"/img/schemas/vapid-caracara-lifeguard.svg"},{"id":"ford-f-series-tow-truck","nom":"F-Series guincho","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"Ford F-Series, configuração de guincho","src":"Extended Look","txt":"Um caminhão-guincho montado sobre uma base de Ford F-Series, com o braço hidráulico e o guincho de cabo à mostra na traseira. Por enquanto, a Rockstar não deu a ele nem nome no jogo nem fabricante fictício. No Extended Look, ele aparece em serviço, com um veículo batido na ponta do cabo.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-Series","reelNom":"Ford F-Series","search":"marque inconnue f-series depanneuse ford f-series, configuration depanneuse","slot":"americain","thumb":"/img/schemas/ford-f-series-tow-truck.svg"},{"id":"ford-f-series-flatbed","nom":"F-Series carroceria plana","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"Ford F-Series de sexta geração","src":"Primeiro trailer","txt":"Ford F-Series de sexta geração transformada em caminhão de carroceria plana: a caçamba original deu lugar a um assoalho liso para levar material volumoso. Uma adaptação comum na agricultura e na construção. Nome no jogo não divulgado.","search":"marque inconnue f-series plateau ford f-series sixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-Series","reelNom":"Ford F-Series","slot":"americain","thumb":"/img/schemas/ford-f-series-flatbed.svg"},{"id":"freight-train","nom":"Freight Train","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"Electro Motive Division, GE AC4400CW","txt":"Trem de carga. A malha ferroviária atravessa Leonida entre as zonas industriais, os portos e os centros urbanos, com passagens de nível que fecham a estrada de verdade.","search":"marque inconnue freight train electro motive division, ge ac4400cw","src":"Capturas oficiais","reel":"https://www.google.com/search?tbm=isch&q=Electro%20Motive%20Division","reelNom":"Electro Motive Division","thumb":"/img/schemas/freight-train.svg"},{"id":"chevrolet-kodiak-gmc-topkick","nom":"Kodiak ou Topkick","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"Chevrolet Kodiak, GMC Topkick","src":"Extended Look","txt":"O caminhão de médio porte da General Motors, vendido sob as duas marcas Chevrolet Kodiak e GMC Topkick, de capô curto e grade cromada. Nem nome no jogo nem fabricante próprio do universo foram atribuídos a ele. O Extended Look o apresenta em configuração de obra.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Kodiak","reelNom":"Chevrolet Kodiak","search":"marque inconnue kodiak ou topkick chevrolet kodiak, gmc topkick","slot":"americain","thumb":"/img/schemas/chevrolet-kodiak-gmc-topkick.svg"},{"id":"international-s-series-semi-truck","nom":"S-Series","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"International S-Series, cavalo mecânico","src":"Segundo trailer","txt":"Um cavalo mecânico International S-Series, fácil de reconhecer pela grade quadrada e pela cabine alta montada sobre o motor. Ele não recebeu nem nome no jogo nem fabricante fictício. O segundo trailer o mostra na rodovia, com a carreta engatada.","reel":"https://www.google.com/search?tbm=isch&q=International%20S-Series","reelNom":"International S-Series","search":"marque inconnue s-series international s-series, tracteur routier","thumb":"/img/schemas/international-s-series-semi-truck.svg"},{"id":"chevrolet-silverado-6500-hd","nom":"Silverado 6500 HD","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"Chevrolet Silverado 6500 HD","src":"Extended Look","txt":"Caminhão de porte médio, muito além da picape de uso particular: chassi-cabine destinado a carrocerias de trabalho, guincho, caçamba ou plataforma. Visto no Extended Look. O nome dele no jogo não foi divulgado.","search":"marque inconnue silverado 6500 hd chevrolet silverado 6500 hd","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Silverado%206500%20HD","reelNom":"Chevrolet Silverado 6500 HD","slot":"americain","thumb":"/img/schemas/chevrolet-silverado-6500-hd.svg"},{"id":"dodge-grand-caravan-taxi","nom":"Taxi Grand Caravan","marque":"Marca desconhecida","cat":"service","st":"vu","insp":"Dodge Grand Caravan 2011-2020, Chrysler Town & Country 2011-2016","src":"Capturas oficiais","txt":"A minivan com pintura de táxi, baseada na Dodge Grand Caravan e na sua prima, a Chrysler Town & Country. Em Miami, essas vans amarelas fazem as corridas até o aeroporto, com portas de correr e o porta-malas cheio de malas. As capturas oficiais mostram o táxi no trânsito.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Grand%20Caravan","reelNom":"Dodge Grand Caravan","search":"marque inconnue taxi grand caravan dodge grand caravan 2011-2020, chrysler town & country 2011-2016","slot":"americain","thumb":"/img/schemas/dodge-grand-caravan-taxi.svg"},{"id":"mtl-packer","nom":"Packer","marque":"MTL","cat":"service","st":"vu","insp":"1994 International 9000/9200","src":"Segundo trailer","search":"mtl packer 1994 international 9000/9200","txt":"O Packer é um caminhão-cegonha, usado para transportar veículos novos ou apreendidos. A carreta de dois andares faz dele um veículo inconfundível. Ele foi catalogado a partir do segundo trailer, com uma identificação da comunidade e sem nome divulgado pelo estúdio.","reel":"https://www.google.com/search?tbm=isch&q=1994%20International%209000%2F9200","reelNom":"1994 International 9000/9200","thumb":"/img/schemas/mtl-packer.svg"},{"id":"nagasaki-caddy","nom":"Caddy","marque":"Nagasaki","cat":"service","st":"vu","src":"Extended Look","txt":"O carrinho de golfe da Nagasaki, lento e indestrutível, volta num cenário feito sob medida para ele: os campos de golfe bem cuidados de Leonida. Nenhum modelo real específico está associado a ele, o que faz sentido para um veículo tão genérico. No Extended Look, ele aparece rodando entre dois buracos.","fam":"Carrinho de golfe","reel":"https://www.google.com/search?tbm=isch&q=Voiturette%20de%20golf","reelNom":"Carrinho de golfe","search":"nagasaki caddy voiturette de golf","thumb":"/img/schemas/nagasaki-caddy.svg"},{"id":"vapid-benson","nom":"Benson","marque":"Vapid","cat":"service","st":"vu","insp":"International 4700 Delivery Truck Chassis","txt":"Caminhão baú de porte médio, maior que o Mule e mais fácil de manobrar que uma carreta. Tradicionalmente, ele é usado nos golpes que precisam de espaço de carga.","search":"vapid benson international 4700 delivery truck chassis","src":"Extended Look","reel":"https://www.google.com/search?tbm=isch&q=International%204700%20Delivery%20Truck%20Chassis","reelNom":"International 4700 Delivery Truck Chassis","thumb":"/img/schemas/vapid-benson.svg"},{"id":"vapid-police-cruiser-interceptor","nom":"Police Cruiser (Interceptor)","marque":"Vapid","cat":"service","st":"vu","insp":"Ford Taurus","txt":"SUV de patrulha que virou o padrão das polícias americanas na década de 2010, no lugar do sedã. Porta-malas maior, vão livre do solo mais alto.","search":"vapid police cruiser (interceptor) ford taurus","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Taurus","reelNom":"Ford Taurus","slot":"americain","thumb":"/img/schemas/vapid-police-cruiser-interceptor.svg"},{"id":"vapid-police-cruiser-stanier-le","nom":"Police Cruiser (Stanier LE)","marque":"Vapid","cat":"service","st":"vu","insp":"Ford Crown Victoria","src":"Primeiro trailer","txt":"Carro de patrulha clássico, feito sobre a base do Stanier LE. O Crown Victoria equipou quase todas as polícias americanas durante vinte anos: chassi de longarinas, tração traseira, conserto barato depois de uma batida. Não confunda com o Police Ghost, que usa a mesma base com uma pintura discreta.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Crown%20Victoria","reelNom":"Ford Crown Victoria","search":"vapid police cruiser (stanier le) ford crown victoria","slot":"americain","thumb":"/img/schemas/vapid-police-cruiser-stanier-le.svg"},{"id":"vapid-police-ghost","nom":"Police Ghost (Stanier LE)","marque":"Vapid","cat":"service","st":"vu","insp":"Ford Crown Victoria","src":"Segundo trailer","txt":"O carro de patrulha clássico de Vice City, com base no Stanier. O Crown Victoria, que inspirou o visual dele, foi o carro de polícia padrão nos Estados Unidos por mais de vinte anos: tração traseira, chassi separado, praticamente indestrutível. O nome Ghost remete às unidades descaracterizadas, cuja pintura só dá para notar quando você já está perto demais.","search":"vapid police ghost (stanier le) ford crown victoria","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Crown%20Victoria","reelNom":"Ford Crown Victoria","slot":"americain","thumb":"/img/schemas/vapid-police-ghost.svg"},{"id":"ford-explorer-police","nom":"Police Montagne","marque":"Vapid","cat":"service","st":"vu","insp":"Ford Explorer de sexta geração","src":"Primeiro trailer","txt":"Desde os anos 2010, o SUV de patrulha substituiu o sedã na maioria das polícias americanas: porta-malas mais fundo, mais altura livre do solo, melhor visão sobre o trânsito. O Montagne da polícia segue essa silhueta e já aparece no primeiro trailer, nas ruas de Vice City.","search":"vapid police montagne ford explorer sixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Explorer","reelNom":"Ford Explorer","slot":"americain","thumb":"/img/schemas/ford-explorer-police.svg"},{"id":"vapid-taxi","nom":"Stanier Taxi","marque":"Vapid","cat":"service","st":"vu","insp":"Ford Crown Victoria","txt":"O Crown Victoria com pintura de táxi, quadriculado nas laterais e luminoso no teto. É o sedã de frota por excelência: porta-malas imenso, chassi de longarinas, mecânica indestrutível e manutenção barata. O primeiro trailer mostra o carro no trânsito de Vice City.","search":"vapid stanier taxi ford crown victoria","src":"Primeiro trailer","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Crown%20Victoria","reelNom":"Ford Crown Victoria","slot":"americain","thumb":"/img/schemas/vapid-taxi.svg"},{"id":"vapid-tow-truck","nom":"Tow Truck","marque":"Vapid","cat":"service","st":"vu","insp":"International Harvester série S dos anos 80","src":"Primeiro trailer","search":"vapid tow truck international harvester serie s des annees 80","txt":"O guincho de plataforma ou de lança faz parte da paisagem urbana americana, entre o socorro na estrada e a remoção de veículos estacionados em local proibido. A fonte usada para este Tow Truck é o primeiro trailer, onde o veículo não tem nome.","reel":"https://www.google.com/search?tbm=isch&q=International%20Harvester%20s%C3%A9rie%20S%20des%20ann%C3%A9es%2080","reelNom":"International Harvester série S dos anos 80","thumb":"/img/schemas/vapid-tow-truck.svg"},{"id":"endurex-race-bike","nom":"Race Bike","marque":"Endurex","cat":"divers","st":"vu","insp":"Pinarello Dogma","src":"Extended Look","txt":"A bicicleta de estrada de competição da Endurex, desenhada a partir de uma Pinarello Dogma: quadro de carbono com traseira assimétrica, guidão curvo, rodas de perfil alto. É a bicicleta mais rápida do jogo. No Extended Look, ela aparece com o ciclista pedalando no limite.","reel":"https://www.google.com/search?tbm=isch&q=Pinarello%20Dogma","reelNom":"Pinarello Dogma","search":"endurex race bike pinarello dogma","thumb":"/img/schemas/endurex-race-bike.svg"},{"id":"bmx","nom":"BMX","marque":"Marca desconhecida","cat":"divers","st":"vu","insp":"Bicicleta BMX","src":"Capturas oficiais","search":"marque inconnue bmx bmx bike","txt":"A bicicleta está lá, na imagem; o nome dela, em lugar nenhum. Essa bicicleta de rodas pequenas, nascida nos anos 70 quando crianças da Califórnia imitavam o motocross, virou esporte olímpico. Os parques com rampas de Miami fazem dela tanto um veículo urbano de verdade quanto um brinquedo.","reel":"https://www.google.com/search?tbm=isch&q=BMX%20bike","reelNom":"Bicicleta BMX","thumb":"/img/schemas/bmx.svg"},{"id":"cruiser","nom":"Cruiser","marque":"Marca desconhecida","cat":"divers","st":"vu","insp":"Beach cruiser, bicicleta de praia dos anos 30","src":"Capturas oficiais","search":"marque inconnue cruiser beach cruiser, velo de plage des annees 30","txt":"A bicicleta de praia de guidão alto e selim largo aparece nas imagens, sem legenda associada. É a cara da Flórida litorânea: sem marchas, posição ereta, pneus largos para rodar na areia compactada dos calçadões.","reel":"https://www.google.com/search?tbm=isch&q=Beach%20cruiser","reelNom":"Beach cruiser","thumb":"/img/schemas/cruiser.svg"},{"id":"lombike","nom":"LomBike","marque":"Marca desconhecida","cat":"divers","st":"vu","insp":"CitiBike Miami E-Bikes","src":"Capturas oficiais","search":"marque inconnue lombike citibike miami e-bikes","txt":"Bicicleta urbana utilitária, sem pretensão esportiva. Esse tipo de bicicleta serve sobretudo para trajetos curtos e entregas no bairro. Por enquanto, a presença dela não passa de uma suposição.","reel":"https://www.google.com/search?tbm=isch&q=CitiBike%20Miami%20E-Bikes","reelNom":"CitiBike Miami E-Bikes","thumb":"/img/schemas/lombike.svg"},{"id":"monorail-de-vice-city","nom":"Monotrilho de Vice City","marque":"Marca desconhecida","cat":"divers","st":"vu","insp":"Innovia APM 100, Metromover de Miami","src":"Segundo trailer","search":"marque inconnue monorail de vice city innovia apm 100, metromover de miami","txt":"O monotrilho urbano é uma particularidade de Miami, que opera desde os anos 80 uma rede elevada automática que atende o centro da cidade. Esse meio de transporte, raro nos Estados Unidos, faz parte da identidade visual da cidade. A nossa base de dados liga este monotrilho ao segundo trailer e adota o Innovia APM 100 do Metromover como inspiração.","reel":"https://www.google.com/search?tbm=isch&q=Innovia%20APM%20100","reelNom":"Innovia APM 100","thumb":"/img/schemas/monorail-de-vice-city.svg"},{"id":"scorcher","nom":"Scorcher","marque":"Marca desconhecida","cat":"divers","st":"vu","insp":"Saracen Zen, Rockshox Domain 180mm","src":"Capturas oficiais","search":"marque inconnue scorcher saracen zen, rockshox domain 180mm","txt":"Mountain bike com suspensão, o Scorcher é feito para trilhas e parques, mais do que para o asfalto. O Mount Kalaga National Park, que está no nosso mapa, é exatamente o tipo de lugar onde uma bike dessas faz todo o sentido. As capturas oficiais o mostram encostado em um muro baixo.","reel":"https://www.google.com/search?tbm=isch&q=Saracen%20Zen","reelNom":"Saracen Zen","thumb":"/img/schemas/scorcher.svg"},{"id":"electric-scooter","nom":"Patinete elétrico","marque":"Marca desconhecida","cat":"divers","st":"vu","insp":"BIRD One","src":"Extended Look","txt":"O patinete elétrico compartilhado, copiado do BIRD One que se vê largado em toda calçada de Miami. Plataforma baixa, guidão reto, pouca autonomia e velocidade limitada. O Extended Look mostra vários enfileirados num ponto de aluguel.","reel":"https://www.google.com/search?tbm=isch&q=BIRD%20One","reelNom":"BIRD One","search":"marque inconnue trottinette electrique bird one","thumb":"/img/schemas/electric-scooter.svg"},{"id":"vcia-train","nom":"VCIA Train","marque":"Marca desconhecida","cat":"divers","st":"comm","insp":null,"src":"Comparação da comunidade","search":"marque inconnue vcia train navette automatique d’aeroport","txt":"O trem que liga os terminais continua sendo uma hipótese da comunidade, sem nome conhecido. Esses trens sem condutor fazem parte da infraestrutura padrão dos grandes aeroportos americanos, e o aeroporto internacional de Vice City está no nosso mapa.","fam":"Trem automático de aeroporto","reel":"https://www.google.com/search?tbm=isch&q=Navette%20automatique%20d%E2%80%99a%C3%A9roport","reelNom":"Trem automático de aeroporto","thumb":"/img/schemas/vcia-train.svg"},{"id":"vcmm-train","nom":"VCMM Train","marque":"Marca desconhecida","cat":"divers","st":"vu","insp":"Metrorail de Miami","src":"Segundo trailer","search":"marque inconnue vcmm train metrorail de miami","txt":"O trem urbano de Vice City chama a atenção nas imagens, mas o nome dele não foi divulgado. Nosso mapa registra várias estações, entre elas a do aeroporto e a do Vice City Arts Center, o que sugere uma rede que atende a cidade de verdade, e não um simples cenário.","reel":"https://www.google.com/search?tbm=isch&q=Metrorail%20de%20Miami","reelNom":"Metrorail de Miami","thumb":"/img/schemas/vcmm-train.svg"}];
